// questionBankFico.js — Detailed Q&A for reading/learning (not MCQ), FICO module.
// Format matches src/data/questionBank.js: {q, a, type: 'conceptual'|'scenario'|'troubleshooting'}

const QUESTION_BANK_FICO = {
  'fi-day-1': {
    junior: [
      { q: 'What is the legal difference between "Company" and "Company Code" in SAP?', a: 'Company (international) is the consolidation entity used for group reporting and intercompany elimination — it can span several Company Codes. Company Code is the independent legal entity that produces its own balance sheet and P&L for external/statutory reporting.', type: 'conceptual' },
      { q: 'Why is Business Area described as "phased out" in S/4HANA?', a: 'Business Area was ECC\'s cross-Company-Code reporting unit, maintained via manual derivation rules and never integrated cleanly with the Universal Journal. S/4HANA replaces it with Segment, which derives automatically from Profit Center and posts natively to ACDOCA.', type: 'conceptual' },
      { q: 'What does Segment do that Business Area could not?', a: 'Segment posts as a native ACDOCA field on every line item, supports document splitting for segment-level balance sheets, and derives automatically from Profit Center — no manual substitution rule required as was common for Business Area.', type: 'conceptual' },
      { q: 'What is Credit Control Area used for?', a: 'The org unit that owns customer credit limits, scoring, and exposure monitoring; assigned to one or more Company Codes so credit risk can be managed at group level even across multiple legal entities.', type: 'conceptual' },
      { q: 'How is Credit Control Area different from Credit Segment (FSCM)?', a: 'Credit Control Area is the classic org structure assignment to Company Codes. Credit Segment is the object FSCM Credit Management actually scores and limits against; a mapping between the two must exist for FSCM checks to fire correctly.', type: 'conceptual' },
      { q: 'What is Functional Area and when do you need it?', a: 'Functional Area classifies P&L postings by business function (Production, Sales & Distribution, Administration, R&D) rather than by account nature. Needed when statutory or management reporting requires a cost-of-sales P&L format alongside, or instead of, the standard nature-of-expense format.', type: 'conceptual' },
      { q: 'How does Functional Area get populated on a posting?', a: 'Via default assignment on the cost object (cost center, order, WBS), or via substitution rules (GGB1) when no default exists — the same derivation logic used for cost objects generally.', type: 'conceptual' },
      { q: 'What is Controlling Area and how does it relate to Company Code?', a: 'Controlling Area is the CO org unit sitting above Company Code. One Controlling Area can be assigned 1:N Company Codes (cross-CC controlling), but each Company Code belongs to exactly one Controlling Area.', type: 'conceptual' },
      { q: 'What two conditions must hold for cross-Company-Code Controlling to work?', a: 'All Company Codes assigned to the same Controlling Area must share the same operating chart of accounts and the same fiscal year variant — without both, real-time FI-CO integration via the Universal Journal breaks.', type: 'conceptual' },
      { q: 'What are the two currency types every Company Code always has?', a: 'Company Code currency (local/statutory currency of that legal entity) and Group currency (shared consolidation currency) — two of the parallel currency fields stored on every ACDOCA line.', type: 'conceptual' },
      { q: 'How many total currency types can a Company Code carry, and where are they stored?', a: 'Up to 10 — the 2 fixed types (company code + group) plus up to 8 freely definable additional currency types — all stored as parallel columns on the same ACDOCA line item, not in separate currency tables.', type: 'conceptual' },
      { q: 'What does "ACDOCA stores currencies natively" actually mean for a consultant?', a: 'Currency translation for reporting doesn\'t require a separate reconciliation step between an index table and a totals table (as in ECC) — every posted line already carries all configured currency amounts, so multi-currency reports run directly off ACDOCA.', type: 'conceptual' },
      { q: 'What is a Fiscal Year Variant and what does it control?', a: 'It defines the number, start/end, and special periods of a company\'s fiscal year (calendar year, shifted year, or a 4-4-5 pattern with special periods 13-16 for adjustments). Assigned per Company Code, it drives posting period determination.', type: 'conceptual' },
      { q: 'Why can two Company Codes in the same Controlling Area not use different Fiscal Year Variants?', a: 'CO postings and period-end allocations run at Controlling Area level across all assigned Company Codes in the same posting period; mismatched fiscal year variants would misalign period boundaries and break real-time CO reporting.', type: 'conceptual' },
      { q: 'What are the two core org-design decisions made before any FICO configuration begins?', a: '(1) single Company Code vs. multiple Company Codes, and (2) one shared operating chart of accounts vs. separate operating charts of accounts per entity/country — both cascade into every later FI/CO build choice.', type: 'conceptual' },
      { q: 'Why does the number of Company Codes matter for intercompany complexity?', a: 'Every additional Company Code that trades with another creates an intercompany relationship needing IC billing/postings, transfer pricing, and month-end IC reconciliation — fewer CCs means fewer IC pairs to reconcile.', type: 'conceptual' },
      { q: 'What is the Fiori Launchpad\'s Space/Page structure?', a: 'Apps group into Pages (a themed collection of tiles, e.g. "Accounts Payable"); Pages group into Spaces (a broader work area, e.g. "Finance"); a user\'s assigned Business Role determines which Spaces and Pages — and therefore which apps — they see.', type: 'conceptual' },
      { q: 'How does a Business Role differ from a classic SAP GUI authorization role for a Fiori user?', a: 'A Business Role still carries the underlying authorization objects, but is additionally mapped to specific Fiori catalogs/spaces so the correct app tiles are surfaced; getting the mapping wrong means a user has authorization but no visible tile to launch the app.', type: 'conceptual' },
      { q: 'If a new FI user reports "I don\'t see the app I need" after go-live, what\'s usually the root cause?', a: 'Almost always a Business Role / Fiori catalog mapping gap rather than a missing authorization object — the user has the authorization, but the app tile isn\'t assigned to their role\'s space.', type: 'conceptual' },
      { q: 'Why is Enterprise Structure the first tab in the FICO build rather than G/L accounts?', a: 'Every downstream FI object (G/L master, document splitting, credit management, CO derivation) is scoped by Company Code, Controlling Area, or Segment — you cannot correctly configure account-level objects until the org structure they live inside is fixed.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client operates in 5 countries, wants one Controlling Area for global CO reporting, but two countries insist on locally-mandated non-calendar fiscal years. How do you resolve this?', a: 'You cannot mix fiscal year variants inside one Controlling Area. Either (a) split into two Controlling Areas along the fiscal-year boundary and accept a two-step CO consolidation, or (b) push the two countries toward the common variant if local law allows a shortened/adjustment bridge year. Get legal/tax sign-off before committing — this is a locked decision that is expensive to reverse post-go-live.', type: 'scenario' },
      { q: 'A Company Code was assigned the wrong Fiscal Year Variant and this is discovered during month 3, after two periods of postings. What is the remediation path?', a: 'Changing the fiscal year variant after postings exist is a major intervention with no simple reassignment. Typical remediation: a controlled fiscal-year-variant change project via SAP support/basis, with balance carryforward reconciliation. Prevention (locking this down at Phase A sign-off) is far cheaper than remediation.', type: 'troubleshooting' },
      { q: 'CFO wants segment-level balance sheets, but the client\'s ECC system used Business Area for years with no clean Profit-Center-to-Segment mapping. Migration approach?', a: 'Build the Profit Center → Segment derivation table first (Segment is derived from Profit Center by default), validate it reproduces the old Business Area reporting cuts, then activate document splitting on Segment as a splitting characteristic so segment-level balance sheets replace the old Business Area reports going forward.', type: 'scenario' },
      { q: 'Two Company Codes under one Controlling Area post to different operating charts of accounts by mistake. What breaks first?', a: 'Real-time FI-CO integration through the Universal Journal — CO allocations, assessments, and cost center postings spanning both Company Codes fail or post to incorrect/undefined accounts, because CO derivation logic assumes one shared operating chart of accounts across the Controlling Area.', type: 'troubleshooting' },
      { q: 'Client wants a single Credit Control Area to manage risk across 8 Company Codes in different currencies. What do you flag as a design risk?', a: 'Every open item, order, and delivery must convert to one common currency for the limit comparison to be meaningful. Flag the FX rate type and rate date used for exposure conversion up front — a volatile rate can make exposure look artificially high or low right at the limit threshold.', type: 'scenario' },
      { q: 'A new Fiori user has full SAP GUI-equivalent authorization but reports zero visible tiles after go-live. Diagnosis path?', a: 'Check Business Role → Catalog → Space/Page assignment before touching authorization objects — this is almost always a Fiori Launchpad content mapping gap, not an authorization gap, since the authorization objects are already confirmed granted.', type: 'troubleshooting' },
      { q: 'Client wants to consolidate three recently-acquired subsidiaries into group currency for board reporting within 60 days, without a full S/4 migration for each entity yet.', a: 'Add group currency as a parallel currency type on each subsidiary\'s existing Company Code configuration (if already on S/4/ACDOCA) so consolidation reporting can run off existing local postings immediately, while the full technical migration proceeds on its own longer timeline.', type: 'scenario' },
      { q: 'Post go-live, IC reconciliation between two Company Codes under different operating charts of accounts is taking days each month. Root cause and fix?', a: 'The different operating charts of accounts is the root cause — IC postings land on non-comparable GL accounts requiring manual mapping every cycle. Fix: harmonize to one operating chart of accounts (major project), or build a permanent GL-to-GL mapping table maintained centrally, not per reconciliation cycle.', type: 'troubleshooting' },
      { q: 'Client asks whether a single global Company Code can replace their 12-country legal entity structure to simplify FICO.', a: 'No — Company Code is the legal entity for statutory reporting; if the 12 countries are genuinely separate legal entities for tax/regulatory reasons, each needs its own Company Code. What can be simplified is shared operating chart of accounts and shared master data governance, not the Company Code count itself.', type: 'scenario' },
      { q: 'A Controlling Area shows correct data for 3 of its 4 assigned Company Codes, and one CC\'s cost center postings never appear in cross-CC CO reports.', a: 'First check whether that Company Code\'s fiscal year variant and operating chart of accounts genuinely match the other three (a common late-stage config drift), then confirm the CC-to-Controlling-Area assignment itself wasn\'t left on a default/test value during cutover.', type: 'troubleshooting' },
      { q: 'Board wants a functional (cost-of-sales) P&L in addition to the standard nature-of-expense P&L, discovered as a requirement after go-live.', a: 'Activate Functional Area as a derivation on all relevant cost objects going forward via default assignment/substitution. Historical periods without Functional Area populated will show gaps in the cost-of-sales view unless a retroactive derivation/reposting exercise is run — flag that cost and scope separately.', type: 'scenario' },
      { q: 'Client\'s Credit Control Area spans Company Codes with a shared customer base, but each CC wants independently visible (not group-summed) exposure per legal entity.', a: 'This is a Credit Segment design question inside FSCM Credit Management, not just Credit Control Area — map each Company Code to its own Credit Segment for entity-level visibility while still rolling up to one Credit Control Area for group risk oversight.', type: 'scenario' },
      { q: 'A consultant proposes deriving Segment via a hard-coded substitution rule instead of the standard Profit-Center-based default. What\'s the risk?', a: 'Bypassing the standard Profit-Center-derived default means every future Profit Center master data change requires a parallel manual update to the substitution rule — a maintenance and audit risk. Recommend the standard derivation unless there is a documented business reason it can\'t satisfy the requirement.', type: 'scenario' },
      { q: 'Client wants Company Code currency, Group currency, and a third "hard currency" for a hyperinflationary subsidiary, all reported simultaneously.', a: 'Configure the third currency as one of the up to 8 freely definable currency types on that Company Code — ACDOCA carries it natively alongside the two fixed types. Confirm the exchange rate type used reflects the hyperinflation-adjusted rate methodology required.', type: 'scenario' },
      { q: 'Fiscal year close for one Company Code is delayed because Controlling Area period-end allocations are blocked.', a: 'CO period locks operate at the Controlling Area level across all assigned Company Codes, so one CC\'s late transactional cleanup can block period-end allocation runs for every CC sharing that Controlling Area. Sequence CC-level close checklists so the slowest CC doesn\'t hold the whole Controlling Area hostage.', type: 'troubleshooting' },
      { q: 'Client with 40 Company Codes worries Fiori Business Role maintenance will not scale for go-live.', a: 'Design Business Roles around job function (AP clerk, AR clerk, controller) rather than per-Company-Code — Company Code-level restriction happens via authorization objects/org-level values inside a shared role template, not by duplicating a role per legal entity.', type: 'scenario' },
      { q: 'Auditor questions why the client\'s Segment-based balance sheet doesn\'t reconcile to the entity-level Company Code balance sheet.', a: 'Confirm document splitting\'s zero-balance clearing is active for Segment as a splitting characteristic — without it, segment-level balance sheets can fail to balance to zero even though the Company Code total is correct, since splitting (not just derivation) is what makes segment-level reporting balance.', type: 'troubleshooting' },
      { q: 'Client wants Credit Control Area assignment changed for a Company Code mid-year because of a reorg.', a: 'Reassigning Credit Control Area mid-year does not retroactively move historical credit exposure history. Document the cutover date, validate open orders/deliveries transfer correctly to the new Credit Control Area\'s exposure calculation, and communicate a temporary exposure visibility gap around the change date.', type: 'scenario' },
      { q: 'New consultant configures a second operating chart of accounts "just in case" for future flexibility, with no current business requirement.', a: 'Push back — an unused second operating chart of accounts adds ongoing maintenance (every account created/maintained twice) with zero current benefit. This is exactly the kind of speculative flexibility Enterprise Structure decisions should avoid; Part 1 locks scope precisely to prevent this drift.', type: 'scenario' },
      { q: 'How would you validate that Enterprise Structure decisions (Company Code count, Controlling Area assignment, chart of accounts strategy) are correct before Phase B content build starts?', a: 'Confirm sign-off against the governing spec\'s locked decisions, trace each Company Code to its Controlling Area and fiscal year variant, and run a dry-run cross-CC CO posting test — catching a structural error here is far cheaper than discovering it after 27 more tabs of content assume the structure is fixed.', type: 'scenario' },
    ],
  },
  'fi-day-2': {
    junior: [
      { q: 'What is a Fiscal Year Variant?', a: 'A configuration object defining the number, start/end dates, and special periods of a company\'s fiscal year — assigned per Company Code and driving posting period determination.', type: 'conceptual' },
      { q: 'What is the difference between year-dependent and year-independent fiscal year variants?', a: 'Year-independent: period start/end dates are identical every year (e.g. calendar year). Year-dependent: dates shift year to year (e.g. a retail 4-4-5 calendar), requiring maintenance for each fiscal year.', type: 'conceptual' },
      { q: 'What is a shortened fiscal year used for?', a: 'A transition fiscal year shorter than 12 months, typically used when a company changes its fiscal year end (e.g. moving from a March year-end to a December year-end).', type: 'conceptual' },
      { q: 'What are special periods 13-16?', a: 'Additional posting periods reserved purely for year-end adjustment entries (audit adjustments, tax true-ups) after the normal 12 periods have closed. They carry no calendar date range of their own.', type: 'conceptual' },
      { q: 'What does OB52 configure?', a: 'The Posting Period Variant — which posting periods are open, per account type (A=Asset, D=Customer, K=Vendor, S=G/L, M=Material), and the Posting Period Variant is then assigned to Company Codes.', type: 'conceptual' },
      { q: 'Why does OB52 control periods by account type instead of one blanket open/close?', a: 'Different sub-ledgers close on different timelines — e.g. AP may need to stay open a day longer than G/L for late invoice capture — so account-type-level control lets the close team sequence sub-ledger closes independently.', type: 'conceptual' },
      { q: 'What is a Period Authorization Group?', a: 'A further restriction layered on top of OB52 that limits posting into an otherwise-open period to a named subset of users — typically used to give only the close team access during the reconciliation window.', type: 'conceptual' },
      { q: 'What does a Document Type control?', a: 'Which account types can be posted (e.g. SA for G/L-only, KR for vendor invoice), which number range assigns the document number, and which reversal document type is used when the entry is reversed.', type: 'conceptual' },
      { q: 'What is the relationship between Document Type and Number Range?', a: 'Each Document Type is assigned to exactly one Number Range object, which determines whether document numbers are internally or externally assigned and the number interval used.', type: 'conceptual' },
      { q: 'What is a Posting Key?', a: 'A two-digit code entered before every line item that carries the debit/credit indicator and the account type being posted to (G/L, customer, vendor, asset, material).', type: 'conceptual' },
      { q: 'What is the classic G/L debit/credit posting key pair?', a: '40 (debit) and 50 (credit) — the most frequently tested posting key pair in FI interviews.', type: 'conceptual' },
      { q: 'What are the customer and vendor invoice/credit posting key pairs?', a: 'Customer: 01 (invoice/debit) and 11 (credit). Vendor: 21 (invoice/credit) and 31 (credit memo/debit). 25/35 covers vendor debit/credit for clearing transactions.', type: 'conceptual' },
      { q: 'What is a Field Status Variant?', a: 'A configuration object assigned at Company Code level that groups together all the Field Status Groups used by that Company Code\'s G/L accounts.', type: 'conceptual' },
      { q: 'What is a Field Status Group and where is it assigned?', a: 'A set of rules controlling whether each entry field (cost center, text, assignment number, etc.) is suppressed, displayed, required, or optional. It is assigned to an individual G/L account master record.', type: 'conceptual' },
      { q: 'What controls field behavior on vendor/customer master data, parallel to the G/L Field Status Group?', a: 'The Account Group assigned to the vendor or customer (or Business Partner role in S/4) — it defines which master data fields are suppressed, required, or optional for that grouping.', type: 'conceptual' },
      { q: 'What is the priority order when Posting Key, Field Status Group, and Account Group disagree on a field\'s status?', a: 'Suppress > Display > Required > Optional. Whichever control marks the field as Suppress wins outright, even if another control marks it Required.', type: 'conceptual' },
      { q: 'Give a concrete example of the field status conflict rule in action.', a: 'If the Field Status Group on a G/L account marks "Cost Center" as Required but the posting key used marks it Suppress, the cost center field will not appear on the entry screen at all — Suppress overrides Required.', type: 'conceptual' },
      { q: 'What is a Tolerance Group?', a: 'A configuration object setting maximum posting amounts and acceptable payment differences. G/L tolerance groups apply at document/line-item level; Employee tolerance groups are assigned per user.', type: 'conceptual' },
      { q: 'How is an Employee Tolerance Group used in practice?', a: 'It caps the payment difference (over/under payment) an individual user can post and write off without triggering an escalation or blocking the transaction — commonly set lower for junior clerks than senior clerks.', type: 'conceptual' },
      { q: 'What is the User Assignment to Tolerance Groups?', a: 'The mapping table (OB57 in classic config) that assigns each individual SAP user ID to one employee tolerance group, determining which limits apply when that specific person posts.', type: 'conceptual' },
      { q: 'Why is Document Type sometimes assigned to a specific Ledger Group in S/4HANA?', a: 'To support ledger-specific postings (e.g. an adjustment relevant only to a local statutory ledger, not the leading ledger) — the document type-to-ledger group assignment controls which ledgers a posting reaches.', type: 'conceptual' },
      { q: 'Do posting keys still exist in S/4HANA Fiori apps?', a: 'Yes — posting keys remain part of the underlying data model and document structure, but most Fiori apps (e.g. Post General Journal Entries) abstract them behind a simplified debit/credit selection rather than asking the user to type a two-digit code.', type: 'conceptual' },
      { q: 'What happens if a posting period is closed for account type K (vendor) but open for S (G/L)?', a: 'Vendor invoice postings will be blocked with a period-closed error while direct G/L postings continue to succeed — this is intentional, sequencing sub-ledger closes ahead of the final G/L close.', type: 'conceptual' },
      { q: 'What is the practical difference between Field Status Group and Account Group from a build perspective?', a: 'Field Status Group governs G/L account line-item entry fields; Account Group governs vendor/customer master data fields. They solve the same kind of problem (screen field control) but for two different master data domains.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A close-period team reports they can post to a period that regular users cannot access, even though OB52 shows the period as closed for everyone.', a: 'This is exactly what Period Authorization Group is designed to do — it grants a named subset of users continued access to a period that OB52 has otherwise closed for general posting, typically during the reconciliation window.', type: 'conceptual' },
      { q: 'Vendor invoices for the prior month keep failing to post the day after month-end close, but the close team insists the period should still be open for AP.', a: 'Check OB52\'s account-type-specific settings — if the posting period variant closed account type K (vendor) at month-end while the close team assumed a grace period, the fix is either extending the K period window intentionally or correcting the team\'s expectation, not just re-opening blindly.', type: 'troubleshooting' },
      { q: 'A reversal creates a document under an unexpected document type, breaking a downstream report filter that only looks for the original type.', a: 'Check the original document type\'s configured reversal document type assignment — reversal type is set per originating document type, and a misconfiguration here (e.g. mapping SA reversals to a generic AB type) produces exactly this symptom.', type: 'troubleshooting' },
      { q: 'One non-leading ledger is missing certain adjustment postings that appear correctly in the leading ledger.', a: 'Check whether the document type used for those adjustments is restricted to a specific ledger group — if it\'s scoped only to the leading ledger group, non-leading ledgers will never receive the posting even though no error is thrown.', type: 'troubleshooting' },
      { q: 'Field marked Required by the Field Status Group is not appearing on the entry screen at all, and users cannot understand why the "required" field is invisible.', a: 'Check the posting key used for that line — if it marks the same field Suppress, Suppress always overrides Required in the three-way conflict, hiding the field entirely rather than blocking with a "required field missing" error.', type: 'troubleshooting' },
      { q: 'Client wants junior AP clerks capped at a lower payment write-off tolerance than senior clerks without duplicating Company Code configuration.', a: 'Create two Employee Tolerance Groups (junior/senior) with different payment-difference limits, both still referencing the same underlying G/L tolerance group, and assign each user to their appropriate employee group via the user-assignment table — no Company Code duplication needed.', type: 'scenario' },
      { q: 'A new Fiori-only FI user cannot find the posting key input field they remember from SAP GUI training, and assumes something is broken.', a: 'Explain that posting keys still exist in the data model but Fiori apps (e.g. Post General Journal Entries) present a simplified debit/credit selector instead of the raw two-digit code — the underlying posting still generates the correct posting key, just abstracted from the user.', type: 'conceptual' },
      { q: 'Client wants two Company Codes to share identical field status behavior on their G/L accounts without maintaining Field Status Groups twice.', a: 'Assign both Company Codes to the same Field Status Variant — Field Status Groups live at the variant level, so any Company Code pointing to that variant automatically shares the same field control rules.', type: 'scenario' },
      { q: 'Auditor flags that a specific cost center field was blank on several postings that should have required it per policy.', a: 'Trace the posting keys used on those line items — if any of them carry a Suppress status for the cost center field, that overrides the Field Status Group\'s Required setting, and no system error would have surfaced to flag it at entry time. This is a config gap, not a user error.', type: 'troubleshooting' },
      { q: 'Design a period-close sequence so that AP, AR, and G/L do not all close simultaneously, but each sub-ledger has adequate cutoff time.', a: 'Use OB52\'s account-type-specific period controls: close K (vendor) and D (customer) first at a defined cutoff, leave S (G/L) open slightly longer for consolidation postings, then close S last — sequencing sub-ledger closes ahead of the final G/L close is the standard pattern.', type: 'scenario' },
      { q: 'Client wants to prevent all users except three named controllers from posting to special periods 13-16.', a: 'Assign a dedicated Period Authorization Group scoped to special periods only, and grant that group\'s authorization to just the three controllers — this restricts adjustment postings to the intended small group while leaving normal period access unaffected.', type: 'scenario' },
      { q: 'A vendor invoice document type\'s number range was exhausted mid-year, and new invoices cannot be posted.', a: 'Extend the number range interval for that document type\'s assigned number range object before the next posting — this is a maintenance task (SNRO/FBN1-equivalent), not a redesign, but should be caught proactively via periodic number range utilization monitoring rather than reactively after postings fail.', type: 'troubleshooting' },
      { q: 'Client wants a shortened fiscal year to align a newly acquired subsidiary\'s year-end with the parent\'s calendar year.', a: 'Configure a one-time shortened fiscal year variant for the transition period (e.g. April to December) for that Company Code, then switch to the parent\'s standard year-independent variant going forward — document the one-time transition clearly for auditors reconciling the short period.', type: 'scenario' },
      { q: 'Two Company Codes under the same Controlling Area use different Fiscal Year Variants — what breaks in CO reporting?', a: 'CO period-end allocations and cross-CC cost reporting assume aligned period boundaries across the Controlling Area; mismatched fiscal year variants misalign periods and produce incorrect or partial cross-CC CO results — this should have been caught during Enterprise Structure sign-off (FI Day 1).', type: 'troubleshooting' },
      { q: 'A consultant proposes giving every user the same, most-permissive Employee Tolerance Group "to avoid support tickets."', a: 'Push back — tolerance groups exist specifically as a segregation-of-duties control; collapsing everyone into the most-permissive group defeats that control and is likely to fail an internal audit. Support ticket volume should be solved by clearer training or a slightly wider (not maximal) limit, not by removing the control.', type: 'scenario' },
      { q: 'Client\'s external auditor asks how the system prevents an AP clerk from posting a vendor invoice with an arbitrarily large payment write-off.', a: 'Point to the Employee Tolerance Group assigned to that clerk\'s user ID — it caps the maximum payment difference postable without escalation, and any amount above that threshold is blocked or routed for approval, providing the segregation-of-duties evidence the auditor is asking for.', type: 'conceptual' },
      { q: 'A Document Type change request comes in mid-year to allow a new account type on an existing, heavily-used document type (e.g. adding vendor postings to a G/L-only type).', a: 'Flag the risk: changing an existing, widely-used document type\'s allowed account types retroactively affects reporting and reconciliation logic built around its prior scope. Recommend a new document type for the new use case instead, preserving the existing type\'s historical behavior.', type: 'scenario' },
      { q: 'Client\'s month-end close checklist has AP, AR, and G/L all closing on the same calendar day, causing a bottleneck.', a: 'Redesign using OB52\'s account-type granularity — close K and D a day or two before S, giving the G/L team visibility into finalized sub-ledger totals before they close the books, which is the standard pattern this control exists to support.', type: 'scenario' },
      { q: 'A field status conflict causes a required tax-relevant field to be suppressed on certain postings, and this is discovered only during a tax audit.', a: 'This is a high-severity finding — trace which posting keys are used for that transaction type, correct the posting key or field status group so the field is at minimum Required (not Suppress), and assess whether historical postings need remediation for the audit period in question.', type: 'troubleshooting' },
      { q: 'Client wants a single Field Status Variant shared across 15 Company Codes in different countries with different statutory field requirements.', a: 'A shared Field Status Variant means all 15 Company Codes get identical field behavior — flag this as a risk if statutory requirements genuinely differ per country; recommend country-specific Field Status Groups within the shared variant (or separate variants) rather than forcing one-size-fits-all field control.', type: 'scenario' },
      { q: 'Explain how a wrong Posting Period Variant assignment at Company Code level would surface as a symptom, without the consultant knowing the root cause yet.', a: 'Users at that Company Code would see period-open/closed errors inconsistent with what the close calendar says should be true — since the variant (not the calendar) actually drives OB52\'s account-type period ranges, a wrong variant assignment silently applies someone else\'s period schedule.', type: 'troubleshooting' },
      { q: 'A go-live cutover plan needs to open all posting periods temporarily for data migration, then lock everything down before user access begins.', a: 'Temporarily set OB52 to a wide-open period range for all account types during migration, then tighten it to the actual go-live period range and add Period Authorization Groups restricting prior periods to the migration/close team only before granting general user access — sequencing this correctly prevents end users from accidentally posting into migration-only periods.', type: 'scenario' },
    ],
  },
  'fi-day-3': {
    junior: [
      { q: 'What is the difference between Operating, Group, and Country Chart of Accounts?', a: 'Operating COA is the one actually posted to daily, assigned to the Company Code. Group COA sits above it for consolidation across Company Codes that may use different operating charts. Country COA satisfies a local statutory account layout requirement alongside the operating COA.', type: 'conceptual' },
      { q: 'What is a G/L Account Type and why is it significant in S/4HANA?', a: 'It classifies an account as Balance Sheet, Non-Operating Expense/Income, Primary Costs/Revenue, Secondary Costs, or Cash Account. It is significant because it merges FI and CO master data — a Secondary Costs account type is what used to be a separate CO cost element in ECC.', type: 'conceptual' },
      { q: 'What does an Account Group control on a G/L account master?', a: 'The number range used when the account is created, and the field status (suppressed/required/optional) for fields on that account\'s master record — mirroring the Account Group concept used for vendor/customer masters.', type: 'conceptual' },
      { q: 'What is a Retained Earnings Account?', a: 'The G/L account that automatically receives the net result of all P&L accounts at fiscal year-end via balance carryforward, determined by each P&L account\'s P&L Statement Account Type.', type: 'conceptual' },
      { q: 'How many Retained Earnings Accounts can one P&L Statement Account Type map to?', a: 'Exactly one. The mapping is strictly 1:1 — a P&L account\'s statement account type determines a single, specific retained earnings account.', type: 'conceptual' },
      { q: 'What are the three G/L master data segments?', a: 'Chart of Accounts segment (description, account type — shared wherever that COA is used), Company Code segment (currency, tax category, reconciliation account link), and CO-relevance driven by account type for cost/revenue elements.', type: 'conceptual' },
      { q: 'What is a Reconciliation Account?', a: 'A G/L account flagged to link a sub-ledger (AP or AR) to the general ledger. It automatically reflects the total of all vendor or customer balances and cannot be posted to directly.', type: 'conceptual' },
      { q: 'Why can\'t reconciliation accounts be posted to directly?', a: 'To guarantee the sub-ledger (vendor/customer balances) and the general ledger always agree — direct GL postings would break that automatic reconciliation, so all postings must flow through the AP/AR sub-ledger transactions.', type: 'conceptual' },
      { q: 'What is Open Item Management used for?', a: 'It flags an account (e.g. GR/IR clearing, bank clearing) so individual postings remain open until matched and cleared against an offsetting entry, rather than just accumulating into a balance.', type: 'conceptual' },
      { q: 'What is Line Item Display and how does it differ from Open Item Management?', a: 'Line Item Display shows individual postings on an account rather than only totals — useful for any detailed account. Open Item Management is a stronger control requiring each item to eventually clear; an account can have Line Item Display without Open Item Management.', type: 'conceptual' },
      { q: 'What is a Sort Key on a G/L account?', a: 'It determines the default assignment field (e.g. purchase order number, reference) used when the system tries to group and match open items for clearing — improving automatic clearing hit rates.', type: 'conceptual' },
      { q: 'Where is Cost Element Category maintained in S/4HANA?', a: 'Directly on the G/L account master, for accounts with Primary Costs/Revenue or Secondary Costs account type — there is no separate CO-only cost element master as there was in ECC.', type: 'conceptual' },
      { q: 'What are examples of Cost Element Categories?', a: 'Category 1 = primary cost, 11 = revenue, 21/22 = internal settlement/allocation categories used by CO allocation cycles — each governs which CO postings are valid for that account.', type: 'conceptual' },
      { q: 'What is the "Manage G/L Account Master Data" app used for?', a: 'The primary S/4HANA Fiori app for creating, changing, and displaying G/L account master records — replacing the classic FS00/FS01/FS02 transaction pattern from ECC.', type: 'conceptual' },
      { q: 'Why is Cash Account its own G/L Account Type rather than a Balance Sheet sub-type?', a: 'Because it integrates specifically with Bank Account Management (BAM) — flagging an account as Cash Account type connects it to house bank/account master data and cash position reporting in a way a generic Balance Sheet account does not.', type: 'conceptual' },
      { q: 'What master data must exist before a Secondary Costs G/L account can be used in an allocation cycle?', a: 'The account itself, created with account type Secondary Costs and the correct cost element category, plus valid CO master data (cost centers, controlling area) for the objects it allocates between.', type: 'conceptual' },
      { q: 'What happens if the Chart of Accounts segment of a G/L account is changed after the account has postings?', a: 'Certain fields (like account type) carry high risk if changed post-posting since CO/FI logic assumes consistency over time; SAP restricts or blocks changes to fields that would create inconsistent historical reporting.', type: 'conceptual' },
      { q: 'What is the relationship between Chart of Accounts and Company Code for a G/L account?', a: 'The Chart of Accounts segment of a G/L account (description, account type) is created once and can be used by every Company Code assigned to that COA; each Company Code then maintains its own Company Code segment (currency, tax, reconciliation link) for that account.', type: 'conceptual' },
      { q: 'Can two different Company Codes use the same operating Chart of Accounts but have different currencies for the same G/L account?', a: 'Yes — the Chart of Accounts segment is shared, but the Company Code segment (which includes currency) is maintained separately per Company Code, allowing different local currencies on the same shared account.', type: 'conceptual' },
      { q: 'What is the purpose of the Group Chart of Accounts specifically at month-end?', a: 'It provides a common account numbering scheme that consolidation/group reporting maps every operating COA account to, enabling one consolidated financial statement even when subsidiaries use different local operating charts.', type: 'conceptual' },
      { q: 'Why would a client need a Country Chart of Accounts in addition to the Operating COA?', a: 'Some countries legally require financial statements to be presented using a locally mandated account structure/layout; Country COA satisfies that statutory requirement without forcing the operating COA (used for daily processing) to match the local layout.', type: 'conceptual' },
      { q: 'What is the risk of skipping Open Item Management on a clearing account like GR/IR?', a: 'Without Open Item Management, the account only shows a net balance rather than individual open goods-receipt/invoice-receipt mismatches, making it far harder to investigate and clear specific discrepancies — a core GR/IR reconciliation control is lost.', type: 'conceptual' },
      { q: 'What field on the G/L master determines whether an account participates in cost-of-sales vs. nature-of-expense reporting?', a: 'Functional Area (from FI Day 2), used together with the G/L account\'s type, drives whether postings feed the cost-of-sales P&L view; the G/L account type itself determines Balance Sheet vs P&L classification.', type: 'conceptual' },
      { q: 'Why does S/4HANA describe the G/L account as replacing "two separate master data objects" from ECC?', a: 'In ECC, a Primary Cost account required both a G/L account (FI) and a separate cost element (CO, created via KA01/KA06). In S/4, the G/L account\'s account type alone determines CO-relevance, eliminating the second master data object entirely.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A client wants a single P&L account to feed two different retained earnings accounts depending on business unit.', a: 'Not possible directly — the P&L Statement Account Type maps 1:1 to a single Retained Earnings Account. Business-unit-level retained earnings splitting must be achieved through Segment or Profit Center reporting layered on top of the standard carryforward, not by trying to split one account\'s carryforward target.', type: 'scenario' },
      { q: 'Users attempt to post directly to a reconciliation account and receive an error. What is the correct process instead?', a: 'Post via the vendor or customer sub-ledger transaction (invoice, payment, credit memo) — the reconciliation account updates automatically as a result. The direct-posting block is intentional and should never be worked around via substitution or account type changes.', type: 'troubleshooting' },
      { q: 'A G/L account\'s type is changed from Primary Costs to Secondary Costs after several periods of postings.', a: 'This is high risk — CO reporting, allocation logic, and derivation rules built around the original type may become inconsistent across the historical vs. new periods. Treat this like any master-data-type change: assess historical impact, consider creating a new account instead, and get sign-off before proceeding.', type: 'troubleshooting' },
      { q: 'Client uses different operating charts of accounts per country but wants consolidated group reporting.', a: 'Assign a shared Group Chart of Accounts across every operating COA in use — Group COA exists specifically to enable consolidation across divergent local operating charts without forcing all Company Codes onto one shared operating COA.', type: 'scenario' },
      { q: 'An account meant for open item management (e.g. GR/IR clearing) was created without Open Item Management activated, and now has postings.', a: 'You cannot simply flip the flag with existing line items in place — this requires either clearing the account down to zero first or a controlled technical activation process. This is a common go-live gap; flag it for remediation planning rather than a quick config change.', type: 'troubleshooting' },
      { q: 'Client asks why S/4 no longer needs a separate CO transaction to create cost elements.', a: 'G/L Account Type now carries the CO-relevance directly on the G/L master — a cost element is simply a G/L account with account type Primary Costs/Revenue or Secondary Costs. This is one of S/4\'s headline master-data simplifications, eliminating the separate FI account + CO cost element pair from ECC.', type: 'conceptual' },
      { q: 'Auditor asks how the system guarantees AP sub-ledger totals always match the GL receivables balance.', a: 'Point to the Reconciliation Account design — it is structurally blocked from direct posting, and every vendor/customer transaction automatically updates it, so the sub-ledger and GL total are mathematically guaranteed to match by construction, not by a periodic reconciliation process.', type: 'conceptual' },
      { q: 'Client wants to add a new statutory reporting layout for a newly-entered country without disrupting daily operational postings.', a: 'Configure a Country Chart of Accounts for that jurisdiction and map it from the existing Operating COA — daily transaction posting continues unaffected against the Operating COA, while statutory reports pull from the Country COA mapping.', type: 'scenario' },
      { q: 'A cost center allocation cycle fails with an error referencing an invalid cost element category on the target account.', a: 'Check the target G/L account\'s Cost Element Category — allocation cycles validate that the receiving account\'s category (e.g. 21/22 for allocations) is compatible with the allocation method used; a Primary Cost category account, for example, may not accept certain allocation postings.', type: 'troubleshooting' },
      { q: 'Client\'s finance team wants line-item-level visibility on a high-volume revenue account without the overhead of full open item clearing.', a: 'Activate Line Item Display on the account without activating Open Item Management — this gives visibility into individual postings for investigation/reporting purposes without imposing the clearing discipline that Open Item Management requires, which would be unnecessary overhead for a revenue account.', type: 'scenario' },
      { q: 'Two Company Codes share one Operating Chart of Accounts, but one country requires a materially different statutory balance sheet layout.', a: 'Assign a Country Chart of Accounts to the Company Code with the divergent statutory requirement — this coexists with the shared Operating COA (used for daily processing) without forcing either Company Code to change its day-to-day account structure.', type: 'scenario' },
      { q: 'A GR/IR clearing account shows a large, growing net balance and finance cannot explain individual discrepancies.', a: 'First confirm Open Item Management is actually active on that account — a large unexplainable net balance with no line-item-level visibility into which specific GR/IR pairs are mismatched is the classic symptom of Open Item Management being missing or bypassed on a clearing account that needs it.', type: 'troubleshooting' },
      { q: 'Design a G/L account creation governance process to prevent uncontrolled account proliferation across a large FICO build.', a: 'Enforce Account Group discipline strictly — since Account Group governs the number range and field requirements for new accounts, route all new-account requests through a small number of well-defined Account Groups with mandatory approval, rather than allowing ad hoc account creation with loose field controls.', type: 'scenario' },
      { q: 'Client\'s Segment-based reporting (from FI Day 1) shows unexpected gaps on certain Secondary Costs accounts.', a: 'Confirm the Secondary Costs accounts in question actually carry a valid CO derivation path (cost center/controlling area assignment) — Secondary Costs accounts are CO-only by nature and won\'t independently carry Segment unless the CO object they post against has Profit Center/Segment properly assigned.', type: 'troubleshooting' },
      { q: 'A consultant proposes skipping Account Groups entirely and using one generic group for every G/L account "to simplify the build."', a: 'Push back — collapsing all Account Groups into one removes the number-range and field-status differentiation between, say, Balance Sheet and P&L accounts, which is exactly the control Account Groups exist to provide. This is speculative simplification that creates a governance gap, not genuine simplification.', type: 'scenario' },
      { q: 'Client wants to know whether the "Manage G/L Account Master Data" app can bulk-create accounts for a large chart of accounts migration.', a: 'The app supports mass creation/change via its underlying OData services and mass upload templates, but for a large migration (hundreds/thousands of accounts), pair it with the Migration Cockpit (covered in INT-6) rather than manual entry through the Fiori app one account at a time.', type: 'scenario' },
      { q: 'A newly acquired subsidiary\'s chart of accounts must be harmonized into the parent\'s Operating COA before go-live.', a: 'Map every subsidiary account to its equivalent (or new) account in the parent\'s Operating COA, paying special attention to account type consistency (Balance Sheet vs P&L vs Secondary Costs) since a wrong mapping here corrupts both financial and CO reporting from day one.', type: 'scenario' },
      { q: 'Client asks whether Sort Key can be changed after go-live if automatic clearing hit rates are poor.', a: 'Yes, Sort Key can be adjusted, but changing it only affects the default assignment field proposed going forward — it does not retroactively re-tag existing open items, so expect a transition period where old and new sort logic coexist during clearing runs.', type: 'scenario' },
      { q: 'Explain why "changing G/L account type after postings" and "changing Fiscal Year Variant after postings" (FI Day 1/2) are both flagged as high-risk in the same way.', a: 'Both are foundational master-data/config decisions that every downstream process (CO derivation, period determination, reporting) assumes are stable over time; changing either after transactional history exists creates a historical-vs-current inconsistency that is expensive to remediate rather than a simple field update.', type: 'conceptual' },
      { q: 'A client\'s Retained Earnings Account shows an unexpected balance after year-end close, not matching the sum of P&L accounts.', a: 'Check whether any P&L accounts were created or had their P&L Statement Account Type changed mid-year without a corresponding review of which Retained Earnings Account they map to — a mismatched or missing mapping on even one account will cause the carryforward total to be incorrect.', type: 'troubleshooting' },
      { q: 'Design the G/L account build sequence so that CO-relevant accounts (Primary/Secondary Costs) are created only after Controlling Area setup (FI Day 1) is confirmed.', a: 'Sequence account creation after Enterprise Structure sign-off specifically because Cost Element Category and CO-relevance validation depend on a live, correctly configured Controlling Area — creating CO-relevant G/L accounts before that foundation is fixed risks having to recreate or reclassify them later.', type: 'scenario' },
    ],
  },
  'fi-day-4': {
    junior: [
      { q: 'What is the difference between Park and Hold?', a: 'Park saves a complete document that can later be posted or routed through approval; it is visible in balances/workflow queues. Hold saves an incomplete entry purely for the entering user\'s own recall — it never posts and is invisible to anyone else.', type: 'conceptual' },
      { q: 'What replaced BSEG as the live posting table in S/4HANA?', a: 'ACDOCA — the Universal Journal is the single source of truth for line items. BSEG survives only as a compatibility/index view for reports that still reference the old structure.', type: 'conceptual' },
      { q: 'What is the difference between Partial and Residual clearing?', a: 'Partial clearing leaves the original open item open alongside a new partial-payment item, preserving the original baseline date. Residual clearing closes the original item entirely and creates one new item for the remaining balance, with a new baseline date.', type: 'conceptual' },
      { q: 'Why does the new baseline date from residual clearing matter?', a: 'Baseline date drives both payment-term timing and dunning eligibility, so a reset baseline date on a residual item changes when it becomes due and when it can be dunned — a common source of unexpected dunning behavior.', type: 'conceptual' },
      { q: 'What does Reset & Reverse do differently from a standard reversal?', a: 'It first undoes the item\'s clearing, restoring it to an open state, and then performs the reversal — standard reversal alone cannot act on an already-cleared document.', type: 'conceptual' },
      { q: 'What is the Accrual Engine?', a: 'A tool that automates recurring accrual and deferral postings on a schedule, including their automatic reversal, reducing the manual month-end journal entry burden for predictable recurring items.', type: 'conceptual' },
      { q: 'What is an Account Assignment Model used for?', a: 'It pre-fills common combinations of accounts and cost objects to speed up manual document entry for transactions that always hit the same accounts in predictable proportions.', type: 'conceptual' },
      { q: 'Which Fiori apps handle document entry, review, and approval in S/4HANA?', a: 'Post General Journal Entries (manual entry), Manage Journal Entries (search/display/reverse), and Verify Journal Entries (approval workflow for parked documents).', type: 'conceptual' },
      { q: 'What does ledger group posting enable?', a: 'It restricts a posting to specific ledger groups, allowing adjustments relevant only to certain accounting principles (e.g. a local-GAAP-only entry) without affecting the leading ledger.', type: 'conceptual' },
      { q: 'Why is a Sample Document useful even though it never posts by itself?', a: 'It acts as a reusable template that gets copied into a real document, ensuring consistent account combinations and reducing manual entry errors for recurring transaction types.', type: 'conceptual' },
      { q: 'What is the difference between a Sample Document and a Recurring Entry?', a: 'A Sample Document is a manually-copied template with no automatic scheduling. A Recurring Entry runs automatically on a defined schedule (e.g. monthly) without manual copying each time.', type: 'conceptual' },
      { q: 'What defines when a Recurring Entry stops generating postings?', a: 'A configured end date or a maximum number of runs set on the recurring entry master — without one of these, it would run indefinitely.', type: 'conceptual' },
      { q: 'What is the difference between Individual Reversal and Mass Reversal?', a: 'Individual Reversal reverses one specific document at a time. Mass Reversal processes many documents together using shared selection criteria and a single reversal reason.', type: 'conceptual' },
      { q: 'What is a Negative Posting and why is it sometimes preferred over a standard reversal?', a: 'A Negative Posting reverses a document by posting a negative amount in the same period rather than an offsetting debit/credit, keeping period totals and trend reports cleaner instead of inflating both debit and credit turnover.', type: 'conceptual' },
      { q: 'Can every reversal reason use negative posting?', a: 'No — negative posting must be explicitly enabled for a given reversal reason and is only available where the Company Code and posting period configuration permit it.', type: 'conceptual' },
      { q: 'What is "posting with reference" used for?', a: 'Creating a new document by copying the structure of an existing one (e.g. same accounts, similar amounts) as a starting point, distinct from a Sample Document which is a dedicated non-postable template.', type: 'conceptual' },
      { q: 'What is the difference between internal and external document number assignment?', a: 'Internal assignment lets SAP automatically assign the next number in the range; external assignment requires the user (or an interface) to supply the document number, often to match a legacy or source-system reference.', type: 'conceptual' },
      { q: 'Who can post a parked document?', a: 'Any user with the appropriate authorization can post a parked document once it is complete — this is what enables a segregation-of-duties workflow where one person parks and another reviews and posts.', type: 'conceptual' },
      { q: 'What is the difference between a manual accrual posting and an Accrual Engine-managed accrual?', a: 'A manual accrual is entered and reversed by hand each period. An Accrual Engine-managed accrual is scheduled once and then automatically posts and reverses itself each period without manual intervention.', type: 'conceptual' },
      { q: 'What happens if a recurring entry template references a G/L account that gets blocked mid-cycle?', a: 'The recurring entry run will fail for that specific posting until the account is unblocked or the template is updated to reference a valid account — it does not silently skip the line.', type: 'conceptual' },
      { q: 'What is the purpose of the "Manage Journal Entries" app specifically, versus "Post General Journal Entries"?', a: 'Manage Journal Entries is used to search, display, and reverse existing documents; Post General Journal Entries is used to create new manual postings — two different stages of the document lifecycle.', type: 'conceptual' },
      { q: 'Can a parked document be changed before it is posted?', a: 'Yes — parked documents remain editable (amounts, accounts, text) until the point they are actually posted, which is one of their main advantages over posting directly.', type: 'conceptual' },
      { q: 'What triggers the Accrual Engine\'s automatic reversal of a prior period\'s accrual?', a: 'The accrual object\'s defined schedule — once configured, each period-end run both posts the current period\'s accrual and reverses the prior period\'s, without needing a separate manual reversal step.', type: 'conceptual' },
      { q: 'Why might a company prefer Account Assignment Models over Sample Documents for a specific transaction type?', a: 'Account Assignment Models are lighter-weight and faster for entering the same account/cost-object combination repeatedly during manual entry, while Sample Documents are better suited to copying an entire multi-line document structure.', type: 'conceptual' },
      { q: 'What is the risk of leaving a Recurring Entry active with no end date after the underlying business need has ended?', a: 'It will keep generating postings indefinitely, creating erroneous entries that then require reversal and cleanup — a common operational hygiene issue.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A customer dispute requires dunning to reference the original invoice date after a partial payment was made.', a: 'Use Partial Clearing rather than Residual Clearing — partial clearing keeps the original open item (and its original baseline date) intact, which is exactly what preserves the original dunning timeline.', type: 'scenario' },
      { q: 'A user cannot reverse a cleared document using the standard reversal transaction.', a: 'Use Reset & Reverse — it undoes the existing clearing first, returning the document to an open state, and then completes the reversal in the same action.', type: 'troubleshooting' },
      { q: '"Why can\'t I reverse this document?" — walk the full diagnostic chain.', a: 'Check, in order: is the document already cleared, is the posting period closed, does the document involve cross-company complications, and is the reversal reason code valid for that document type — any one of these blocks a standard reversal.', type: 'troubleshooting' },
      { q: 'Client wants an adjustment posted only to their local statutory ledger, not the group/IFRS leading ledger.', a: 'Use ledger group posting, restricting the entry to the specific non-leading ledger group — this keeps the leading ledger clean of adjustments that only apply under local statutory rules.', type: 'scenario' },
      { q: 'A recurring entry has been posting an outdated amount for three months after a contract renegotiation.', a: 'Update the recurring entry\'s underlying template/reference document directly — recurring entries run off their own stored template independent of any original source document, so a source change alone does not propagate automatically.', type: 'troubleshooting' },
      { q: 'Auditor asks why S/4 no longer requires periodic reconciliation between an index table and totals table.', a: 'ACDOCA is the single Universal Journal line-item table — there is no separate index/totals structure (like ECC\'s BSEG/BSIS/BSAS) that needs periodic reconciliation; every posted line already carries its full account assignment and amounts.', type: 'conceptual' },
      { q: 'Client asks whether Negative Posting can be used for all reversals to keep their P&L trend report clean.', a: 'Not universally — negative posting must be explicitly enabled per reversal reason and permitted by the Company Code/period configuration; recommend enabling it selectively for the reversal reasons where trend-report cleanliness genuinely matters, rather than as a blanket default.', type: 'scenario' },
      { q: 'A mass reversal run partially fails, reversing some documents but not others in the batch.', a: 'Investigate the individual failed documents against the standard reversal blockers (already cleared, closed period, cross-company complications, invalid reversal reason) — a mass reversal doesn\'t bypass these per-document checks, so a partial failure means some documents genuinely can\'t be reversed as requested.', type: 'troubleshooting' },
      { q: 'Client\'s recurring entries are creating duplicate postings after a system refresh from production to a test environment.', a: 'Check whether the recurring entry\'s last-run date was reset during the refresh — if the schedule thinks no run has occurred yet, it can regenerate postings for periods already processed in production; recommend excluding or resetting recurring entry run logs appropriately during environment refreshes.', type: 'troubleshooting' },
      { q: 'A parked document sits unposted for several weeks and the client asks whether this creates financial risk.', a: 'Parked documents have no G/L impact until posted, so there\'s no direct financial risk, but an aging parked document may signal a stalled approval workflow — worth a process check on why it hasn\'t moved through review, similar to the noted item aging concern from FI-12.', type: 'conceptual' },
      { q: 'Client wants to know whether posting with reference can be used to duplicate a document across two different Company Codes.', a: 'Posting with reference copies structure within the accessible scope, but a genuine cross-Company-Code duplication of a business event should use a proper cross-company posting (FI-12) rather than manually re-keying via reference, to preserve the correct linked-document audit trail.', type: 'scenario' },
      { q: 'Auditor asks how Account Assignment Models reduce fraud risk compared to fully manual entry.', a: 'They constrain data entry to pre-approved account/cost-object combinations, reducing the chance of postings to unauthorized or incorrect accounts — a control benefit, though they don\'t replace proper segregation-of-duties authorization controls.', type: 'conceptual' },
      { q: 'A Company Code\'s Accrual Engine-managed rent accrual stops posting after a cost center reorganization.', a: 'Check whether the accrual object\'s configured cost center assignment was updated to reflect the reorganization — the Accrual Engine posts against the object\'s stored configuration, which does not automatically follow a cost center rename or reassignment.', type: 'troubleshooting' },
      { q: 'Client wants external document numbering for all vendor invoices to match their legacy AP system\'s invoice numbers.', a: 'Configure external number assignment on the relevant document type\'s number range — this lets the invoice carry the legacy system\'s reference directly as the SAP document number, useful for audit trail continuity during a transition period.', type: 'scenario' },
      { q: 'A user reports they can see a parked document in the worklist but cannot edit it.', a: 'Check their authorization for that specific document type/Company Code combination — parked document visibility and edit rights are controlled separately, so read access doesn\'t guarantee edit access, which is often intentional for segregation of duties.', type: 'conceptual' },
      { q: 'Client asks whether ledger-group-restricted postings (FI Day 4/5) ever need to be reversed differently than standard postings.', a: 'The reversal itself should also be scoped to the same ledger group as the original posting — reversing a ledger-group-restricted entry without specifying the ledger group risks either failing or, worse, reversing across unintended ledgers.', type: 'scenario' },
      { q: 'A recurring entry template was built with a hard-coded amount, but the underlying lease payment has since escalated per a contract clause.', a: 'The template requires manual updating to the new amount — recurring entries do not read external contract data or apply automatic escalation; this is a common operational gap worth flagging in a recurring-entry governance review.', type: 'troubleshooting' },
      { q: 'Client\'s internal audit flags that several Sample Documents haven\'t been used in over a year.', a: 'Recommend a periodic review and cleanup of unused Sample Documents — stale templates referencing outdated accounts or cost objects increase the risk of an entry being copied forward with now-incorrect account assignments.', type: 'scenario' },
      { q: 'Auditor asks how the system distinguishes a Negative Posting reversal from an original, unrelated negative-amount entry in reporting.', a: 'The negative posting document carries a reference back to the original document it reverses (via the reversal linkage), so reports and document flow tracing can still distinguish a true reversal from an unrelated negative-value original posting.', type: 'conceptual' },
      { q: 'A client wants to restrict which users can post using external document number assignment, to prevent accidental number collisions.', a: 'Restrict this via authorization on the specific document type\'s posting transaction/app, since external numbering carries a real risk of duplicate or out-of-sequence numbers if used carelessly by untrained users.', type: 'scenario' },
    ],
  },
  'fi-day-5': {
    junior: [
      { q: 'What five things does ACDOCA absorb from ECC?', a: 'BSEG (FI line items), COEP (CO line items), FAGLFLEXA (New GL totals), ANEP (asset postings), and MLIT (material ledger) — all merged into one Universal Journal table.', type: 'conceptual' },
      { q: 'What is the leading ledger and can it be deactivated?', a: 'The leading ledger (typically 0L) reflects the primary accounting principle, usually group/IFRS, and is always active — it cannot be deactivated in a Company Code.', type: 'conceptual' },
      { q: 'What is the difference between the Ledger approach and the Accounts approach to parallel accounting?', a: 'Ledger approach uses separate ledgers per accounting principle. Accounts approach captures principle-specific differences via dedicated G/L accounts within one ledger instead of adding a second ledger.', type: 'conceptual' },
      { q: 'What is a Simulation extension ledger used for?', a: 'Modeling what-if postings — entries that test a scenario without committing them to actuals in the underlying standard ledger.', type: 'conceptual' },
      { q: 'What is the single most-asked splitting question in FI interviews?', a: 'The distinction between passive splitting (inheriting a split from a referenced document) and active splitting (deriving the split independently via splitting rules).', type: 'conceptual' },
      { q: 'What does the Zero-Balance flag actually enforce?', a: 'It forces a splitting characteristic — like Segment or Profit Center — to sum to zero within each individual document, which is the mechanism that makes segment-level balance sheets actually balance.', type: 'conceptual' },
      { q: 'Can document splitting be turned on after go-live?', a: 'Yes, but it is a project rather than a simple config toggle — historical documents are not retroactively re-split, so a transition plan is needed for reporting continuity.', type: 'conceptual' },
      { q: 'What determines which splitting rule set applies to a given document?', a: 'The combination of Business Transaction (the event type, e.g. vendor invoice), Transaction Variant, and Item Category together determine the applicable splitting rule set.', type: 'conceptual' },
      { q: 'Does data in an extension ledger exist in the underlying standard ledger?', a: 'No — extension ledger postings exist only in the extension layer on top of the base ledger; they are additive/virtual and never written into the standard ledger itself.', type: 'conceptual' },
      { q: 'What does Predictive Accounting use extension ledgers for?', a: 'Posting commitment and statistical data — like unapproved sales orders or planned costs — into a prediction ledger for forward-looking reporting, without affecting actual financial results.', type: 'conceptual' },
      { q: 'What is a Standard extension ledger used for, distinct from Simulation or Prediction?', a: 'Adding adjustment postings on top of an underlying ledger permanently (e.g. a recurring statutory adjustment), without duplicating the underlying ledger\'s full data set.', type: 'conceptual' },
      { q: 'Can more than one non-leading ledger exist in a Company Code?', a: 'Yes — multiple non-leading ledgers can coexist, each representing a different accounting principle (e.g. local GAAP for two different countries), all alongside the single mandatory leading ledger.', type: 'conceptual' },
      { q: 'What is a Ledger Group?', a: 'A grouping of one or more ledgers used to scope a posting (or a report) to a specific subset of ledgers, rather than posting to every ledger by default.', type: 'conceptual' },
      { q: 'What is the relationship between Segment and document splitting?', a: 'Segment is commonly configured as a splitting characteristic, meaning document splitting derives and balances Segment on each document line so that segment-level reporting is possible.', type: 'conceptual' },
      { q: 'What does "splitting rule" broadly refer to in document splitting configuration?', a: 'The combination of business transaction, transaction variant, and item category-based rules that determine how a document\'s amounts get distributed (split) across the relevant splitting characteristics.', type: 'conceptual' },
      { q: 'Can a splitting characteristic other than Profit Center or Segment be configured?', a: 'Yes — Business Area (legacy) and custom characteristics can also be configured as splitting characteristics, though Profit Center and Segment are by far the most common in S/4 designs.', type: 'conceptual' },
      { q: 'What is "inheritance" in the context of document splitting?', a: 'A document line inheriting a splitting characteristic value from another line in the same document — a general mechanism related to, but broader than, passive splitting\'s specific inherit-from-reference-document behavior.', type: 'conceptual' },
      { q: 'What is a "default account assignment" in the context of document splitting?', a: 'A constant value (like a default Segment or Profit Center) configured to apply when a line item has no other way to derive the splitting characteristic — a fallback, not the primary derivation path.', type: 'conceptual' },
      { q: 'Does document splitting apply to every document type, or can it be scoped?', a: 'It can be scoped — splitting rules are configured per business transaction/transaction variant, so certain document types can be included or excluded from active splitting behavior as needed.', type: 'conceptual' },
      { q: 'What is the practical difference between a ledger and a splitting characteristic?', a: 'A ledger represents a full parallel accounting view (e.g. IFRS vs local GAAP); a splitting characteristic (like Segment) is a reporting dimension within a single ledger\'s postings — the two solve different problems and can be used together.', type: 'conceptual' },
      { q: 'What does "currency type" mean in the context of ACDOCA\'s parallel currency support?', a: 'Each currency type (company code currency, group currency, and up to 8 freely definable types from FI Day 1) is stored as its own field on the same ACDOCA line, letting one posting be viewed in multiple currencies simultaneously.', type: 'conceptual' },
      { q: 'Can extension ledgers have their own currency settings independent of the underlying standard ledger?', a: 'Yes — an extension ledger can be configured with currency settings appropriate to its purpose (e.g. a simulation in a different reporting currency) without affecting the underlying standard ledger\'s currency configuration.', type: 'conceptual' },
      { q: 'What happens to a document\'s splitting result if its business transaction type is reclassified after posting?', a: 'The already-posted document\'s split is not retroactively recalculated; only new postings going forward reflect the updated business transaction classification and its associated splitting rules.', type: 'conceptual' },
      { q: 'What is the relationship between the Universal Journal and financial statement reporting granularity?', a: 'Because every dimension (Company Code, Segment, Profit Center, cost object, currency) lives on the same ACDOCA line, reports can be sliced by any combination of these dimensions directly, without needing to join separate tables.', type: 'conceptual' },
      { q: 'Is the leading ledger always the same across every Company Code in a client?', a: 'The leading ledger designation (e.g. 0L) is typically consistent client-wide, but which accounting principle it represents and how non-leading ledgers are configured can still vary by Company Code as needed.', type: 'conceptual' },
      { q: 'What is a common reason a client would need a non-leading ledger at all?', a: 'To maintain a parallel accounting principle (e.g. local statutory GAAP) alongside the group/IFRS leading ledger, so both views are available from the same transactional postings without duplicate manual entry.', type: 'conceptual' },
      { q: 'What does "iterative processing" mean in the context of splitting rule resolution (distinct from allocation cycles in CO Day 4)?', a: 'While iterative processing is primarily an allocation-cycle concept, the general principle — resolving interdependent relationships through repeated passes rather than a single pass — is conceptually related to how complex splitting scenarios can require multiple derivation passes.', type: 'conceptual' },
      { q: 'What is the risk of having too many splitting characteristics configured at once?', a: 'Each additional splitting characteristic increases document complexity and processing overhead, and can make troubleshooting a splitting discrepancy harder — most designs deliberately limit splitting characteristics to the ones genuinely needed for reporting.', type: 'conceptual' },
      { q: 'Can a Company Code post to an extension ledger without also posting to its underlying standard ledger?', a: 'No — an extension ledger by definition sits on top of an underlying standard ledger; it cannot exist or receive postings independently of that base ledger relationship.', type: 'conceptual' },
      { q: 'What is the benefit of Predictive Accounting for a sales-heavy business specifically?', a: 'It lets finance see the financial impact of orders and commitments that haven\'t yet become actual revenue (e.g. open sales orders), supporting forward-looking cash and margin visibility without contaminating actual reported results.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client\'s segment-level balance sheet doesn\'t balance to zero even though the Company Code total is correct.', a: 'Check whether the Zero-Balance flag is active for Segment as a splitting characteristic — Segment derivation alone (having the field populated) is not sufficient; the zero-balance clearing mechanism is what actually forces the per-document balance.', type: 'troubleshooting' },
      { q: 'A vendor payment does not split the same way its referenced invoice did, breaking Segment-level reporting consistency.', a: 'This points to a passive splitting configuration gap — payments should passively inherit the split of the invoice they reference, so investigate the business transaction/transaction variant mapping for that payment document type.', type: 'troubleshooting' },
      { q: 'Client needs an alternative accounting principle represented without standing up a second full ledger.', a: 'Use the Accounts approach — capture the principle-specific difference through dedicated G/L accounts within the existing ledger rather than adding a second ledger, which is a heavier structural commitment.', type: 'scenario' },
      { q: 'Auditor asks whether simulation postings in an extension ledger show up anywhere in the standard ledger\'s actuals.', a: 'No — extension ledger data, including simulation postings, exists only within the extension layer and never appears in the underlying standard ledger\'s actual financial results.', type: 'conceptual' },
      { q: 'A newly onboarded Company Code has different document splitting rules from the rest of its Controlling Area.', a: 'Flag this as a design risk — while technically permitted, inconsistent splitting rules across Company Codes sharing a Controlling Area undermine the comparability that cross-CC segment/profit-center reporting is meant to provide.', type: 'scenario' },
      { q: 'Client\'s prior S/4 project promised segment-level reporting but never delivered it in practice.', a: 'The most likely cause is that document splitting with zero-balance clearing was treated as a post go-live afterthought rather than an Enterprise Structure-time design decision — retrofitting splitting is a project, not a quick configuration fix, echoing the FI Day 1 lesson about locking structure early.', type: 'scenario' },
      { q: 'Client wants to add a second non-leading ledger for a newly acquired subsidiary\'s local GAAP, on top of an existing non-leading ledger for a different country.', a: 'This is supported — multiple non-leading ledgers can coexist alongside the leading ledger, each scoped via its own ledger group; confirm the new ledger\'s currency and fiscal year variant settings align with the subsidiary\'s Company Code before activation.', type: 'scenario' },
      { q: 'Auditor asks whether a Standard extension ledger\'s adjustment postings show up in the underlying ledger\'s balance.', a: 'No — extension ledger adjustments layer additively on top of the underlying ledger for reporting purposes but are never written into the underlying standard ledger itself; reports must explicitly include the extension ledger to see the combined view.', type: 'conceptual' },
      { q: 'Client\'s Segment-based reports include Business Area data mixed in from a legacy configuration, causing confusion.', a: 'Review whether Business Area is still active as a legacy splitting characteristic alongside Segment — since S/4 favors Segment, having both active without a clear governance rule creates redundant/conflicting reporting dimensions that should be rationalized down to one.', type: 'troubleshooting' },
      { q: 'A client wants forward-looking visibility into open sales order value without affecting their actual reported revenue figures.', a: 'This is the core use case for Predictive Accounting via a prediction extension ledger — commitment/statistical postings land there, visible for forward-looking analysis, while actual reported financials in the standard ledger remain untouched.', type: 'scenario' },
      { q: 'Client asks whether reclassifying a business transaction type would retroactively fix a historical document\'s incorrect split.', a: 'No — reclassification only affects new postings going forward; a historical document\'s existing split is not recalculated, so a genuine historical correction requires a reversal and re-posting under the corrected configuration, not a reclassification alone.', type: 'troubleshooting' },
      { q: 'Two Company Codes in the same Controlling Area configure different sets of splitting characteristics.', a: 'Flag this as a design risk consistent with the earlier CO Day 1 pattern — while technically independent per Company Code, inconsistent splitting characteristics undermine comparable cross-CC reporting and should be harmonized unless there\'s a clear, documented reason for the divergence.', type: 'scenario' },
      { q: 'Client asks how many splitting characteristics they should configure for a mid-size single-country implementation.', a: 'Recommend limiting to genuinely required reporting dimensions — typically Profit Center and Segment cover most needs; adding characteristics "just in case" increases document complexity and troubleshooting difficulty without a clear reporting payoff, echoing the speculative-flexibility caution from FI Day 3.', type: 'scenario' },
      { q: 'A report combining data from the leading ledger and an extension ledger shows unexpected totals.', a: 'Confirm the report is explicitly configured to include the extension ledger\'s layer — since extension ledger data is additive and separate from the underlying standard ledger, a report reading only the standard ledger by default will show a different (lower) total than one correctly including the extension.', type: 'troubleshooting' },
      { q: 'Client wants a what-if budget scenario tested without any risk of accidentally affecting actual reported numbers.', a: 'Use a Simulation extension ledger — postings there test the scenario in isolation and never touch the underlying standard ledger\'s actuals, eliminating the risk of accidental contamination of real financial results.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents a user from accidentally posting a real transaction into a Simulation ledger.', a: 'Postings are directed to specific ledgers/ledger groups via configuration and authorization, not left to user discretion at transaction time — a properly configured system routes real transactional postings to the standard/leading ledger by default, with simulation postings requiring an explicit, separately authorized process.', type: 'conceptual' },
      { q: 'Client\'s cross-CC Controlling Area reporting shows inconsistent Segment population across its Company Codes.', a: 'Check whether all Company Codes in the Controlling Area have Segment configured identically as a splitting characteristic with zero-balance clearing — a CC missing this configuration will show incomplete or missing Segment data compared to its peers, even though basic Controlling Area-level integration (CO Day 1) is otherwise intact.', type: 'troubleshooting' },
      { q: 'Client asks whether currency types can differ between the leading ledger and a non-leading ledger.', a: 'Currency types themselves are shared at the Company Code/client level (per FI Day 1), but each ledger can still be configured with different specific reporting currencies drawn from those available types, tailored to what that ledger\'s accounting principle requires.', type: 'conceptual' },
      { q: 'A finance team wants to know if extension ledgers count against the same posting period controls (OB52) as the standard ledger.', a: 'Extension ledger postings generally still respect the underlying Company Code\'s period control framework, since they layer on top of — rather than bypass — the standard ledger\'s posting period structure; verify specific configuration for the ledger type in question if unusual behavior is reported.', type: 'conceptual' },
      { q: 'Client asks why their Segment-level balance sheet was correct in a pilot Company Code but incorrect after rolling out to five more.', a: 'Confirm the same document splitting configuration (Segment as a splitting characteristic, zero-balance flag active) was replicated identically to all five new Company Codes — a common rollout gap is copying most, but not all, of the splitting configuration to newly onboarded entities.', type: 'troubleshooting' },
      { q: 'Auditor questions why postings dated in a period already closed for the standard ledger still appear to process in an extension ledger.', a: 'Verify the extension ledger\'s own period control settings — while typically aligned with the underlying ledger, if configured with independent period settings, extension ledger postings could process on a schedule not identical to the standard ledger\'s close calendar, which should be reviewed for control gaps.', type: 'troubleshooting' },
      { q: 'Client wants their group consolidation team to use the Prediction ledger data for forecast reporting.', a: 'This is a reasonable use case since Predictive Accounting exists specifically for forward-looking, non-actual reporting; ensure the consolidation team\'s reporting tool is configured to read the prediction ledger explicitly and is clearly labeled as forecast, not actual, to avoid confusion downstream.', type: 'scenario' },
      { q: 'A newly built Company Code inherits its Chart of Accounts and Controlling Area setup from an existing one, but not its document splitting configuration.', a: 'This is a common oversight — splitting configuration (characteristics, zero-balance flags, business-transaction rule assignments) must be explicitly copied or rebuilt for each new Company Code; it does not automatically inherit alongside COA/Controlling Area assignment.', type: 'troubleshooting' },
      { q: 'Client\'s controller asks whether the Ledger approach or the Accounts approach is easier to maintain long-term for a company adding new countries every year.', a: 'The Accounts approach tends to be lighter-weight to extend since it avoids standing up a new full ledger per new accounting requirement, but it can produce a more cluttered chart of accounts over time; the Ledger approach scales cleaner structurally but with more upfront ledger configuration per new principle — the right choice depends on how frequently distinct principles, not just new countries, actually arise.', type: 'scenario' },
      { q: 'Auditor asks for the single clearest way to demonstrate that Segment-level reporting in this client\'s S/4 system is trustworthy.', a: 'Demonstrate that Segment is an active splitting characteristic with zero-balance clearing enabled, consistently configured across every relevant Company Code, and show a sample document where the Segment-level lines sum to zero independently — this combination is the concrete evidence, not just a statement that Segment is populated.', type: 'conceptual' },
    ],
  },
  'fi-day-6': {
    junior: [
      { q: 'How must vendor master data be created in S/4HANA?', a: 'Exclusively via the Business Partner (BP) transaction — classic FK01/XK01 vendor creation transactions are no longer available.', type: 'conceptual' },
      { q: 'What do BP roles FLVN00 and FLVN01 represent?', a: 'FLVN00 is the general vendor role data; FLVN01 is the Company Code-specific vendor data (reconciliation account, payment terms, etc.).', type: 'conceptual' },
      { q: 'What is CVI and why does it matter?', a: 'Customer-Vendor Integration keeps the Business Partner and its vendor/customer sub-object numbers synchronized automatically — without it, number mismatches would block postings.', type: 'conceptual' },
      { q: 'What controls the number range and field status for a vendor master record?', a: 'The Vendor Account Group assigned to that BP\'s vendor role — the same design pattern as the G/L Account Group from FI Day 3.', type: 'conceptual' },
      { q: 'What special G/L indicator is used for vendor down payments?', a: 'Indicator A, posting to an alternative reconciliation account that keeps the down payment separate from regular payables until it is cleared against the final invoice.', type: 'conceptual' },
      { q: 'What does baseline date control for a vendor invoice?', a: 'Both automatic payment run (F110) item selection and dunning eligibility — a single field with two significant downstream effects.', type: 'conceptual' },
      { q: 'Is classic withholding tax configuration supported in S/4HANA?', a: 'No — Extended Withholding Tax is mandatory; classic WHT configuration is not part of the S/4 scope going forward.', type: 'conceptual' },
      { q: 'What are noted items in the AP context?', a: 'Memo-style postings (e.g. a down payment request before actual payment) that carry no G/L impact until they convert into a real posting.', type: 'conceptual' },
      { q: 'What are the primary S/4 Fiori apps for AP line item review?', a: 'Manage Supplier Line Items and Supplier Balances, replacing the classic FBL1N/FK10N-style GUI reports.', type: 'conceptual' },
      { q: 'What happens if a required BP role is missing when posting a vendor invoice?', a: 'The posting fails outright — a missing role (e.g. FLVN01 for that Company Code) blocks the transaction entirely, not just reporting.', type: 'conceptual' },
      { q: 'What is a Business Partner Grouping in the vendor context?', a: 'A configuration determining the BP number range and, together with the BP role, influencing how the vendor sub-object number is derived via CVI.', type: 'conceptual' },
      { q: 'Can a single Business Partner hold both a vendor and a customer role simultaneously?', a: 'Yes — a Business Partner can carry multiple roles (vendor, customer, or both), representing a real-world entity that is both a supplier and a buyer to the same organization.', type: 'conceptual' },
      { q: 'What is the difference between a down payment request and an actual down payment posting?', a: 'A down payment request is a noted item (memo, no G/L impact); the actual down payment is a real posting using the special G/L indicator once payment is made against that request.', type: 'conceptual' },
      { q: 'What does Correspondence typically generate for a vendor relationship?', a: 'Standard communication outputs like account statements or balance confirmations, configured similarly in spirit to SD\'s output determination technique.', type: 'conceptual' },
      { q: 'What determines the reconciliation account used for a given vendor?', a: 'The reconciliation account is assigned on the vendor\'s Company Code segment (FLVN01), linking that vendor\'s sub-ledger postings to the correct G/L reconciliation account (from FI Day 3).', type: 'conceptual' },
      { q: 'Why can\'t two vendors share the same reconciliation account setup in a way that skips sub-ledger detail?', a: 'They can share the same reconciliation account (many vendors typically do), but each vendor\'s individual open items are still tracked at the vendor level within the sub-ledger — the reconciliation account only reflects the total, not eliminating per-vendor detail.', type: 'conceptual' },
      { q: 'What is the purpose of an alternative payee on a vendor master record?', a: 'Allowing payment to be made to a different party than the vendor itself (e.g. a factoring company or headquarters), while the original vendor remains the invoicing/reconciliation entity.', type: 'conceptual' },
      { q: 'What does the term "one-time vendor" refer to?', a: 'A generic vendor account group used for infrequent, low-volume vendors where creating full individual vendor master records isn\'t justified — transaction-specific details are entered at posting time instead.', type: 'conceptual' },
      { q: 'What is the risk of using a one-time vendor account for a supplier that turns out to be recurring?', a: 'Losing consolidated vendor-level reporting and payment history, since one-time vendor transactions don\'t roll up under one dedicated master record the way a proper vendor account does.', type: 'conceptual' },
      { q: 'What does "duplicate invoice check" refer to in AP processing?', a: 'A system check (based on vendor, invoice number, amount, and date) that flags or blocks an invoice that appears to duplicate one already posted, preventing accidental double payment.', type: 'conceptual' },
      { q: 'What is the purpose of payment block reason codes at the vendor or invoice level?', a: 'Preventing a specific vendor or invoice from being selected in the automatic payment run until the block is manually released, typically used for disputes or pending approvals.', type: 'conceptual' },
      { q: 'What does the term "cash discount" refer to on a vendor invoice?', a: 'A reduction in the payable amount if payment is made within a specified early-payment window, defined by the vendor\'s payment terms.', type: 'conceptual' },
      { q: 'How does Extended Withholding Tax differ in its configuration scope from Classic Withholding Tax (no longer supported)?', a: 'Extended WHT supports multiple withholding tax types/codes per vendor simultaneously and configurable calculation timing (invoice vs payment), which classic WHT\'s simpler single-type model could not handle as flexibly.', type: 'conceptual' },
      { q: 'What is a Withholding Tax Certificate?', a: 'A statutory document generated to confirm the amount of tax withheld from a vendor payment, required in many countries for the vendor\'s own tax filing purposes.', type: 'conceptual' },
      { q: 'What does the vendor master\'s "Recipient Type" or classification typically influence in withholding tax scenarios?', a: 'Which withholding tax rate or exemption applies, since certain vendor classifications (e.g. by legal entity type) can be subject to different statutory withholding requirements.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A vendor invoice fails to post with a vague error, and no master data issue is obviously visible.', a: 'Check whether the required BP role for that Company Code (FLVN01) actually exists on the vendor — a missing role is the most common root cause of unexplained vendor posting failures, especially post-migration.', type: 'troubleshooting' },
      { q: 'A down payment was cleared, but the final invoice still shows the full original amount as outstanding.', a: 'Verify the down payment clearing transaction correctly referenced both the alternative reconciliation account and the final invoice — a skipped or misdirected clearing step leaves both the down payment and the invoice open independently.', type: 'troubleshooting' },
      { q: 'Client wants payment terms to still count from the original invoice date after a partial vendor payment.', a: 'Use Partial Clearing rather than Residual Clearing on the vendor side, mirroring the same FI Day 4 logic — partial clearing preserves the original baseline date; residual clearing would reset it.', type: 'scenario' },
      { q: 'A client migrating off ECC asks why their FK01-based vendor onboarding script no longer works.', a: 'BP is the mandatory, sole entry point for vendor master creation in S/4 — FK01/XK01 were intentionally retired as part of the S/4 simplification, and this is a standard interview filter for genuine S/4 exposure.', type: 'conceptual' },
      { q: 'Client has vendors across two countries needing withholding tax calculated at different points (invoice vs payment).', a: 'Extended Withholding Tax supports country-specific configuration of calculation timing per withholding tax type/code, so both countries\' requirements can coexist within the same system.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents a vendor payment from posting twice against an already-cleared invoice.', a: 'Open Item Management on the vendor reconciliation account ensures a cleared item is removed from the open item pool, so neither the payment program nor manual clearing can select it again.', type: 'conceptual' },
      { q: 'Client\'s AP team wants payments for a specific vendor routed to a factoring company instead of the vendor directly.', a: 'Configure an alternative payee on the vendor master — this redirects the actual payment to the factoring company while the vendor remains the invoicing and reconciliation entity for all reporting purposes.', type: 'scenario' },
      { q: 'A duplicate invoice check flags a legitimate second invoice from the same vendor with a coincidentally similar amount and date.', a: 'Review the specific matching criteria (vendor, invoice number, amount, date) — if the invoice numbers genuinely differ, the check may need its sensitivity reviewed rather than assuming the flag is always correct; false positives are possible and shouldn\'t be blindly overridden without verification either way.', type: 'troubleshooting' },
      { q: 'Client used one-time vendor accounts for a supplier who has since become a regular, high-volume partner.', a: 'Recommend converting to a proper dedicated vendor master record — continuing to use one-time vendor postings for a recurring supplier loses consolidated payment history, vendor-level reporting, and makes credit/dispute management much harder to track.', type: 'scenario' },
      { q: 'A vendor payment is blocked and the AP clerk cannot determine why despite the invoice looking correct.', a: 'Check for a payment block reason code at either the invoice or vendor level — these are common, deliberate holds (disputes, pending approval) that aren\'t always obvious from the invoice data alone and require checking the block field specifically.', type: 'troubleshooting' },
      { q: 'Client wants to apply different withholding tax rates for the same vendor depending on the type of service invoiced.', a: 'Extended Withholding Tax supports multiple withholding tax types/codes per vendor, so different service categories can be configured with their own applicable rate — this flexibility is exactly why classic WHT (single-type) was retired in favor of Extended WHT.', type: 'scenario' },
      { q: 'Auditor asks for evidence that withholding tax certificates were correctly issued for a sample of vendor payments.', a: 'Pull the Withholding Tax Certificate output for those specific payments and cross-check the withheld amount against the configured rate for that vendor\'s classification and withholding tax code — this is the standard audit trail for WHT compliance.', type: 'conceptual' },
      { q: 'A cash discount was not applied even though the payment was made within the early-payment window.', a: 'Check the payment terms configuration on the vendor/invoice and confirm the payment program actually evaluated the discount period correctly against the baseline date — a mismatch between the intended discount window and the configured payment terms is the most common cause.', type: 'troubleshooting' },
      { q: 'Client wants to consolidate reconciliation accounts for all vendors in a given country to simplify their chart of accounts.', a: 'This is workable since many vendors can share one reconciliation account without losing individual vendor-level open item tracking — confirm the consolidation doesn\'t inadvertently merge vendors that need separately visible aging or dispute tracking for other business reasons.', type: 'scenario' },
      { q: 'A vendor classified under the wrong Recipient Type is having incorrect withholding tax applied.', a: 'Correct the vendor master\'s classification field and verify whether historical payments need retroactive withholding tax correction and, if applicable, an amended certificate — this is a master-data correction with potential downstream compliance impact.', type: 'troubleshooting' },
      { q: 'Client asks whether a Business Partner can be both a customer and a vendor for intercompany trading purposes.', a: 'Yes — a single BP can carry both roles, which is common for intercompany trading partners; ensure both roles have their own correctly maintained Company Code segments (FLVN01/FLCU01) since the roles are otherwise independently configured.', type: 'conceptual' },
      { q: 'Auditor asks how correspondence output (account statements) supports vendor dispute resolution.', a: 'Correspondence provides the vendor with a formal, system-generated statement of their account status, which serves as a documented basis for resolving discrepancies — the output determination configuration should be checked if statements aren\'t generating for a disputing vendor.', type: 'conceptual' },
      { q: 'Client\'s down payment request sits as a noted item for an unusually long time, and finance asks if this needs escalation.', a: 'The noted item itself carries no financial risk while unconverted (per the FI-12 pattern), but a long-unconverted down payment request may indicate a stalled vendor negotiation or delayed project milestone worth an operational check, not an accounting concern.', type: 'conceptual' },
      { q: 'A vendor\'s account group was set up without a reconciliation account default, and the first invoice attempt fails.', a: 'Confirm the account group\'s configuration includes a proper reconciliation account assignment — a missing default at the account group level, not just the individual vendor master, is the likely root cause if this affects multiple new vendors in that group.', type: 'troubleshooting' },
      { q: 'Client wants to know whether BP Grouping affects anything beyond number range assignment.', a: 'BP Grouping primarily drives number range and, in combination with CVI, influences vendor/customer sub-object number derivation — it is not typically used to drive field status or other master data behavior, which remains governed by the Account Group.', type: 'conceptual' },
    ],
  },
  'fi-day-7': {
    junior: [
      { q: 'What are the four stages of an F110 payment run?', a: 'Parameters (selection criteria) → Proposal (item selection) → Payment Run (payment document creation) → Payment Medium (file/check generation).', type: 'conceptual' },
      { q: 'What are the five FBZP configuration blocks?', a: 'All Company Codes, Paying Company Code, Payment Methods per Country, Payment Methods per Company Code, and Bank Determination (ranking order, bank accounts, available amounts, value date, charges).', type: 'conceptual' },
      { q: 'Where is house bank and account ID master data maintained in S/4HANA?', a: 'In Bank Account Management (BAM), which replaces the classic FI12 transaction entirely.', type: 'conceptual' },
      { q: 'What is the Payment Medium Workbench (PMW)?', a: 'The modern tool for generating the actual payment file/format sent to a bank, replacing the classic RFFO* print programs from ECC.', type: 'conceptual' },
      { q: 'What role does DMEE/DMEEX play in payment processing?', a: 'It defines and adjusts the specific file format layout a particular bank requires, feeding into how PMW generates the final payment file.', type: 'conceptual' },
      { q: 'What happens to Electronic Bank Statement transactions that don\'t match automatically?', a: 'They post to a clearing/suspense account for manual post-processing investigation rather than blocking the entire statement import.', type: 'conceptual' },
      { q: 'What is a Check Lot?', a: 'A number range definition for physical checks, tracked through the check register alongside void reasons and cancellations.', type: 'conceptual' },
      { q: 'What is Bank Account Management "Lite" vs "full"?', a: 'Lite BAM covers basic bank account master data; full BAM adds bank hierarchy and a formal review/approval workflow for account changes.', type: 'conceptual' },
      { q: 'What is the difference between value date, posting date, and document date?', a: 'Document date is when the underlying transaction occurred, posting date is when it hits the ledger period, and value date is the bank-relevant processing date — all three can legitimately differ.', type: 'conceptual' },
      { q: 'What is In-House Cash used for at a high level?', a: 'Centralizing internal cash and payment netting across group entities, reducing external bank transaction volume and associated fees.', type: 'conceptual' },
      { q: 'What is the difference between the F110 Parameters stage and the Proposal stage?', a: 'Parameters define the selection criteria (Company Codes, dates, vendor/customer range); Proposal is where the system actually applies those criteria to select specific open items for payment.', type: 'conceptual' },
      { q: 'Can a payment proposal be edited before the payment run executes?', a: 'Yes — the proposal can be reviewed and individual items can be blocked or unblocked before the actual payment run creates the payment documents, giving a manual review checkpoint.', type: 'conceptual' },
      { q: 'What is a Payment Method?', a: 'A configured way of making a payment (check, wire transfer, direct debit, etc.), assigned at both the country level and the Company Code level within FBZP, and also selectable on the vendor/invoice.', type: 'conceptual' },
      { q: 'What role does "Bank Determination" play within FBZP?', a: 'It sets the ranking order of house banks/accounts, available amounts, value date rules, and charges — this is the block most often responsible for a payment routing through an unexpected bank account.', type: 'conceptual' },
      { q: 'What is a House Bank ID and Account ID pair used for?', a: 'Identifying a specific bank and specific account at that bank within SAP, maintained via Bank Account Management and linked to a G/L account for postings.', type: 'conceptual' },
      { q: 'What does "Interpretation Algorithm" mean in the context of Electronic Bank Statement processing?', a: 'The logic SAP uses to parse and match incoming bank statement line items (e.g. by reference number pattern) to determine which open item(s) they correspond to.', type: 'conceptual' },
      { q: 'What is a Posting Rule in EBS configuration?', a: 'The rule that determines which G/L accounts and posting logic apply once a bank statement transaction has been interpreted and matched, translating the matched transaction into an actual FI posting.', type: 'conceptual' },
      { q: 'What is an External Transaction code in EBS?', a: 'A code the bank itself uses to classify a statement line item (e.g. a specific transaction type for a wire transfer), which SAP maps to its own internal posting rules via configuration.', type: 'conceptual' },
      { q: 'What does "Available Amount" mean within Bank Determination?', a: 'The maximum amount available in a given house bank/account for payment selection, used to distribute payment volume appropriately when multiple accounts are ranked for the same payment method.', type: 'conceptual' },
      { q: 'What is a Void Reason Code used for?', a: 'Documenting why a specific check was cancelled/voided (e.g. printer error, stale check, lost in mail) as part of the check register\'s audit trail.', type: 'conceptual' },
      { q: 'What is the purpose of a payment proposal\'s "exception list"?', a: 'Listing items that could not be automatically selected for payment (e.g. due to a block or missing bank details), so they can be manually reviewed before the run finalizes.', type: 'conceptual' },
      { q: 'What does DMEE stand for and what problem does it solve?', a: 'Data Medium Exchange Engine — it lets a consultant define or adjust the exact file structure/format a specific bank requires for electronic payment files, without custom ABAP development.', type: 'conceptual' },
      { q: 'What is Cash Management used for at an awareness level in this tab?', a: 'Providing forward-looking cash position visibility across house banks and planned inflows/outflows, complementing the transactional detail this tab covers with a more strategic liquidity view.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A payment proposal selects zero items despite clearly overdue, unblocked vendor invoices existing.', a: 'Walk the full FBZP chain: payment method mismatch between BP and document, payment block flags, bank determination amount/ranking issues, house bank assignment, due date logic, and minimum payment amount thresholds — any one of these silently excludes an item.', type: 'troubleshooting' },
      { q: 'Several EBS transactions land in a clearing account instead of auto-clearing against open items.', a: 'This is expected behavior for unmatched items, not a failed import — investigate the interpretation algorithm and external transaction code mapping for that specific bank/transaction type combination to close the matching gap.', type: 'troubleshooting' },
      { q: 'Client wants centralized payment execution across 12 regional entities from one internal payment factory.', a: 'Evaluate Advanced Payment Management, which is built specifically for centralized, multi-entity payment execution and routing rather than running 12 independent, uncoordinated F110 jobs.', type: 'scenario' },
      { q: 'Treasury flags an interest/cashflow discrepancy traced to an incorrect value date on a vendor payment.', a: 'Separate value date (bank processing date) from posting date and document date, and check the bank determination configuration\'s value date rules for that specific payment method/bank combination — this is a classic three-date confusion trap.', type: 'troubleshooting' },
      { q: 'A check shows as issued in SAP but the bank confirms it was never cashed after 18 months.', a: 'Investigate via the check register and apply the client\'s stale-check policy — likely resulting in a formal void/cancellation with an appropriate reason code, since SAP does not auto-expire outstanding checks.', type: 'scenario' },
      { q: 'Client asks whether In-House Cash could reduce their external banking fees across regional entities.', a: 'Yes — In-House Cash nets internal cash positions between entities before anything hits an external bank, directly reducing the volume (and associated fees) of external bank transactions.', type: 'scenario' },
      { q: 'A payment proposal\'s exception list shows several items with no clear reason given.', a: 'Drill into each exception individually — common causes include a missing or invalid bank detail on the vendor master, a payment method mismatch, or a block that was set after the proposal parameters were last run; the exception list groups symptoms, not root causes, so each item needs its own check.', type: 'troubleshooting' },
      { q: 'Client wants payments for two different payment methods to draw from two different bank accounts automatically.', a: 'Configure Bank Determination\'s ranking order so each payment method routes to its intended house bank/account combination — this is exactly the configuration block responsible for account-level payment routing.', type: 'scenario' },
      { q: 'An EBS import correctly matches 95% of transactions but consistently misses one specific recurring wire transfer type.', a: 'Check the Interpretation Algorithm and External Transaction code mapping specifically for that wire transfer type — a narrow, consistent miss usually points to one specific mapping gap rather than a broader EBS configuration problem.', type: 'troubleshooting' },
      { q: 'Client\'s treasury team wants a specific bank account to never be used until its available amount exceeds a threshold.', a: 'This is precisely what the Available Amount setting within Bank Determination controls — configure the threshold so that account is only used for payment selection once sufficient funds are confirmed available.', type: 'scenario' },
      { q: 'Auditor asks why a payment run selected a lower-priority bank account over the client\'s preferred primary account.', a: 'Check the Bank Determination ranking order and the Available Amount on the primary account — if the primary account\'s available amount was insufficient or exhausted for that run, the system correctly fell through to the next-ranked account per configuration.', type: 'troubleshooting' },
      { q: 'Client wants every voided check to carry a mandatory explanation for internal audit purposes.', a: 'Enforce Void Reason Code entry as a required field in the check cancellation process — this ensures every void carries a documented, auditable reason rather than being cancelled with no context.', type: 'scenario' },
      { q: 'A newly implemented bank\'s statement format isn\'t parsing correctly on import.', a: 'This typically requires a DMEE-based format definition update or review — the bank\'s specific file layout needs to be mapped correctly before EBS interpretation algorithms can even begin matching transactions.', type: 'troubleshooting' },
      { q: 'Client asks whether the payment proposal stage can be safely skipped to speed up the payment run process.', a: 'Not recommended — the Proposal stage is the manual review checkpoint where blocks, exceptions, and unexpected selections can be caught before actual payment documents and bank files are generated; skipping it removes a key control point.', type: 'conceptual' },
      { q: 'Auditor asks how the system prevents duplicate payment file generation for the same F110 run.', a: 'Once the Payment Medium stage generates the file for a completed payment run, that run\'s status is locked, and regenerating requires an explicit reprint/reissue process rather than allowing an accidental second file generation from the same run.', type: 'conceptual' },
      { q: 'Client wants Cash Management visibility to include payments still sitting in the F110 proposal stage, not yet finalized.', a: 'Confirm whether the Cash Management configuration is set to include proposed (not yet finalized) payment data — by default, some cash position views may only reflect confirmed payment runs, which would understate near-term outflows if proposals aren\'t included.', type: 'scenario' },
      { q: 'A vendor is paid via the wrong payment method despite the vendor master specifying a preference.', a: 'Check whether the invoice itself carries an override payment method distinct from the vendor master default — invoice-level payment method entries take precedence over the vendor master\'s default in the selection logic.', type: 'troubleshooting' },
      { q: 'Client asks whether DMEE changes require a full system regression test before go-live.', a: 'Yes — DMEE format changes affect the actual file sent to a bank, so a failed or malformed file can disrupt real payment processing; test file generation against the bank\'s specification (or a test environment they provide) before any production cutover.', type: 'scenario' },
      { q: 'Auditor asks what evidence demonstrates that bank determination is correctly prioritizing accounts per policy.', a: 'Show the configured ranking order in Bank Determination alongside a sample payment run\'s actual account selection, confirming the selected accounts followed the configured priority and available amount rules — this pairs configuration with observed behavior as audit evidence.', type: 'conceptual' },
    ],
  },
  'fi-day-8': {
    junior: [
      { q: 'What BP roles represent customer master data, mirroring the vendor-side pattern?', a: 'FLCU00 (general customer data) and FLCU01 (Company Code-specific customer data) — the direct parallel to FLVN00/01 on the vendor side.', type: 'conceptual' },
      { q: 'What is a Dunning Area used for?', a: 'Applying different dunning rules to different business units within a single Company Code, rather than requiring separate Company Codes for varying dunning policies.', type: 'conceptual' },
      { q: 'What object does FSCM Credit Management actually score and check limits against?', a: 'Credit Segment — not Credit Control Area directly. A mapping between Credit Segment and Credit Control Area must exist for the checks to resolve correctly.', type: 'conceptual' },
      { q: 'What is the difference between a static and dynamic credit check?', a: 'Static compares current exposure against the limit at a single point in time. Dynamic adds a forward-looking horizon window, factoring in expected future activity.', type: 'conceptual' },
      { q: 'Name two SD document points where a credit check can trigger.', a: 'Sales order creation and delivery creation (and goods issue) are all configurable trigger points, each independently evaluated against current credit exposure.', type: 'conceptual' },
      { q: 'What is the difference between item interest and balance interest calculation?', a: 'Item interest calculates per individual open item (e.g. late payment penalty on one invoice); balance interest calculates on the account\'s overall balance over a period — different use cases entirely.', type: 'conceptual' },
      { q: 'Is classic FD32-based credit management still the S/4-recommended approach?', a: 'No — FSCM Credit Management is mandatory in S/4HANA, and classic FD32-based logic is explicitly out of scope.', type: 'conceptual' },
      { q: 'What does a Dunning Block do?', a: 'Prevents a specific item or account from being dunned, even if it would otherwise be selected by the dunning run — used for disputes or known exceptions.', type: 'conceptual' },
      { q: 'What are Collections and Dispute Management used for, at an awareness level?', a: 'FSCM modules supporting structured collections work-lists (prioritized follow-up on overdue accounts) and formal dispute case tracking (documenting and resolving customer billing disputes).', type: 'conceptual' },
      { q: 'What determines a customer\'s approved credit exposure in FSCM?', a: 'Credit Profile, Risk Class, and Scoring Rules feed a limit request workflow that ultimately determines the approved credit exposure for that customer\'s Credit Segment.', type: 'conceptual' },
      { q: 'What is a Dunning Level?', a: 'A progressively escalating stage in the dunning procedure (e.g. level 1 reminder, level 4 final notice), each with its own text and grace day threshold.', type: 'conceptual' },
      { q: 'What is a Dunning Procedure?', a: 'The overall configuration object defining the sequence of dunning levels, grace days, minimum amounts, and interest calculation rules applied to a customer.', type: 'conceptual' },
      { q: 'What is Bills of Exchange Receivable, at an awareness level?', a: 'A payment instrument where the customer formally commits to pay by a future date, tracked separately from standard open items until honored or discounted.', type: 'conceptual' },
      { q: 'What is a Credit Exposure Category?', a: 'A classification (open order, open delivery, open receivable) FSCM uses to categorize different types of exposure feeding into total credit exposure calculation.', type: 'conceptual' },
      { q: 'What does a Risk Class do in FSCM Credit Management?', a: 'Groups customers by risk profile, which then feeds the credit limit determination and scoring rules applied during the limit request workflow.', type: 'conceptual' },
      { q: 'What is the difference between a customer down payment and a customer credit memo?', a: 'A down payment is an advance payment received before invoicing, using special G/L logic; a credit memo reduces an existing invoiced amount, typically for returns or billing corrections.', type: 'conceptual' },
      { q: 'What is a Dunning Notice?', a: 'The output document (letter, email) generated by the dunning run, informing the customer of overdue items at their current dunning level.', type: 'conceptual' },
      { q: 'What triggers Dispute Case creation in FSCM Dispute Management?', a: 'A customer contesting all or part of an invoice, which creates a structured case tracking the dispute reason, resolution status, and linked open item.', type: 'conceptual' },
      { q: 'What does a Collections Strategy define?', a: 'Rules prioritizing which overdue customer accounts collections staff should work first, based on factors like exposure size, days overdue, and risk class.', type: 'conceptual' },
      { q: 'Can a customer be assigned to more than one Dunning Area?', a: 'No — a customer\'s open items are dunned under one applicable Dunning Area at a time per Company Code, even if the client has multiple Dunning Areas configured.', type: 'conceptual' },
      { q: 'What is the purpose of a minimum dunning amount?', a: 'Preventing the dunning run from generating notices for trivially small overdue balances, avoiding unnecessary customer friction over immaterial amounts.', type: 'conceptual' },
      { q: 'What does "credit exposure" include beyond just open invoices?', a: 'Open sales orders, open deliveries not yet invoiced, and open receivables — the full pipeline of potential financial exposure, not just posted invoices.', type: 'conceptual' },
      { q: 'What is the relationship between Dunning Block and Payment Block?', a: 'A Dunning Block only prevents dunning notices; a Payment Block prevents automatic payment selection — an item can have one, both, or neither independently.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A client complains a clearly overdue customer never received a dunning notice.', a: 'Check grace days, minimum dunning amount thresholds, any dunning block on the item or account, a payment block, and the account\'s last-dunned date — this multi-factor chain is the standard troubleshooting approach.', type: 'troubleshooting' },
      { q: 'A sales order passes credit check, but the subsequent delivery for the same customer and amount is blocked.', a: 'Other orders likely consumed available credit exposure in the time between the two check points — credit checks evaluate exposure independently at each configured SD trigger point, so the outcome can legitimately change between order and delivery.', type: 'troubleshooting' },
      { q: 'Client wants entity-level credit exposure visibility while still rolling up to one group-wide risk view.', a: 'Map each Company Code to its own Credit Segment for entity-level visibility, while keeping a single shared Credit Control Area for the group-level rollup — this mirrors the design question first raised in FI Day 1.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents a customer from being dunned twice for the same item within the grace period.', a: 'The account\'s last-dunned date combined with the dunning procedure\'s configured grace days prevents re-dunning too soon after a prior notice — this is a built-in control, not a manual check.', type: 'conceptual' },
      { q: 'A newly onboarded customer\'s credit limit request sits with no clear approver, causing delays.', a: 'Check the FSCM limit request workflow\'s routing rules — risk class and credit profile typically determine routing, and a gap in that configuration is the most likely reason a request goes unassigned.', type: 'troubleshooting' },
      { q: 'Client\'s interest calculation shows different results for the same overdue balance across two reports.', a: 'Confirm whether item interest or balance interest is configured for each scenario — they legitimately use different calculation bases and will produce different, both-correct results rather than indicating a system error.', type: 'troubleshooting' },
      { q: 'A customer dispute is resolved but the disputed invoice still shows as fully overdue in dunning.', a: 'Check whether the Dispute Case was correctly linked to the open item and closed — if the linkage or closure step was missed, dunning continues treating the item as a standard overdue balance rather than one under resolved dispute.', type: 'troubleshooting' },
      { q: 'Client wants collections staff to prioritize their largest at-risk accounts automatically each morning.', a: 'Configure a Collections Strategy weighting exposure size, days overdue, and risk class — this generates a prioritized work-list rather than requiring manual triage each day.', type: 'scenario' },
      { q: 'Two customers with identical overdue amounts receive different dunning treatment.', a: 'Check whether they are assigned to different Dunning Areas or Dunning Procedures — differing grace days, minimum amounts, or dunning levels between areas legitimately produce different treatment for the same overdue amount.', type: 'troubleshooting' },
      { q: 'Auditor asks how the system prevents dunning notices for immaterial overdue balances from cluttering customer communications.', a: 'The minimum dunning amount threshold configured on the dunning procedure suppresses notice generation for balances below that materiality level.', type: 'conceptual' },
      { q: 'Client\'s FSCM credit exposure calculation seems to undercount risk for customers with many open (not yet invoiced) deliveries.', a: 'Verify the relevant Credit Exposure Categories (open delivery, in particular) are included in the exposure calculation configuration — if a category is excluded, that portion of the pipeline won\'t contribute to total exposure.', type: 'troubleshooting' },
      { q: 'Client wants a specific high-value customer excluded from automatic dunning entirely, handled manually by an account manager instead.', a: 'Apply a Dunning Block at the customer master level — this removes the account from automatic dunning runs while the account manager handles collections manually and can release the block if that changes.', type: 'scenario' },
      { q: 'A Bills of Exchange Receivable is discounted with a bank before its due date.', a: 'This creates a contingent liability posting since the bank has advanced funds against the not-yet-matured bill; if the customer fails to honor it, the liability could revert to the company, which should be tracked separately from a standard cleared receivable.', type: 'conceptual' },
      { q: 'Client asks whether Risk Class assignment can change for a customer mid-year based on changing payment behavior.', a: 'Yes — Risk Class is master data that can be reassessed and updated as a customer\'s payment history evolves, which then flows into future credit limit and scoring calculations.', type: 'scenario' },
      { q: 'Auditor asks for evidence that a specific customer\'s credit limit was appropriately approved before activation.', a: 'Pull the FSCM limit request workflow history for that customer, showing the risk class/credit profile-driven routing and the specific approver\'s sign-off before the limit went live.', type: 'conceptual' },
      { q: 'Client\'s dunning run is producing notices for customers who made payment the same day, before the run executed.', a: 'This is a timing issue, not a configuration error — the dunning run reflects open items as of its execution time; same-day payments processed after the run naturally won\'t be reflected until the next run.', type: 'troubleshooting' },
      { q: 'Client wants a single dunning procedure but different grace days for two business units within one Company Code.', a: 'Use Dunning Areas to achieve this — one Company Code can have multiple Dunning Areas, each with independently configured grace days and rules, without needing a separate dunning procedure per unit.', type: 'scenario' },
      { q: 'A dispute case remains open for months with no resolution activity logged.', a: 'This is an operational red flag worth escalating — an aging, inactive dispute case risks both cash flow (the disputed amount stays uncollected) and customer relationship deterioration if left unmanaged.', type: 'scenario' },
      { q: 'Auditor asks how the system\'s credit and dunning processes work together to manage overall customer risk.', a: 'Credit Management controls new exposure at the front end (blocking new orders/deliveries when limits are exceeded), while Dunning manages existing overdue exposure after invoicing — together they form a front-and-back-end risk control pair.', type: 'conceptual' },
    ],
  },
  'fi-day-9': {
    junior: [
      { q: 'Are delta depreciation areas still used in S/4HANA?', a: 'No — they are eliminated entirely under New Asset Accounting, since every depreciation area now posts in real time, removing the need for a delayed "delta" catch-up area.', type: 'conceptual' },
      { q: 'What is the Technical Clearing Account used for?', a: 'It splits an integrated asset acquisition posting into an operational part (goods/invoice side) and a valuating part (asset capitalization side), reconciled through that account — mandatory for integrated acquisitions.', type: 'conceptual' },
      { q: 'Does Assets under Construction (AuC) normally carry depreciation?', a: 'No, normally not — the asset isn\'t yet in service — but there are defined exceptions depending on local statutory requirements.', type: 'conceptual' },
      { q: 'Where do asset line items live in S/4HANA, replacing ANEP/ANLP?', a: 'In ACDOCA — asset postings are absorbed into the single Universal Journal table, just like FI, CO, and material ledger postings.', type: 'conceptual' },
      { q: 'What does a Depreciation Key combine?', a: 'A base method, declining balance method, multilevel method, and period control rules — together fully determining how depreciation is calculated for assets in that class.', type: 'conceptual' },
      { q: 'What is the difference between Fiscal Year Change and Year-End Closing for assets?', a: 'Fiscal Year Change opens the new fiscal year for postings without closing the prior year; Year-End Closing is the later, separate step that locks the prior year after all depreciation and adjustments are complete.', type: 'conceptual' },
      { q: 'What is AuC line item settlement?', a: 'The process by which accumulated costs on an investment order or WBS element serving as AuC settle to one or more final fixed assets once the capital project completes.', type: 'conceptual' },
      { q: 'Is area 01 still privileged in S/4HANA the way it was in ECC?', a: 'No — every depreciation area posts in real time on equal footing; there is no single structurally privileged area anymore.', type: 'conceptual' },
      { q: 'What is the difference between planned and posted depreciation?', a: 'Planned depreciation is what the depreciation key calculates should happen; posted depreciation is what has actually been run and posted via the periodic depreciation program.', type: 'conceptual' },
      { q: 'What is Post-Capitalization used for?', a: 'Capitalizing an asset discovered or recognized after its original acquisition period — handling the retroactive booking of an asset that should have been capitalized earlier.', type: 'conceptual' },
      { q: 'What is the difference between a main asset and a sub-asset?', a: 'A main asset is the primary asset record; sub-assets represent components or subsequent additions tracked separately but rolled up under the same main asset for reporting.', type: 'conceptual' },
      { q: 'What is Time-Dependent data on an asset master?', a: 'Fields like cost center or location that can change over the asset\'s life, tracked with effective dates so historical assignment history is preserved.', type: 'conceptual' },
      { q: 'What are the four types of asset transactions covered in FI Day 9?', a: 'Acquisition, transfer (intra- or inter-company), retirement (sale or scrapping), and post-capitalization.', type: 'conceptual' },
      { q: 'What is an Intra-Company Asset Transfer?', a: 'Moving an asset between cost centers, plants, or asset classes within the same Company Code, without a change in legal ownership.', type: 'conceptual' },
      { q: 'What is an Inter-Company Asset Transfer?', a: 'Moving an asset between two different Company Codes, which typically requires a sale/purchase-style posting since it crosses a legal entity boundary.', type: 'conceptual' },
      { q: 'What is Unplanned Depreciation?', a: 'A manual, one-time depreciation posting outside the normal periodic schedule, typically used for impairments or unexpected write-downs.', type: 'conceptual' },
      { q: 'What does the Asset History Sheet report show?', a: 'A summary of an asset class\'s (or individual asset\'s) acquisition, transfers, retirements, and depreciation activity over a reporting period.', type: 'conceptual' },
      { q: 'What is Asset Explorer used for?', a: 'A detailed, interactive view of a single asset\'s planned and posted values across all depreciation areas, useful for investigating a specific asset\'s financial history.', type: 'conceptual' },
      { q: 'What is a Base Method within a Depreciation Key?', a: 'The fundamental calculation approach (straight-line, declining balance, etc.) the depreciation key applies before period control rules refine the timing.', type: 'conceptual' },
      { q: 'What does Period Control within a Depreciation Key determine?', a: 'How depreciation is prorated in the period an asset is acquired, transferred, or retired (e.g. full month vs. pro-rata based on the exact date).', type: 'conceptual' },
      { q: 'What is an Asset Class?', a: 'A grouping of similar assets (e.g. machinery, vehicles, buildings) that determines the default account determination, screen layout, and number range for assets created within it.', type: 'conceptual' },
      { q: 'What is Screen Layout in the context of asset master data?', a: 'Configuration controlling which fields are required, optional, or suppressed on the asset master record, similar in spirit to Field Status Groups for G/L accounts.', type: 'conceptual' },
      { q: 'What is Account Determination for an asset class?', a: 'Configuration linking the asset class to the specific G/L accounts (acquisition, accumulated depreciation, depreciation expense) used for postings involving that class.', type: 'conceptual' },
      { q: 'What is retirement with revenue vs. retirement by scrapping?', a: 'Retirement with revenue records a sale and the resulting gain/loss; scrapping retires the asset with no revenue, typically recognizing a full loss of remaining book value.', type: 'conceptual' },
      { q: 'What is the purpose of the fiscal year change program for assets specifically?', a: 'It opens the new fiscal year in Asset Accounting for postings, distinct from and required before the separate year-end closing step that locks the prior year.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A batch of assets fails the depreciation run with no obvious single pattern.', a: 'Check each failing asset for a closed posting period, incomplete asset master data, a blocked asset status, or a ledger mismatch on the relevant depreciation area — this is the standard multi-factor diagnostic chain.', type: 'troubleshooting' },
      { q: 'A CFO is confused why an asset acquisition appears to post as two distinct entries instead of one clean posting.', a: 'This is the Technical Clearing Account design at work — operational (goods/invoice) and valuating (capitalization) parts are intentionally separated and reconciled through it, which is standard behavior for integrated acquisitions in New Asset Accounting.', type: 'conceptual' },
      { q: 'An AuC project unexpectedly shows depreciation postings when none were expected.', a: 'Check whether this AuC falls under one of the defined local-statutory exceptions requiring depreciation, rather than assuming the "AuC normally doesn\'t depreciate" default rule applies universally without exception.', type: 'troubleshooting' },
      { q: 'A capital project (WBS-based AuC) needs to settle to three different final assets with different useful lives.', a: 'AuC line item settlement supports distributing accumulated costs from one WBS/AuC object to multiple final assets, each then independently carrying its own depreciation key and useful life going forward.', type: 'scenario' },
      { q: 'Auditor questions why local statutory and group/IFRS depreciation areas show different values for the same physical asset.', a: 'This is expected — multiple depreciation areas mapped to different accounting principles legitimately calculate and post different depreciation values for the same asset; forcing them to match would be incorrect, not corrective.', type: 'conceptual' },
      { q: 'Client asks whether area 01 needs any special handling during a system conversion to S/4HANA.', a: 'No special privileged treatment is needed post-conversion — under New Asset Accounting every depreciation area posts in real time equally, so area 01 should be treated the same as any other configured area going forward.', type: 'scenario' },
      { q: 'An asset transfer between two Company Codes fails to post correctly.', a: 'Confirm this is being handled as an Inter-Company Asset Transfer with its sale/purchase-style posting logic — a standard intra-company transfer transaction will not correctly handle the legal entity boundary crossing.', type: 'troubleshooting' },
      { q: 'Client wants to record an unexpected mid-year impairment on a piece of equipment outside the normal depreciation schedule.', a: 'Post Unplanned Depreciation — this one-time manual posting exists specifically for impairments and write-downs that fall outside the periodic depreciation program\'s normal schedule.', type: 'scenario' },
      { q: 'A newly created asset class has no G/L postings occurring for assets created within it.', a: 'Check the asset class\'s Account Determination configuration — a missing or incomplete mapping to the required G/L accounts (acquisition, depreciation, accumulated depreciation) will block or misdirect postings.', type: 'troubleshooting' },
      { q: 'Client\'s asset history sheet shows a transfer but the underlying cost center reassignment isn\'t reflected on the asset master.', a: 'Check the asset\'s Time-Dependent data — cost center changes should be recorded with an effective date on the time-dependent segment; a mismatch suggests the transfer wasn\'t fully processed through the proper time-dependent update.', type: 'troubleshooting' },
      { q: 'A retired asset shows an unexpected gain despite the client scrapping it with no sale.', a: 'Verify whether the retirement was processed as retirement with revenue rather than scrapping — a mistakenly recorded sale price, even a small one, generates a gain/loss calculation that pure scrapping would not.', type: 'troubleshooting' },
      { q: 'Client wants a detailed investigation into why one specific asset\'s depreciation seems inconsistent with its peers in the same class.', a: 'Use Asset Explorer to review that specific asset\'s depreciation key, base method, and period control settings across all depreciation areas — an individually overridden depreciation key on the asset master (rather than the class default) is a common cause of peer inconsistency.', type: 'troubleshooting' },
      { q: 'Auditor asks how the system prevents an asset from being depreciated past its planned useful life.', a: 'The depreciation key\'s base method and useful life configuration on the asset master stop generating further planned depreciation once the asset is fully depreciated — this is a structural limit, not a manual monitoring task.', type: 'conceptual' },
      { q: 'Client wants sub-assets to track separately-depreciable improvements made to a main asset over time.', a: 'Create sub-assets under the main asset — sub-assets can carry their own depreciation start date and useful life while still rolling up to the main asset for consolidated reporting.', type: 'scenario' },
      { q: 'A client\'s fiscal year change program run fails partway through for one Company Code.', a: 'Investigate the specific assets or asset classes causing the failure — common causes include incomplete asset master data or a status (like being blocked) that prevents the year-change program from processing that asset cleanly; a partial failure needs isolation, not a full restart assumption.', type: 'troubleshooting' },
      { q: 'Client asks whether Period Control settings can differ between acquisition and retirement for the same asset class.', a: 'Yes — Period Control is configured per transaction type within the depreciation key, so acquisition proration rules can differ from retirement proration rules for the same asset class.', type: 'conceptual' },
      { q: 'A capital project settles to a Fixed Asset, but the resulting asset\'s screen layout is missing an expected field.', a: 'Check the target asset class\'s Screen Layout configuration — a field missing at the class level won\'t appear on any asset created under it, regardless of what data the settling project intended to pass through.', type: 'troubleshooting' },
      { q: 'Client wants evidence that all assets acquired this fiscal year have been correctly capitalized before year-end close.', a: 'Run the Asset History Sheet for the fiscal year, filtered to acquisitions, and cross-check against expected capital additions from the capital budget — this is the standard reconciliation approach before locking the year.', type: 'conceptual' },
      { q: 'Auditor asks why an intra-company transfer between two plants didn\'t trigger any gain/loss recognition.', a: 'This is expected — intra-company transfers move an asset within the same legal entity with no change in ownership, so no sale/purchase economic event occurs and no gain/loss should be recognized, unlike an inter-company transfer.', type: 'conceptual' },
      { q: 'Client\'s asset explorer shows different planned depreciation values across depreciation areas for the same asset in the same period.', a: 'This is expected when multiple depreciation areas represent different accounting principles with different depreciation keys or useful lives assigned — divergent planned values across areas reflect legitimate parallel valuation, not an error.', type: 'conceptual' },
    ],
  },
  'fi-day-10': {
    junior: [
      { q: 'What is the difference between realized and unrealized FX gain/loss?', a: 'Realized gain/loss comes from actual settlement of a transaction; unrealized is a period-end valuation estimate on still-open items, typically designed to reverse the following period.', type: 'conceptual' },
      { q: 'What causes the classic "account missing from balance sheet" symptom?', a: 'An unassigned node in the Financial Statement Version — every G/L account needs an explicit FSV hierarchy assignment, and an unassigned account simply won\'t appear in the generated statement.', type: 'conceptual' },
      { q: 'Can Balance Carryforward be rerun after the initial run?', a: 'Yes — it is designed to be rerunnable to reflect any corrections made after the first carryforward, rather than being a strictly one-time, irreversible action.', type: 'conceptual' },
      { q: 'What is the difference between conversion, valuation, and translation?', a: 'Conversion happens at transaction/posting time; valuation revalues existing open balances at period-end; translation applies specifically to consolidated group reporting across entities with different functional currencies.', type: 'conceptual' },
      { q: 'What does GR/IR regrouping accomplish?', a: 'It reclassifies goods-receipt/invoice-receipt mismatches for correct balance sheet presentation at period-end, separate from any FX valuation activity.', type: 'conceptual' },
      { q: 'What is the role of the Financial Closing Cockpit / Advanced Financial Closing?', a: 'Orchestrating and tracking the close checklist itself — task dependencies, status, and sign-offs — turning an informal checklist into a governed, auditable workflow.', type: 'conceptual' },
      { q: 'Where does Embedded Analytics report from, and what does that eliminate?', a: 'Directly and live off ACDOCA via CDS views and Fiori analytical apps, eliminating the separate ETL/data-warehouse extraction step that ECC-era reporting typically required.', type: 'conceptual' },
      { q: 'What does receivables/payables regrouping by remaining maturity achieve?', a: 'It reclassifies receivables and payables between short-term and long-term categories based on remaining time to maturity, for accurate balance sheet aging presentation.', type: 'conceptual' },
      { q: 'What are exchange rate types M, B, and G used for?', a: 'M is the standard/average rate, B is the bank buying rate, and G is the bank selling rate — each maintained with its own translation ratios for different valuation or translation purposes.', type: 'conceptual' },
      { q: 'Why does the FI close checklist need to run in a specific order?', a: 'Later steps depend on earlier ones being complete — for example, FX valuation and balance carryforward need finalized sub-ledger balances, so running them out of order produces numbers that don\'t reflect the true period-end position.', type: 'conceptual' },
      { q: 'What is the standard FI month-end close sequence at a high level?', a: 'Sub-ledger closes (AP/AR) → GR/IR regrouping → FX valuation → accruals/deferrals → balance carryforward validation → financial statement generation.', type: 'conceptual' },
      { q: 'What is a Valuation Method in FX valuation configuration?', a: 'The rule set defining how open items and balances get revalued (which exchange rate type to use, lowest-value principle application, and rounding), assigned to a Valuation Area.', type: 'conceptual' },
      { q: 'What is a Valuation Area?', a: 'A grouping used to apply a specific valuation method and purpose (e.g. one for statutory reporting, one for a different accounting principle) to FX valuation runs.', type: 'conceptual' },
      { q: 'What does "lowest value principle" mean in FX valuation, at a conceptual level?', a: 'A conservative valuation rule ensuring assets aren\'t revalued upward beyond their original booked value even if the current exchange rate would suggest a higher figure, common in certain statutory frameworks.', type: 'conceptual' },
      { q: 'What is the purpose of receivables/payables regrouping beyond currency?', a: 'Reclassifying amounts between short-term and long-term balance sheet categories based on remaining time to maturity, independent of any currency valuation activity.', type: 'conceptual' },
      { q: 'What triggers a manual accrual reversal versus an Accrual-Engine-managed one (from FI Day 4)?', a: 'A manual accrual requires the preparer to enter both the original and reversing entry by hand each period; an Accrual-Engine-managed one reverses automatically per its configured schedule.', type: 'conceptual' },
      { q: 'What does a Financial Statement Version (FSV) node hierarchy represent?', a: 'The tree structure grouping G/L accounts into balance sheet and P&L line items in the order and grouping required for external reporting presentation.', type: 'conceptual' },
      { q: 'Can one Company Code use more than one Financial Statement Version?', a: 'Yes — different FSVs can be used for different reporting purposes (e.g. one for statutory local reporting, one for group reporting) from the same underlying G/L data.', type: 'conceptual' },
      { q: 'What does the Advanced Financial Closing (or Financial Closing Cockpit) task template define?', a: 'The reusable set of close tasks, their sequence, dependencies, and responsible parties, applied consistently period over period rather than rebuilt manually each cycle.', type: 'conceptual' },
      { q: 'What is a KPI tile in the context of embedded analytics?', a: 'A Fiori Launchpad visual element showing a summarized live metric (e.g. days sales outstanding) that a user can click into for underlying detail, all reading directly from ACDOCA.', type: 'conceptual' },
      { q: 'What does the Trial Balance app show?', a: 'A live, period-based summary of G/L account balances, typically the first-stop app for month-end close review before generating full financial statements.', type: 'conceptual' },
      { q: 'What is the difference between the source currency and the target currency in an FX valuation run?', a: 'Source currency is the currency the open item/balance is denominated in; target currency is the reporting currency it\'s being revalued into for that valuation area\'s purpose.', type: 'conceptual' },
      { q: 'What does "Display Financial Statements" app provide beyond the Trial Balance app?', a: 'A fully formatted balance sheet and P&L output following the assigned Financial Statement Version hierarchy, rather than just a flat account-level balance list.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A P&L account\'s balance flows to the wrong Retained Earnings Account after year-end close.', a: 'Check that account\'s P&L Statement Account Type mapping from FI Day 3 — an incorrect or changed mapping sends the carryforward to the wrong retained earnings account, and this is the most likely root cause.', type: 'troubleshooting' },
      { q: 'A G/L account with clear postings is entirely missing from the client\'s balance sheet.', a: 'Check Financial Statement Version assignment first — the account is most likely sitting on an unassigned node and needs to be explicitly mapped into the FSV hierarchy.', type: 'troubleshooting' },
      { q: 'An unrealized FX loss posted last period doesn\'t appear reversed this period.', a: 'Check whether the FX valuation reversal run was actually executed this period — reversal of an unrealized valuation is typically a distinct, deliberate step, not something that happens automatically without running it.', type: 'troubleshooting' },
      { q: 'Client wants clear documentation distinguishing transaction-time currency handling from period-end revaluation.', a: 'Explain conversion (posting time, that day\'s rate) versus valuation (period-end revaluation of existing open balances using a configured valuation method/area) — this distinction is a common conceptual trap worth documenting explicitly.', type: 'conceptual' },
      { q: 'Client asks whether embedded analytics can fully replace their legacy BW-based month-end reporting.', a: 'For standard trial balance and financial statement reporting off ACDOCA, yes, with no ETL required; more complex, multi-system consolidation scenarios may still warrant BW/BPC-based tooling alongside it.', type: 'scenario' },
      { q: 'Design the reasoning for why sub-ledger closes must happen before FX valuation and balance carryforward in the close checklist.', a: 'Sub-ledger closes (AP/AR) finalize open items first; FX valuation needs to revalue a stable set of open items, and carryforward needs final period balances — running these out of sequence produces numbers that don\'t genuinely reflect the true period-end position.', type: 'conceptual' },
      { q: 'Client wants two different FX valuation results — one for statutory local reporting and one for group IFRS reporting — from the same open items.', a: 'Configure two separate Valuation Areas, each with its own Valuation Method appropriate to that reporting purpose, both running against the same underlying open items but producing separately reportable revalued figures.', type: 'scenario' },
      { q: 'Auditor questions why an asset\'s FX valuation wasn\'t revalued upward despite a favorable exchange rate movement.', a: 'Check whether the Valuation Method applies a lowest-value principle — some statutory frameworks conservatively prevent upward revaluation of certain balance sheet items even when the current rate would justify it.', type: 'conceptual' },
      { q: 'Client\'s receivables aging report shows a large receivable still classified as short-term despite being due in 18 months.', a: 'Check whether receivables/payables regrouping ran for that period and correctly reclassified the item to long-term based on remaining maturity — a skipped or misconfigured regrouping run leaves stale short/long-term classifications in place.', type: 'troubleshooting' },
      { q: 'Client wants a repeatable, auditable close process instead of relying on one experienced controller\'s personal checklist.', a: 'Build an Advanced Financial Closing task template capturing the sequence, dependencies, and responsible parties for every close step — this converts tribal knowledge into a governed, repeatable process independent of any one person.', type: 'scenario' },
      { q: 'Two Financial Statement Versions produce materially different total assets for the same underlying G/L balances.', a: 'This is possible and not necessarily an error — different FSVs can group accounts differently (e.g. presenting certain reserves as liabilities vs. equity under different frameworks), so a total difference reflects presentation choice, not data inconsistency, provided the underlying account-level data matches.', type: 'conceptual' },
      { q: 'A KPI tile on the Fiori Launchpad shows a number that doesn\'t match a detailed report pulled the same day.', a: 'Check whether the tile and the report are reading from the same point in time and the same scope (e.g. one might refresh on a schedule while the other queries live) — since both should read from ACDOCA, a genuine mismatch usually points to a scope or filter difference rather than a data source discrepancy.', type: 'troubleshooting' },
      { q: 'Client asks whether they can skip the Trial Balance review step and go straight to generating financial statements.', a: 'Not recommended — Trial Balance review is the standard checkpoint for catching account-level anomalies (unexpected balances, missing FSV assignments) before they propagate into a formatted statement, where they\'re harder to spot amid presentation formatting.', type: 'scenario' },
      { q: 'Auditor asks how the close checklist accounts for the possibility that a sub-ledger close needs to be reopened after an error is found.', a: 'A well-designed Advanced Financial Closing template includes a defined reopen/rework path with re-validation steps, rather than assuming the sequence only ever runs forward without exception — real closes need a documented way to handle a caught error without abandoning the whole sequence.', type: 'conceptual' },
      { q: 'Client\'s FX valuation run appears to have used a stale exchange rate.', a: 'Check whether the exchange rate table was updated for the relevant rate type before the valuation run executed — FX valuation uses whatever rate is currently maintained for the configured rate type/date, so a missed rate update directly causes a stale valuation.', type: 'troubleshooting' },
      { q: 'Client wants confirmation that their embedded analytics KPI tiles will still work correctly after a Financial Statement Version change.', a: 'KPI tiles reading raw ACDOCA balances by account/dimension are generally unaffected by an FSV change, since FSV only affects presentation hierarchy for formatted statements — but any tile specifically built around FSV-based groupings would need review and possible reconfiguration.', type: 'scenario' },
      { q: 'A Company Code\'s balance carryforward run completes, but a subsequent correction to a prior-year P&L account is posted afterward.', a: 'Rerun balance carryforward for the affected fiscal year — since carryforward is designed to be rerunnable, this properly re-rolls the corrected P&L balance into retained earnings without requiring a full close reversal.', type: 'scenario' },
      { q: 'Client asks why their statutory Valuation Area shows a different revalued figure than their group reporting Valuation Area for the identical open item.', a: 'Each Valuation Area applies its own configured Valuation Method (potentially different rate types, lowest-value rules, or rounding) — divergent revalued figures across areas for the same open item are expected when the methods genuinely differ, not a data error.', type: 'conceptual' },
      { q: 'Auditor asks how the system ensures GR/IR regrouping doesn\'t double-count an item already cleared through normal invoice receipt processing.', a: 'Regrouping only reclassifies items still open in GR/IR at the regrouping run\'s cutoff — an item already fully cleared through IR before that point is no longer in the open GR/IR pool and is structurally excluded from the regrouping calculation.', type: 'conceptual' },
    ],
  },
  'co-day-1': {
    junior: [
      { q: 'How is a Controlling Area assigned to Company Codes?', a: 'A Controlling Area can be assigned 1:N — covering multiple Company Codes — while each Company Code belongs to exactly one Controlling Area.', type: 'conceptual' },
      { q: 'What two things must match across every Company Code sharing a Controlling Area?', a: 'The operating chart of accounts and the fiscal year variant — both are hard prerequisites for real-time FI-CO integration to function across the Controlling Area.', type: 'conceptual' },
      { q: 'What is Version 0 and why is it treated specially?', a: 'Version 0 is the mandatory, official plan version that standard reporting compares actuals against; additional versions support scenario planning without disturbing this baseline.', type: 'conceptual' },
      { q: 'What distinguishes a true CO object from a statistical one?', a: 'A true object can receive real cost postings and be settled/allocated from; a statistical object receives only an informational copy of a posting whose real cost lives on a different, true object.', type: 'conceptual' },
      { q: 'What three currencies are tracked on every CO posting?', a: 'Controlling Area currency, Object currency (the cost center/order\'s own), and Transaction currency (the currency of the original posted document).', type: 'conceptual' },
      { q: 'Why does S/4HANA not need a reconciliation ledger like ECC did?', a: 'Because FI and CO postings are the same Universal Journal document rather than two separate documents that could drift out of sync — there is structurally nothing to reconcile.', type: 'conceptual' },
      { q: 'What components make up the CO Component Map?', a: 'Cost Center Accounting, Internal Orders, Profit Center Accounting, Product Costing, and Margin Analysis — all sitting under one Controlling Area.', type: 'conceptual' },
      { q: 'Why are CO actual and plan postings kept on separate number ranges?', a: 'To maintain a clean, document-level separation between actual data and planning data, preventing the two from being ambiguously mixed in reporting or audit trails.', type: 'conceptual' },
      { q: 'What is Object Currency specifically tied to?', a: 'The currency of the individual CO object (a cost center or order), which can differ from both the Controlling Area currency and the transaction currency on a given posting.', type: 'conceptual' },
      { q: 'Can a Controlling Area contain Company Codes using different local currencies?', a: 'Yes — each Company Code retains its own local currency; the Controlling Area currency provides a common reporting currency for cross-CC CO reporting regardless of local currency differences.', type: 'conceptual' },
      { q: 'What is the relationship between Controlling Area and Operating Concern (CO-9 preview)?', a: 'An Operating Concern must be assigned to and activated for a Controlling Area before Margin Analysis postings can flow — a later-tab dependency rooted in this Day 1 org structure.', type: 'conceptual' },
      { q: 'What does "1:N" mean when describing Controlling Area to Company Code assignment?', a: 'One Controlling Area can be assigned to many Company Codes, but never the reverse — a Company Code cannot belong to more than one Controlling Area.', type: 'conceptual' },
      { q: 'Why is Controlling Area described as the "foundation" this entire CO section builds on?', a: 'Every subsequent CO tab (cost centers, orders, profit centers, product costing, margin analysis) operates within the scope of a Controlling Area, so its structure and prerequisites propagate forward into every later configuration decision.', type: 'conceptual' },
      { q: 'What happens to CO reporting if a Company Code is later reassigned to a different Controlling Area?', a: 'Historical CO data tied to the original Controlling Area does not automatically move; this is a significant structural change requiring careful data migration planning, not a routine reassignment.', type: 'conceptual' },
      { q: 'Is Version 0 configurable, or is it entirely fixed by SAP?', a: 'Version 0 is configurable (currency settings, plan/actual comparison rules) but its role as the mandatory official baseline version cannot be removed or replaced by another version.', type: 'conceptual' },
      { q: 'What is the practical difference between Controlling Area currency and Group currency (FI Day 1)?', a: 'Controlling Area currency is used for CO-internal reporting consistency across the Controlling Area\'s Company Codes; Group currency (from FI Day 1) is a broader FI/consolidation-level currency type that can differ in purpose and configuration.', type: 'conceptual' },
      { q: 'Can two Controlling Areas exist within one client?', a: 'Yes — a client can have multiple Controlling Areas, typically used when Company Codes have genuinely incompatible operating charts of accounts or fiscal year variants that can\'t be harmonized into one shared Controlling Area.', type: 'conceptual' },
      { q: 'What CO reporting risk arises from having multiple Controlling Areas in one client?', a: 'Cross-Controlling-Area reporting requires additional consolidation effort since CO data doesn\'t natively roll up across separate Controlling Areas the way it does within one — a design tradeoff worth surfacing early.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Two Company Codes are about to share a Controlling Area but use different operating charts of accounts.', a: 'Flag this before assignment — harmonize to one shared operating chart of accounts first, since mismatched charts break real-time FI-CO integration across the Controlling Area.', type: 'troubleshooting' },
      { q: 'A cost report shows an unexpected cost location and the consultant must determine if it is real or statistical.', a: 'Check whether that object can be the target of settlement/allocation; if it only carries an informational copy, it is statistical, and the true cost is posted elsewhere.', type: 'troubleshooting' },
      { q: 'Client wants to run a what-if planning scenario without disturbing official numbers.', a: 'Create a new, non-Version-0 planning version — Version 0 remains the untouched official baseline for standard reporting throughout the scenario exercise.', type: 'scenario' },
      { q: 'Auditor asks how S/4 structurally prevents the FI-CO sync gaps that occasionally occurred in ECC.', a: 'FI and CO share one Universal Journal document rather than being separately maintained and reconciled — the sync gap is eliminated by design, not by a periodic reconciliation process.', type: 'conceptual' },
      { q: 'A newly onboarded subsidiary\'s fiscal year variant differs from the rest of its intended Controlling Area.', a: 'Resolve this before assignment — mismatched fiscal year variants misalign period boundaries and break CO allocations across the shared Controlling Area.', type: 'scenario' },
      { q: 'Client proposes merging CO actual and plan number ranges to simplify configuration.', a: 'Push back — the separation exists specifically to keep actual and plan data cleanly distinguishable at the document level; collapsing them removes a deliberate data-integrity boundary.', type: 'scenario' },
      { q: 'Client has two divisions with genuinely incompatible fiscal year variants that cannot be harmonized for business reasons.', a: 'Recommend two separate Controlling Areas rather than forcing an artificial harmonization — accept the tradeoff of needing additional cross-Controlling-Area consolidation effort in exchange for each division keeping its legitimately required fiscal year variant.', type: 'scenario' },
      { q: 'Auditor asks how Controlling Area currency differs functionally from Company Code local currency in cross-CC reporting.', a: 'Controlling Area currency gives CO reporting a single common currency across every Company Code in that Controlling Area regardless of their differing local currencies, enabling apples-to-apples cross-CC cost comparison that local-currency-only reporting couldn\'t provide.', type: 'conceptual' },
      { q: 'Client wants to reassign a Company Code from one Controlling Area to another after two years of postings.', a: 'Treat this as a significant structural migration project, not a routine config change — historical CO data tied to the original Controlling Area doesn\'t automatically follow, and a careful data migration/reporting continuity plan is required before making the change.', type: 'scenario' },
      { q: 'A cost center report shows costs in a currency the consultant didn\'t expect for that object.', a: 'Check whether the report is displaying Object Currency, Controlling Area currency, or Transaction currency — all three coexist on the same posting, and confusion between them is a common source of "wrong currency" complaints that are actually just a different valid currency view.', type: 'troubleshooting' },
      { q: 'Client asks whether Operating Concern activation (CO-9) can happen before or must happen after Controlling Area setup.', a: 'Operating Concern must be assigned to and activated for an already-existing Controlling Area — this Day 1 org structure is a prerequisite dependency, not something that can be configured independently or beforehand.', type: 'conceptual' },
      { q: 'Client asks why their multi-Controlling-Area design makes group-wide cost reporting more difficult than expected.', a: 'This is the direct tradeoff of using multiple Controlling Areas — CO data doesn\'t natively consolidate across separate Controlling Areas the way it does within one, so group-wide views require additional reporting/consolidation work by design, not a configuration oversight.', type: 'conceptual' },
      { q: 'Auditor asks for the single clearest way to verify Controlling Area to Company Code assignment integrity before a system audit.', a: 'Pull the assignment table showing every Company Code\'s single Controlling Area assignment, cross-check that all assigned Company Codes share the same operating chart of accounts and fiscal year variant, and confirm no Company Code appears under more than one Controlling Area.', type: 'conceptual' },
      { q: 'Client\'s new acquisition needs to be added to an existing Controlling Area quickly for immediate group reporting, but its fiscal year variant is uncertain.', a: 'Confirm and lock the fiscal year variant decision before assignment — rushing the assignment without this confirmation risks having to unwind and redo the Controlling Area assignment later, a far more costly correction than a brief upfront delay.', type: 'scenario' },
      { q: 'Client wants to know if Version 0\'s currency settings can be changed after go-live without disrupting historical plan data.', a: 'Currency setting changes to Version 0 after go-live are a significant configuration change requiring careful assessment of historical plan data comparability — this isn\'t a simple toggle and should go through the same rigor as any other locked foundational decision change.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents CO postings from mixing actual and plan data ambiguously in the same report.', a: 'The separate number range groups for actual versus plan postings (established at document level) mean every CO document is clearly tagged as one or the other from creation, so reports filtering by data category rely on this structural document-level separation rather than a post-hoc classification.', type: 'conceptual' },
    ],
  },
  'co-day-2': {
    junior: [
      { q: 'Where are cost elements created in S/4HANA?', a: 'In the G/L account master, using account type Primary Costs/Revenue or Secondary Costs — reinforcing that G/L Account Type merged FI and CO master data into one object.', type: 'conceptual' },
      { q: 'What does OKB9 configure?', a: 'The default cost object (typically a cost center) that automatically receives a posting to a P&L account when no cost object was manually entered.', type: 'conceptual' },
      { q: 'What is the full derivation precedence for cost object assignment?', a: 'Document entry (if manually entered) → OKB9 default assignment → substitution rules → cost element default, in that priority order.', type: 'conceptual' },
      { q: 'What is the difference between cost element category 42 and 43?', a: '42 (assessment) redistributes an aggregated cost pool via a secondary cost element, hiding original detail. 43 (internal activity allocation) represents specific activity-type consumption.', type: 'conceptual' },
      { q: 'Are classic KA01/KA02/KA06 transactions still used in S/4HANA?', a: 'No — cost elements are maintained entirely through the G/L account master; these classic cost element transactions are retired.', type: 'conceptual' },
      { q: 'Can a revenue-category cost element post statistically to a cost center?', a: 'Yes — this is valid, informational tracking even though revenue formally belongs to Margin Analysis reporting.', type: 'conceptual' },
      { q: 'What is the benefit of cost elements being G/L accounts for authorization governance?', a: 'One master data object means one authorization concept governs both FI and CO account creation, removing the dual-maintenance risk that existed in ECC.', type: 'conceptual' },
      { q: 'What is a Cost Element Group used for?', a: 'Grouping related cost elements (e.g. all travel expense accounts) for reporting and mass-maintenance convenience, without altering posting derivation logic.', type: 'conceptual' },
      { q: 'What is cost element category 31 used for?', a: 'Order/project results analysis — a category associated with WIP and variance calculation objects (production orders, projects) rather than standard cost postings.', type: 'conceptual' },
      { q: 'What is cost element category 21/22 used for?', a: 'Internal settlement categories, representing amounts that settle from one CO object to another (e.g. an internal order settling to a cost center).', type: 'conceptual' },
      { q: 'What is cost element category 12?', a: 'Sales deductions — a revenue-adjacent category representing amounts that reduce recognized revenue, like rebates or discounts, distinct from category 11\'s straight revenue.', type: 'conceptual' },
      { q: 'Can a G/L account\'s cost element category be changed after go-live?', a: 'Technically possible in some cases, but high-risk — since CO derivation and reporting logic assume category consistency over time, changing it after postings exist can create historical-vs-current inconsistency, similar to the FI Day 3 account type change warning.', type: 'conceptual' },
      { q: 'What does "automatic account assignment" mean beyond OKB9 specifically?', a: 'Other module-specific mechanisms (e.g. from a sales order or production order context) that determine a cost object automatically, following their own derivation logic before any OKB9 fallback applies.', type: 'conceptual' },
      { q: 'Why does S/4 still require a cost object on every P&L posting, even automated ones?', a: 'Because every Primary Costs/Revenue or Secondary Costs account type posting must resolve to a valid CO object (true or statistical) for the posting to be considered CO-complete — this is what enables consistent cost center/profit center reporting across all P&L activity.', type: 'conceptual' },
      { q: 'What is the difference between a substitution rule and OKB9 in terms of precedence?', a: 'Per the full derivation chain, OKB9 applies before substitution in the standard sequence, but substitution rules can be configured to run at various points and, if positioned earlier, can override what OKB9 would otherwise assign.', type: 'conceptual' },
      { q: 'Can a single G/L account carry more than one cost element category over its lifetime?', a: 'Not simultaneously — an account has one active category at a time; changing it is the high-risk scenario discussed elsewhere, distinct from simply having one stable category throughout normal use.', type: 'conceptual' },
      { q: 'What does it mean that "cost elements are G/L accounts, not a parallel structure"?', a: 'There is no separate cost-element-only table or master record — the G/L account record itself, via its account type field, is the complete and only place cost element behavior is defined.', type: 'conceptual' },
      { q: 'Why might a consultant deliberately choose NOT to configure an OKB9 default for a specific P&L account?', a: 'If that account should always require an explicit, manually-considered cost object entry (e.g. a sensitive or infrequently-used account), omitting the default forces the poster to consciously assign the cost object rather than silently defaulting to a potentially wrong one.', type: 'conceptual' },
      { q: 'What is the relationship between Cost Element Groups and the CO Component Map from CO Day 1?', a: 'Cost Element Groups are a reporting convenience that can span across the different CO components (cost centers, orders, etc.) since cost elements themselves are used throughout multiple CO objects, not scoped to just one component.', type: 'conceptual' },
      { q: 'What happens if a substitution rule references a cost element category that no longer exists on the target account?', a: 'The substitution will fail or produce an invalid assignment at posting time, since the rule\'s logic depends on the target account\'s current category — this is a common consequence of the high-risk category-change scenario discussed above.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A posting fails with "no cost object assigned" despite OKB9 being configured for that account.', a: 'Check the full derivation chain — a substitution rule executed earlier in the sequence may be intercepting or conflicting with the OKB9 default before it can apply.', type: 'troubleshooting' },
      { q: 'Client wants to redistribute an aggregated IT overhead pool while a new consultant proposes using activity allocation (43).', a: 'Push back — category 43 represents specific activity-type consumption, not pool-level redistribution; category 42 (assessment) is the correct fit for this pool-redistribution scenario.', type: 'scenario' },
      { q: 'Client wants receiving departments to see the exact original cost elements behind an allocated charge.', a: 'Use Distribution rather than Assessment — Distribution preserves the original primary cost element on the receiver; Assessment consolidates into a secondary cost element instead.', type: 'scenario' },
      { q: 'Auditor asks why cost element creation no longer needs a separate authorization role from G/L account creation.', a: 'Cost elements are G/L accounts — one master data object under one authorization concept, eliminating the ECC-era dual-maintenance and dual-authorization risk.', type: 'conceptual' },
      { q: 'A revenue account unexpectedly shows up in a cost center report the client believed was cost-only.', a: 'Check whether that account\'s cost element category (11, revenue) is intentionally configured for statistical posting to cost centers — this is valid behavior, not necessarily an error.', type: 'troubleshooting' },
      { q: 'Client asks whether Cost Element Groups can be used to change how postings derive their cost object.', a: 'No — groups are a reporting/mass-maintenance convenience only; posting-time derivation is governed by OKB9, substitution rules, and cost element category, not by group membership.', type: 'conceptual' },
      { q: 'Client\'s rebate/discount postings are landing on a straight revenue account instead of a sales deduction account.', a: 'Check whether the G/L account used for those postings carries cost element category 12 (sales deduction) rather than 11 (revenue) — using the wrong category conflates two economically different line items that margin/profitability reporting needs kept separate.', type: 'troubleshooting' },
      { q: 'An internal order settlement to a cost center fails with a category-related error.', a: 'Verify the receiving cost element on the cost center side carries the correct settlement category (21/22) — settlement transactions validate that the target cost element category is compatible with an internal settlement, and a mismatch here is a common configuration gap.', type: 'troubleshooting' },
      { q: 'Client wants to change a heavily-used Primary Costs account to Secondary Costs to correct an original miscategorization made at implementation.', a: 'Treat this with the same caution as an FI Day 3 account type change — assess the historical CO reporting and derivation logic built around the original category, and strongly consider creating a new correctly-categorized account instead of changing the existing one\'s category retroactively.', type: 'scenario' },
      { q: 'A results-analysis-related posting for a production order fails, referencing an invalid cost element category.', a: 'Check that the relevant cost element carries category 31 (order/project results analysis) — WIP and variance postings specifically require this category, and using a standard primary/secondary cost category instead will cause the posting to fail validation.', type: 'troubleshooting' },
      { q: 'Client deliberately wants certain sensitive P&L accounts to require manual cost object entry on every posting, with no default.', a: 'This is a valid control design — omit the OKB9 default assignment for those specific accounts so posters must consciously select the correct cost object each time, trading convenience for deliberate, auditable cost assignment on sensitive accounts.', type: 'scenario' },
      { q: 'Auditor asks whether the absence of a separate cost element authorization object creates a governance gap compared to ECC.', a: 'No — since cost elements are G/L accounts, the single G/L account authorization concept governs creation/change for both, which is actually a governance improvement over ECC\'s dual objects that could be independently (and inconsistently) authorized.', type: 'conceptual' },
      { q: 'Client\'s substitution rule for cost object derivation stopped working after an unrelated G/L account category change.', a: 'Check whether the substitution rule references the affected account\'s cost element category as part of its logic — a category change on one account can silently break a substitution rule elsewhere that depended on the old category value.', type: 'troubleshooting' },
      { q: 'A consultant proposes using one shared Cost Element Group across cost centers, internal orders, and product costing reporting.', a: 'This is workable and often desirable — since cost elements themselves aren\'t scoped to a single CO component, a shared group provides consistent grouping for reporting across multiple components, provided the grouping logic genuinely makes sense across all the intended use cases.', type: 'scenario' },
      { q: 'Client asks whether it\'s possible to have a P&L posting with no cost object at all in a well-configured S/4 system.', a: 'No — every Primary Costs/Revenue or Secondary Costs account type posting must resolve to a valid CO object through the derivation chain; a well-configured system should never allow this to fall through completely, and any occurrence indicates a derivation configuration gap.', type: 'conceptual' },
      { q: 'A newly created G/L account was assigned category 41 (overhead) but the client intended it as a straightforward primary cost account.', a: 'Correct the cost element category on the account before significant postings accumulate — since this is a master data field with downstream CO implications, catching and fixing a miscategorization early avoids the far more expensive later remediation of a category change after heavy use.', type: 'troubleshooting' },
      { q: 'Client asks whether Cost Element Groups need to be rebuilt if new G/L accounts are added to the chart of accounts.', a: 'Existing groups remain valid; new accounts simply need to be explicitly added to the relevant group(s) if they should be included in that reporting view — group membership doesn\'t automatically expand to catch every new account created.', type: 'conceptual' },
      { q: 'Auditor asks how OKB9 default assignment interacts with a Company Code that has multiple cost centers eligible as defaults.', a: 'OKB9 is configured per Company Code/account combination and can only point to one specific default cost center — if multiple cost centers are plausible candidates, the configuration must make an explicit choice, since OKB9 doesn\'t support conditional multi-cost-center defaulting on its own.', type: 'conceptual' },
    ],
  },
  'co-day-3': {
    junior: [
      { q: 'How many Standard Hierarchies exist per Controlling Area?', a: 'Exactly one, mandatory — every cost center in that Controlling Area must belong to it.', type: 'conceptual' },
      { q: 'What is the difference between Reposting Line Items and Reposting Costs?', a: 'Reposting Line Items requires and preserves the original document reference. Reposting Costs does not — it posts a new, independent correction entry instead.', type: 'conceptual' },
      { q: 'Is a Profit Center assignment on a cost center true or statistical?', a: 'Always statistical — the true cost remains on the cost center itself, with the profit center receiving only an informational copy.', type: 'conceptual' },
      { q: 'What do lock indicators on a cost center master record control?', a: 'Which specific transaction types (actual postings, planning, etc.) are blocked for that cost center, without deactivating it entirely.', type: 'conceptual' },
      { q: 'What is the purpose of Cost Center Groups?', a: 'Providing flexible, purpose-specific reporting views (e.g. all EMEA cost centers) layered on top of the one mandatory standard hierarchy.', type: 'conceptual' },
      { q: 'What does Direct Activity Allocation charge based on?', a: 'Actual activity type consumption (e.g. machine hours) rather than a flat manual cost transfer.', type: 'conceptual' },
      { q: 'What fields make up cost center master data?', a: 'Category, hierarchy area, assigned Profit Center, lock indicators, and validity period.', type: 'conceptual' },
      { q: 'What are the two primary Fiori apps for cost center accounting?', a: 'Manage Cost Centers (master data maintenance) and Cost Centers – Plan/Actual (variance reporting).', type: 'conceptual' },
      { q: 'What is a Hierarchy Area on a cost center master record?', a: 'The specific position/node within the Standard Hierarchy that the cost center is attached to, determining its place in the mandatory structural rollup.', type: 'conceptual' },
      { q: 'What is the difference between a cost center\'s Category and its Hierarchy Area?', a: 'Category classifies the cost center\'s functional type (production, service, admin); Hierarchy Area determines its structural position within the Standard Hierarchy — two independent classification dimensions.', type: 'conceptual' },
      { q: 'What is Validity Period on a cost center master?', a: 'The date range during which the cost center is active and can receive postings — cost centers can have a defined start and end date, especially for temporary organizational units.', type: 'conceptual' },
      { q: 'Can a cost center be blocked from just planning but not actual postings?', a: 'Yes — lock indicators independently control actual postings, plan postings, and other transaction types, so any combination of locks/unlocks per transaction type is possible.', type: 'conceptual' },
      { q: 'What does an Alternative Hierarchy provide that Cost Center Groups don\'t?', a: 'A fuller, structured alternate tree (not just a flat grouping) for a different reporting perspective, while Cost Center Groups are typically simpler ad hoc groupings for specific reports.', type: 'conceptual' },
      { q: 'What is a Planning Layout?', a: 'An input template configuring which fields (cost element, cost center, period) appear and in what arrangement for manual cost center planning entry.', type: 'conceptual' },
      { q: 'What is the difference between primary cost element planning and secondary cost element planning?', a: 'Primary cost element planning forecasts costs that will originate from FI postings (e.g. salaries); secondary cost element planning forecasts internal allocations/activity consumption that never touch FI directly.', type: 'conceptual' },
      { q: 'Can a cost center exist without being assigned to a Profit Center?', a: 'Technically the field can be blank in some configurations, but in most well-designed S/4 systems every cost center should carry a Profit Center assignment to avoid dummy profit center postings (CO Day 6 concept).', type: 'conceptual' },
      { q: 'What is the purpose of comparing plan and actual by cost element rather than just a cost center total?', a: 'It surfaces exactly which cost categories are driving a variance (e.g. travel vs. supplies) rather than just showing an overall over/under, making the variance actionable for the cost center owner.', type: 'conceptual' },
      { q: 'What does it mean for a cost center to have "time-dependent" master data fields?', a: 'Certain fields (like Profit Center assignment) can change over the cost center\'s life with effective dates recorded, preserving historical assignment accuracy rather than overwriting it.', type: 'conceptual' },
      { q: 'What happens to historical postings if a cost center\'s Profit Center assignment changes mid-year?', a: 'Historical postings retain the Profit Center that was assigned at the time they were posted; only new postings after the change reflect the new assignment, preserving historical reporting accuracy.', type: 'conceptual' },
      { q: 'What is the difference between a service cost center and a production cost center?', a: 'Service cost centers (e.g. IT, HR) typically support other cost centers and are common allocation senders; production cost centers directly incur manufacturing-related costs and commonly serve as activity type providers.', type: 'conceptual' },
      { q: 'Can Cost Center Groups be nested?', a: 'Yes — groups can contain sub-groups, allowing a flexible multi-level ad hoc reporting structure distinct from, and layered on top of, the single mandatory Standard Hierarchy.', type: 'conceptual' },
      { q: 'What is the role of a Cost Center in the CO Component Map from CO Day 1?', a: 'It is the most foundational, most heavily-used CO object — nearly every other CO component (internal orders, activity types, allocations) references or interacts with cost centers in some way.', type: 'conceptual' },
      { q: 'Why might reposting be used instead of simply reversing and reposting a document?', a: 'Reposting is a lighter-weight correction specifically for moving cost to a different cost object without unwinding the entire original document\'s other line items, whereas a full reversal undoes the complete document.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A miscoded cost center needs correcting with full traceability to the original document.', a: 'Use Reposting Line Items — it requires and preserves the original document reference, giving the auditability the client needs, unlike Reposting Costs.', type: 'scenario' },
      { q: 'A profit center report and cost center report both show the same cost — is this double-counting?', a: 'No — the profit center holds a statistical copy while the cost center holds the true cost; the same economic event legitimately appears in both from different reporting angles.', type: 'conceptual' },
      { q: 'Client wants ad hoc regional cost center reporting without restructuring the standard hierarchy.', a: 'Create a Cost Center Group for the regional view — it layers on top of the standard hierarchy without altering the mandatory structural tree.', type: 'scenario' },
      { q: 'Planning data was entered in Version 1 by mistake and doesn\'t show up in standard variance reports.', a: 'Standard reporting compares against Version 0 by default — the data needs to be corrected into Version 0, or the report explicitly pointed at Version 1.', type: 'troubleshooting' },
      { q: 'Client asks whether a cost center can be locked for actual postings but remain open for planning.', a: 'Yes — lock indicators are granular by transaction type, so actual postings and planning can be locked and unlocked independently of each other.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents a cost center from carrying two profit center assignments at once.', a: 'The cost center master record structurally carries exactly one Profit Center field at a time — enforcement is built into the master data model itself, not a separate validation layer.', type: 'conceptual' },
      { q: 'A cost center\'s Profit Center assignment changed mid-year, and now a report shows inconsistent Profit Center totals for that cost center across the year.', a: 'This is expected — because the assignment is time-dependent, postings before the change carry the old Profit Center and postings after carry the new one; a report split by Profit Center correctly reflects this history rather than retroactively applying the new assignment.', type: 'conceptual' },
      { q: 'Client wants to reorganize which cost centers report under which manager without changing the underlying Standard Hierarchy.', a: 'Use Cost Center Groups (potentially nested) to build the management reporting view — this achieves the desired managerial rollup without touching the mandatory structural Standard Hierarchy that other CO processes depend on.', type: 'scenario' },
      { q: 'A cost center\'s plan/actual variance report shows an overall small variance, but the client suspects hidden offsetting issues.', a: 'Drill into the cost-element-level detail rather than relying on the total — offsetting overspend in one cost element and underspend in another can net to a small total variance while masking two real, separate issues worth investigating individually.', type: 'troubleshooting' },
      { q: 'Client asks whether locking a cost center for actual postings mid-year will affect historical postings already made.', a: 'No — lock indicators only affect future posting attempts from the point they\'re activated; historical postings already in the system are unaffected by a subsequently applied lock.', type: 'conceptual' },
      { q: 'Auditor asks how planning layouts support governance over what cost center planners can enter.', a: 'Planning layouts constrain which fields and combinations are available for manual entry, which reduces the risk of planners entering data against unintended cost elements or periods compared to a fully open entry screen.', type: 'conceptual' },
      { q: 'Client\'s new production cost center shows zero activity type consumption despite clear machine usage.', a: 'Check whether the cost center actually has activity types assigned and whether confirmations/allocations are correctly posting against it — a cost center without properly configured activity types cannot show activity-based consumption, regardless of physical machine usage.', type: 'troubleshooting' },
      { q: 'Client wants primary cost element planning for salaries but is unsure whether secondary cost element planning is also needed.', a: 'Secondary cost element planning is needed if that cost center also plans to receive or send internal allocations (e.g. planned IT service consumption) — the two serve different purposes and a complete plan for a cost center with both internal and external cost flows typically needs both.', type: 'scenario' },
      { q: 'A service cost center\'s costs never seem to get allocated out to the departments it serves.', a: 'Check whether a distribution or assessment cycle (CO Day 4) targeting that service cost center as a sender is actually configured and scheduled to run — a service cost center accumulating costs with no allocation cycle pointing to it as a sender will simply retain those costs indefinitely.', type: 'troubleshooting' },
      { q: 'Client\'s cost center hierarchy shows a cost center appearing to report to the wrong node after a reorganization.', a: 'Check the cost center\'s Hierarchy Area field — this determines the Standard Hierarchy position independently of the cost center\'s Category, so a reorganization must explicitly update Hierarchy Area, not just rename the cost center or change its category.', type: 'troubleshooting' },
      { q: 'Auditor asks how reposting differs from reversal in terms of impact on the rest of a multi-line document.', a: 'Reposting corrects only the specific cost object assignment on a targeted line without touching other lines in the original document; a full reversal undoes the entire document, which is unnecessarily disruptive if only one line item\'s cost object was wrong.', type: 'conceptual' },
      { q: 'Client wants a temporary project-based cost center that automatically becomes inactive after the project ends.', a: 'Set a Validity Period end date on the cost center master matching the project\'s expected completion — this cleanly deactivates the cost center for postings after that date without requiring manual intervention, though the underlying data remains for historical reporting.', type: 'scenario' },
      { q: 'A newly onboarded cost center posts correctly to actuals but doesn\'t appear in the standard plan/actual variance report.', a: 'Check whether any planning data (Version 0) was actually entered for that cost center — a cost center with actuals but zero plan data will show 100% unfavorable "variance" or may not populate cleanly in a report expecting both sides of the comparison, depending on report configuration.', type: 'troubleshooting' },
      { q: 'Client asks whether nested Cost Center Groups can create circular reporting references.', a: 'Properly configured nested groups shouldn\'t be circular since they\'re meant to represent a strict hierarchy of groupings; if a circular reference is discovered, it indicates a configuration error in the group structure that needs correcting, not an inherent system limitation.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that a cost center\'s historical Profit Center assignment changes are properly documented.', a: 'Pull the time-dependent master data change history for that cost center, showing each Profit Center assignment with its effective date range — this is the audit trail demonstrating when and to what the assignment changed over time.', type: 'conceptual' },
      { q: 'Client wants to know whether Cost Center Category affects which G/L accounts can post to that cost center.', a: 'No — Category is a classification/reporting attribute of the cost center itself; which G/L accounts (cost elements) can post to it is governed by the cost element\'s own configuration and the posting\'s derivation chain, not by the receiving cost center\'s category.', type: 'conceptual' },
    ],
  },
  'co-day-4': {
    junior: [
      { q: 'What cost element category is structurally paired with Activity Types?', a: 'Category 43 — internal activity allocation.', type: 'conceptual' },
      { q: 'What is the core distinction between Distribution and Assessment?', a: 'Distribution keeps the original primary cost element visible on the receiver; Assessment uses a secondary cost element (category 42) that consolidates the detail.', type: 'conceptual' },
      { q: 'What is a Statistical Key Figure typically used for?', a: 'Serving as an allocation base (tracing factor) in distribution/assessment cycles — e.g. headcount or square footage driving proportional cost splits.', type: 'conceptual' },
      { q: 'What is the difference between a Fixed and Total SKF value?', a: 'Fixed is a point-in-time snapshot (e.g. headcount at month-end); Total accumulates over the period (e.g. total machine hours run).', type: 'conceptual' },
      { q: 'What is Universal Allocation?', a: 'The S/4-native, Fiori-managed allocation tool running on ACDOCA, covering cost centers, profit centers, and margin analysis in one framework — the strategic direction going forward.', type: 'conceptual' },
      { q: 'Do classic KSV5/KSU5 transactions still function in S/4HANA?', a: 'Yes, technically, but Universal Allocation is the current recommended, strategic path.', type: 'conceptual' },
      { q: 'What does activity price revaluation address?', a: 'Adjusting postings that used the plan (political) price during the period once the actual price is calculated at period-end.', type: 'conceptual' },
      { q: 'What handles cyclic sender/receiver relationships in an allocation cycle?', a: 'Iterative processing within the cycle-segment structure, designed specifically to resolve these cyclic dependencies correctly.', type: 'conceptual' },
      { q: 'What is a Price Indicator on an activity type?', a: 'A setting determining whether the activity price is manually entered, calculated via plan cost/activity, or calculated via actual cost/activity — controlling the source of the price used for allocation.', type: 'conceptual' },
      { q: 'What does Cost Center Splitting produce as its output?', a: 'A breakdown of a multi-activity-type cost center\'s total costs proportionally allocated across its activity types, which is a prerequisite input for accurate activity price calculation.', type: 'conceptual' },
      { q: 'What is Periodic Reposting, distinct from Distribution and Assessment?', a: 'A scheduled version of the manual cost reposting concept from CO Day 3 — moving costs to a different cost object on a recurring schedule rather than as a one-off manual correction.', type: 'conceptual' },
      { q: 'What is a Sender/Receiver Rule within a cycle segment?', a: 'The configuration defining which cost object(s) send cost and which receive it within a specific allocation segment, along with the method (fixed amount, percentage, or tracing factor) used to calculate the split.', type: 'conceptual' },
      { q: 'What is a Tracing Factor?', a: 'The basis (often an SKF, but can be another value like fixed percentages) used to proportionally distribute a sender\'s cost across multiple receivers within an allocation segment.', type: 'conceptual' },
      { q: 'Can Universal Allocation run alongside classic KSV5/KSU5 cycles during a transition period?', a: 'Yes, technically both can coexist, but running both creates duplicate allocation logic and reconciliation risk — a transition should have a clear cutover plan rather than running both indefinitely in parallel.', type: 'conceptual' },
      { q: 'What is the difference between a Sender Cost Element and a Receiver Cost Element in an allocation cycle?', a: 'The Sender Cost Element identifies which original costs on the sending object are eligible for allocation; the Receiver Cost Element (typically a secondary cost element, category 42) is what actually posts on the receiving object.', type: 'conceptual' },
      { q: 'What does "political price" specifically mean for an activity type?', a: 'A negotiated or target price set deliberately (not purely cost-derived) for planning purposes, often used when a business wants predictable internal charge rates regardless of underlying cost fluctuation.', type: 'conceptual' },
      { q: 'Can an activity type have a different price for different receiving cost objects?', a: 'No — an activity type carries one price (per period, per price indicator setting) applied uniformly to whatever object consumes it; differentiated pricing by receiver isn\'t part of the standard activity price mechanism.', type: 'conceptual' },
      { q: 'What is the purpose of running activity price calculation before period-end closes complete?', a: 'To establish the plan/political price that gets used for allocation throughout the period, so postings have a price to apply in real time rather than waiting until period-end for a rate to exist.', type: 'conceptual' },
      { q: 'What does "top-down distribution" mean at an awareness level for this tab?', a: 'Distributing a higher-level total cost proportionally down to lower-level receivers when a direct, granular allocation basis isn\'t available or practical — a related but distinct concept from standard distribution/assessment cycles.', type: 'conceptual' },
      { q: 'What happens to unallocated cost center balances if no distribution or assessment cycle ever runs against them?', a: 'The costs simply remain on the originating cost center indefinitely, appearing in that cost center\'s own reporting rather than being spread to consuming departments — this is often an unintended gap rather than a deliberate design choice.', type: 'conceptual' },
      { q: 'What is the relationship between activity type master data and the Work Center concept (previewed for INT-4)?', a: 'A Work Center is assigned to a Cost Center and carries default Activity Types, linking PP execution capacity/time directly to the CO activity price mechanism covered in this tab.', type: 'conceptual' },
      { q: 'Can Statistical Key Figures be used for purposes other than allocation tracing factors?', a: 'Yes — SKFs can also serve purely informational reporting purposes (e.g. tracking headcount or square footage for KPI reporting) independent of whether they\'re used in any allocation cycle.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client needs receiving departments to see exactly which cost elements make up an allocated charge.', a: 'Use Distribution — it preserves the original primary cost element on the receiver, unlike Assessment which consolidates into a secondary cost element.', type: 'scenario' },
      { q: 'Client wants a summarized, single-line allocation without exposing granular cost element detail.', a: 'Use Assessment — the secondary cost element (category 42) intentionally consolidates the detail, hiding the breakdown.', type: 'scenario' },
      { q: 'Two cost centers have a cyclic allocation relationship (A sends to B, B sends back to A).', a: 'Iterative processing in the cycle-segment structure is designed specifically to resolve this kind of cyclic sender/receiver relationship correctly.', type: 'troubleshooting' },
      { q: 'Client asks whether to migrate from KSV5/KSU5 to Universal Allocation as part of an S/4 upgrade.', a: 'Yes — Universal Allocation is the strategic direction, runs natively on ACDOCA, and unifies allocation logic across cost centers, profit centers, and margin analysis.', type: 'scenario' },
      { q: 'An allocation cycle produces inconsistent month-to-month results using the same tracing factor SKF.', a: 'Check whether the SKF is Fixed (needs periodic re-entry/verification) versus Total (naturally accumulates) — a mismatch in expected behavior between the two types is a common root cause.', type: 'troubleshooting' },
      { q: 'An activity price used during the period differs significantly from the actual price calculated at period-end.', a: 'This is expected — actual price calculation and revaluation adjust postings that used the plan price, aligning them to the true actual price; it is not a configuration error.', type: 'conceptual' },
      { q: 'Client\'s cost center provides three different activity types but reports show one blended, inaccurate price.', a: 'Check whether Cost Center Splitting has been correctly configured to allocate the cost center\'s total cost across its three activity types proportionally — without splitting, the system may calculate an inaccurate single blended price instead of three distinct, activity-specific prices.', type: 'troubleshooting' },
      { q: 'Client wants predictable internal charge rates for IT services regardless of actual IT department cost fluctuations during the year.', a: 'Use a political (plan) price on the relevant activity type, set deliberately rather than purely cost-derived — this gives internal consumers a stable, predictable rate while actual cost variance gets captured and revalued separately at period-end.', type: 'scenario' },
      { q: 'Two allocation cycles both target the same receiving cost center for the same period, and the client is unsure of the combined effect.', a: 'Both cycles will post independently and their effects sum on the receiver — verify this is intentional (e.g. one cycle for facilities cost, another for IT cost) rather than an accidental duplicate cycle inadvertently double-allocating the same underlying cost pool.', type: 'troubleshooting' },
      { q: 'Client is running both classic KSU5 assessment cycles and Universal Allocation for overlapping cost pools.', a: 'Flag this as a reconciliation risk — running both for the same cost pool creates duplicate or conflicting allocation results; recommend a clear cutover plan retiring the classic cycles for that specific pool rather than running both indefinitely.', type: 'scenario' },
      { q: 'Auditor asks how the system ensures an activity type\'s price is applied consistently regardless of which cost object consumes it.', a: 'Activity price is a property of the activity type itself for a given period, not something configurable per receiver — this structural design guarantees uniform pricing across all consumers of that activity type in that period.', type: 'conceptual' },
      { q: 'Client\'s service cost center has been accumulating unallocated costs for six months with no distribution or assessment cycle configured against it.', a: 'This is a configuration gap, not expected behavior — recommend setting up an appropriate distribution or assessment cycle promptly, since the accumulated unallocated cost is understating the true cost of the departments that actually consumed those services during that period.', type: 'troubleshooting' },
      { q: 'Client asks whether top-down distribution can be used as a substitute for building a proper allocation cycle with a real tracing factor.', a: 'Top-down distribution should be reserved for genuine cases where a direct, granular allocation basis isn\'t available or practical — using it as a shortcut to avoid building a proper tracing-factor-based cycle when good allocation data does exist produces less accurate, less defensible cost allocation.', type: 'scenario' },
      { q: 'A newly built activity type shows no price at all when used in a production order confirmation.', a: 'Check whether activity price calculation has actually been run for that activity type and period — a newly created activity type with no price calculation run yet will have no valid price to apply, causing either an error or a zero-cost allocation depending on system configuration.', type: 'troubleshooting' },
      { q: 'Client wants to understand why their SKF-based allocation gave dramatically different results this month versus last.', a: 'Check whether the SKF is a Fixed-type value that should have been re-entered/updated for the current month but wasn\'t — a stale Fixed SKF value carried forward incorrectly, rather than a genuine change in the underlying tracing factor, is a common cause of this kind of swing.', type: 'troubleshooting' },
      { q: 'Auditor asks how iterative processing in a cycle-segment structure avoids an infinite loop with genuinely circular sender/receiver relationships.', a: 'Iterative processing runs a bounded number of passes, converging toward a stable allocation result across the cyclic relationships rather than looping indefinitely — the iteration count and convergence tolerance are configurable to ensure the process terminates with a defensible result.', type: 'conceptual' },
      { q: 'Client wants a single cost center\'s facilities cost split between two departments using square footage as the basis.', a: 'Configure a distribution or assessment cycle with square footage as the tracing factor — likely maintained as a Total-type SKF per department, giving a defensible, reproducible proportional split rather than an arbitrary manual allocation.', type: 'scenario' },
      { q: 'Client\'s CFO asks whether moving fully to Universal Allocation would change the underlying accounting logic of their allocations.', a: 'No — Universal Allocation is a modernized execution/management layer (Fiori-managed, ACDOCA-native) for the same underlying distribution/assessment concepts; the accounting logic (primary vs. secondary cost element behavior, sender/receiver rules) remains conceptually the same, just delivered through a unified tool.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that activity price revaluation correctly adjusted all affected postings at period-end.', a: 'Pull the revaluation run log showing which production orders/cost objects had their activity allocation postings adjusted from plan to actual price, and confirm the total revaluation adjustment reconciles to the difference between total plan-price-charged and total actual cost incurred for that activity type.', type: 'conceptual' },
      { q: 'Client\'s allocation cycle results look correct in a test run but differ when executed in production for the same period.', a: 'Check whether the underlying data (SKF values, cost center balances) differed between the test and production environments at the time each was run — allocation cycles calculate against live data at execution time, so any difference in underlying balances between the two runs will produce different results even with identical cycle configuration.', type: 'troubleshooting' },
    ],
  },
  'co-day-5': {
    junior: [
      { q: 'Can a statistical internal order be settled?', a: 'No — only real internal orders can be settled; statistical orders only carry an informational copy of a cost posted elsewhere.', type: 'conceptual' },
      { q: 'What does a Budget Profile\'s Activation Type control?', a: 'Whether warnings or hard blocks trigger at defined budget consumption thresholds.', type: 'conceptual' },
      { q: 'What is the difference between Allocation Structure and Settlement Profile?', a: 'Allocation Structure defines which cost elements settle and to which settlement cost elements. Settlement Profile defines valid receivers and settlement types (full vs periodic).', type: 'conceptual' },
      { q: 'What does Commitment Management track?', a: 'Open purchase requisitions/orders against an internal order\'s budget before actual costs post, giving visibility into committed (not just posted) spend.', type: 'conceptual' },
      { q: 'What is the typical settlement path for an Investment Order?', a: 'Investment Order → Asset under Construction (AuC) → Fixed Asset — the same lifecycle introduced from the asset accounting side in FI Day 9.', type: 'conceptual' },
      { q: 'What is the difference between Full and Periodic settlement?', a: 'Full clears the entire order balance once at project completion; Periodic runs at each period-end throughout the order\'s life.', type: 'conceptual' },
      { q: 'What determines whether an internal order is real or statistical?', a: 'The order category, set at order type configuration — real orders can be settled and carry true costs; statistical orders cannot.', type: 'conceptual' },
      { q: 'What does the Costing Sheet apply to an internal order\'s costs?', a: 'Configured overhead rates (e.g. a percentage of direct material or labor cost), the same mechanism used elsewhere in CO for indirect cost allocation.', type: 'conceptual' },
      { q: 'What is a Model Order?', a: 'A template internal order used to pre-fill common master data fields (order type, cost elements, settlement rule structure) when creating new similar orders, speeding up order creation.', type: 'conceptual' },
      { q: 'What is the difference between Overall Planning and Annual Planning for an internal order?', a: 'Overall Planning sets one total budget figure for the order\'s entire life; Annual Planning breaks the budget down year by year for multi-year projects.', type: 'conceptual' },
      { q: 'What are Exempt Cost Elements in availability control?', a: 'Specific cost elements deliberately excluded from budget tolerance checking, often used for costs that shouldn\'t trigger a budget block regardless of amount (e.g. certain statistical postings).', type: 'conceptual' },
      { q: 'What is a Budget Manager role?', a: 'The person or role assigned ownership of a specific order\'s budget, typically responsible for approving budget changes or overrides when tolerance limits are approached.', type: 'conceptual' },
      { q: 'What are Activation Types 1, 2, and 3 specifically?', a: 'Type 1 issues a warning only; Type 2 issues a warning but allows posting; Type 3 issues a hard error and blocks the posting — increasing levels of enforcement strictness.', type: 'conceptual' },
      { q: 'What is a Source Structure in the settlement context?', a: 'Groups cost elements together at the point of settlement for routing to Margin Analysis, working alongside the Allocation Structure but focused on the profitability-analysis-facing side.', type: 'conceptual' },
      { q: 'What is a PA Transfer Structure?', a: 'Defines how settled costs map into Margin Analysis value fields or account structures, specifically for scenarios where an internal order settles with profitability detail attached.', type: 'conceptual' },
      { q: 'What is Order Status Management, distinguishing system status from user status?', a: 'System status (REL, TECO, CLSD) is system-controlled and reflects the order\'s lifecycle stage; user status is client-defined and can add additional custom workflow states on top of the system status.', type: 'conceptual' },
      { q: 'Can an internal order\'s order type be changed after creation?', a: 'Generally not freely — order type governs foundational settings like number range and settlement profile, so changing it after the order is in use risks inconsistency; a new order is usually the safer path.', type: 'conceptual' },
      { q: 'What is the purpose of Number Ranges specifically for internal orders?', a: 'Assigning sequential (or externally-defined) numbers to new orders per order type, mirroring the same number range concept used for G/L accounts and documents elsewhere in FICO.', type: 'conceptual' },
      { q: 'What does "annual planning" specifically support that overall planning cannot?', a: 'Year-over-year budget tracking and comparison for a multi-year project, letting stakeholders see whether each individual year is on pace rather than only a lifetime total.', type: 'conceptual' },
      { q: 'What happens to Commitment Management data once a purchase order fully converts to a goods receipt/invoice?', a: 'The committed amount is released from the commitment pool and replaced by the actual posted cost, since the spend is no longer just "planned to happen" but has actually occurred.', type: 'conceptual' },
      { q: 'Can an internal order have more than one Settlement Rule over its lifetime?', a: 'Yes — a settlement rule can be revised as project circumstances change (e.g. a receiver split changes), though changes to an active order\'s settlement rule should be made deliberately given the impact on prior period settlements already processed.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A client attempts to settle a statistical internal order and receives an error.', a: 'This is expected — statistical orders cannot be settled by design; the true cost must be settled from wherever it actually posted, typically a cost center.', type: 'troubleshooting' },
      { q: 'An internal order exceeds its budget tolerance but postings continue without any warning.', a: 'Check the Budget Profile\'s Activation Type — it may be configured to log rather than block, or availability control may not be active for the cost elements involved.', type: 'troubleshooting' },
      { q: 'Client wants an internal order\'s settlement split 60/40 between two cost centers.', a: 'Configure the Settlement Rule with Distribution Rules specifying the 60/40 split across the two cost center receivers.', type: 'scenario' },
      { q: 'A capital project needs both Fixed Asset capitalization and ongoing cost center oversight reporting.', a: 'Settle the capitalizable cost to AuC/Fixed Asset via the settlement rule, while the order itself supports cost center-level oversight reporting throughout the project\'s life.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents an internal order from posting cost overruns without any record.', a: 'Availability control with a strict Activation Type logs or blocks overruns, and Commitment Management provides pre-posting visibility into committed spend approaching the limit.', type: 'conceptual' },
      { q: 'Client asks whether Periodic Settlement can switch to Full Settlement mid-project without issue.', a: 'This requires careful review of what has already settled periodically versus what remains — switching mid-project can create timing and receiver-allocation inconsistencies if not sequenced carefully.', type: 'scenario' },
      { q: 'Client wants postings to a specific statistical cost element to never trigger a budget block, regardless of how much accumulates.', a: 'Configure that cost element as an Exempt Cost Element within availability control — this excludes it from tolerance checking entirely, which is appropriate for costs that are informational/statistical rather than true budget consumption.', type: 'scenario' },
      { q: 'Client wants Activation Type behavior that warns users but still lets them post, reserving hard blocks only for a stricter secondary threshold.', a: 'Configure Activation Type 2 (warning, allows posting) for the initial tolerance level, and Activation Type 3 (hard block) for a stricter secondary tolerance threshold — this graduated approach is a common design pattern for balancing flexibility with control.', type: 'scenario' },
      { q: 'An internal order\'s settlement to Margin Analysis is missing expected profitability characteristic detail.', a: 'Check the PA Transfer Structure configuration — a gap here means settled amounts land in Margin Analysis without the intended characteristic-level detail (customer, product, etc.), reducing the granularity of profitability reporting for that settled cost.', type: 'troubleshooting' },
      { q: 'Client wants a Model Order for recurring marketing campaign internal orders to speed up creation each quarter.', a: 'Build a Model Order pre-configured with the standard order type, expected cost elements, and settlement rule structure for marketing campaigns — new campaign orders can then be created by referencing the model, avoiding repeated manual setup each quarter.', type: 'scenario' },
      { q: 'Auditor asks how the Budget Manager role supports segregation of duties for internal order budget changes.', a: 'The Budget Manager role concentrates budget approval authority with a specific accountable person or role, separate from whoever is entering day-to-day cost postings against the order, which is the segregation-of-duties structure an auditor looks for.', type: 'conceptual' },
      { q: 'Client\'s multi-year capital project shows an overall budget total but the finance team can\'t tell if year 2 specifically is on pace.', a: 'Use Annual Planning instead of (or alongside) Overall Planning — annual planning breaks the total into year-by-year figures, giving the specific year-over-year visibility the finance team needs that a single lifetime total cannot provide.', type: 'scenario' },
      { q: 'A purchase requisition tied to an internal order shows as committed spend, but after the PO converts to a goods receipt, the commitment figure doesn\'t update.', a: 'This would be unexpected behavior — normally the committed amount releases and is replaced by actual posted cost once the PO converts to GR/invoice; investigate whether Commitment Management is correctly configured and whether the conversion step actually completed as expected.', type: 'troubleshooting' },
      { q: 'Client wants to change an internal order\'s order type after several months of postings because the wrong type was originally selected.', a: 'Recommend creating a new, correctly-typed order and transferring/settling the existing balance appropriately, rather than changing the order type in place — order type governs foundational settings (number range, settlement profile) that risk inconsistency if altered mid-life.', type: 'scenario' },
      { q: 'Auditor asks how system status and user status work together to control what actions are permitted on an order.', a: 'System status (REL, TECO, CLSD) sets the baseline lifecycle-driven permissions; user status can add further client-specific restrictions or workflow gates layered on top, so the combination of both determines the full set of permitted actions at any point.', type: 'conceptual' },
      { q: 'Client\'s settlement rule needs to change mid-project because a receiver cost center was reorganized into a different one.', a: 'Update the Settlement Rule to reflect the new receiver going forward, but review whether prior period settlements already processed under the old rule need any correction — changing the rule doesn\'t retroactively re-settle historical periods automatically.', type: 'scenario' },
      { q: 'Auditor asks for evidence that a Source Structure correctly groups cost elements for Margin Analysis settlement.', a: 'Pull the Source Structure configuration showing cost element groupings and cross-check a sample settlement document to confirm the settled amounts landed in Margin Analysis grouped exactly as the Source Structure defines, not scattered inconsistently.', type: 'conceptual' },
      { q: 'Client asks whether a Model Order automatically updates existing orders if the model itself is later changed.', a: 'No — a Model Order is a copy-from template used at creation time only; changing the model afterward has no retroactive effect on orders already created from it, only on new orders created going forward.', type: 'conceptual' },
      { q: 'Client\'s internal order shows costs settling correctly to a cost center but the client also wants visibility in Margin Analysis for the same spend.', a: 'Review whether the Settlement Rule can support a split settlement to both a cost center and Margin Analysis via Distribution Rules, or whether the business need is better served by a dedicated PA Transfer Structure — the right approach depends on whether both destinations genuinely need the full amount or a split.', type: 'scenario' },
    ],
  },
  'co-day-6': {
    junior: [
      { q: 'Is Profit Center Accounting a separate ledger in S/4HANA?', a: 'No — Profit Center is a field on the same ACDOCA line item, reported directly from the Universal Journal rather than a dedicated PCA table.', type: 'conceptual' },
      { q: 'What does the Dummy Profit Center indicate?', a: 'A derivation gap — the profit center could not be determined and needs investigation, not a permanent parking spot for those postings.', type: 'conceptual' },
      { q: 'From which object is Segment typically derived?', a: 'Profit Center — reinforcing the FI Day 1 concept that Segment derives from Profit Center by default.', type: 'conceptual' },
      { q: 'What tool identifies objects missing a profit center assignment?', a: 'Assignment Monitor, built specifically to surface derivation gaps before they cause dummy-center postings.', type: 'conceptual' },
      { q: 'Does profit-center-level balance sheet reporting require document splitting?', a: 'Yes — Profit Center must be a splitting characteristic with zero-balance clearing active, or balance sheet items won\'t genuinely balance at profit center level.', type: 'conceptual' },
      { q: 'What are the three related concepts frequently confused: Profit Center, Segment, and Business Area?', a: 'Profit Center is master data with its own hierarchy/derivation; Segment is typically derived from Profit Center for external reporting; Business Area is the legacy concept Segment replaces.', type: 'conceptual' },
      { q: 'What replaced GLPCA/GLPCT in S/4HANA?', a: 'Direct reporting from ACDOCA — the old ECC-era dedicated PCA tables no longer exist.', type: 'conceptual' },
      { q: 'What is Transfer Pricing / Multiple Valuation used for, at an awareness level?', a: 'Valuing goods movements between profit centers at different price bases (legal, group, profit center) for internal margin visibility.', type: 'conceptual' },
      { q: 'What is the Standard Hierarchy for Profit Centers, parallel to the CO Day 3 cost center concept?', a: 'The single mandatory structural tree every profit center in a Controlling Area belongs to, providing the master rollup for profit center reporting.', type: 'conceptual' },
      { q: 'Can a Profit Center be assigned to more than one cost center?', a: 'Yes — many cost centers commonly share one profit center assignment (e.g. all cost centers in a division rolling up to that division\'s profit center), while a cost center itself carries exactly one profit center at a time.', type: 'conceptual' },
      { q: 'What is a Profit Center Group used for, mirroring the CO Day 3 cost center group concept?', a: 'Flexible, purpose-specific profit center reporting views (e.g. regional groupings) layered on top of the mandatory standard hierarchy.', type: 'conceptual' },
      { q: 'What does "derivation from Sales Order" mean for Profit Center?', a: 'A sales order line item can carry (or derive) a Profit Center based on the material or other order characteristics, feeding profitability visibility from the SD side.', type: 'conceptual' },
      { q: 'What does "derivation from WBS" mean for Profit Center?', a: 'A WBS element (project) can carry its own Profit Center assignment, so project-related postings inherit that profit center rather than falling back to a cost center-derived default.', type: 'conceptual' },
      { q: 'What is the relationship between Profit Center and the Segment concept from FI Day 1, restated precisely?', a: 'Segment is typically configured to derive automatically from the posting\'s Profit Center, meaning Profit Center master data effectively drives Segment population without separate manual Segment entry in most designs.', type: 'conceptual' },
      { q: 'Why would a company activate document splitting on Profit Center specifically, rather than relying on derivation alone?', a: 'Derivation only populates the field; splitting with zero-balance clearing (FI Day 5) ensures each document balances to zero per profit center, which is required for a genuinely usable profit-center-level balance sheet.', type: 'conceptual' },
      { q: 'Can Profit Center reporting include planning data, not just actuals?', a: 'Yes — profit center planning can be entered similarly to cost center planning (CO Day 3), supporting plan/actual variance reporting at the profit center level.', type: 'conceptual' },
      { q: 'What replaced the classic profit center planning transactions from ECC in S/4HANA?', a: 'Planning now works through the same ACDOCA-based planning framework used broadly across CO, rather than a dedicated separate PCA planning transaction tied to the now-retired GLPCA/GLPCT tables.', type: 'conceptual' },
      { q: 'What is the practical benefit of Profit Center-level balance sheets for a diversified business?', a: 'It lets management assess each business unit\'s or division\'s financial position (not just its P&L performance) independently, closer to evaluating them as quasi-standalone businesses within one legal entity.', type: 'conceptual' },
      { q: 'Does every posting need an explicit substitution rule to derive Profit Center, or can it rely purely on default derivation from cost center/material?', a: 'Most postings rely on the standard derivation chain (from cost center, material master, order, etc.) without needing a custom substitution rule — substitution is typically reserved for exceptions the standard chain doesn\'t handle.', type: 'conceptual' },
    ],
    senior: [
      { q: 'The dummy profit center is accumulating a growing number of postings each month.', a: 'Investigate via Assignment Monitor to find which master data objects lack a profit center assignment, then fix the derivation gap at the source rather than repeatedly clearing the dummy center.', type: 'troubleshooting' },
      { q: 'Client\'s profit-center-level balance sheet doesn\'t reconcile even though profit center is populated on every line.', a: 'Check whether Profit Center is actually configured as a splitting characteristic with zero-balance clearing — population alone does not guarantee per-document balancing.', type: 'troubleshooting' },
      { q: 'Client confuses Profit Center, Segment, and Business Area.', a: 'Explain the three-way distinction clearly: Profit Center is master data, Segment typically derives from it for external reporting, and Business Area is the legacy concept Segment replaces in S/4.', type: 'conceptual' },
      { q: 'A material transfer between two profit centers needs to reflect internal margin for management reporting.', a: 'This is a transfer pricing / multiple valuation scenario — different valuation views can value the same movement differently for internal margin visibility.', type: 'scenario' },
      { q: 'Client wants regional profit center reporting without restructuring the standard hierarchy.', a: 'Create a Profit Center Group for the regional view, layered on top of the mandatory standard hierarchy without altering its structure.', type: 'scenario' },
      { q: 'A newly created material type consistently posts to the dummy profit center after go-live.', a: 'Check the material master\'s profit center derivation or the substitution rule covering that material type — new master data types can fall outside existing derivation coverage and need an explicit rule added.', type: 'troubleshooting' },
      { q: 'Client wants each division to see its own standalone-style balance sheet within one legal entity for internal management purposes.', a: 'This is exactly the use case for Profit Center-level balance sheets with document splitting active — each division\'s Profit Center becomes a quasi-standalone reporting unit without requiring separate legal entities or Company Codes.', type: 'scenario' },
      { q: 'A WBS element\'s postings are landing on the wrong Profit Center compared to what the project team expected.', a: 'Check the WBS element\'s own Profit Center assignment directly — if the WBS has its own explicit assignment, it takes precedence over any cost-center-derived default, so a wrong WBS-level assignment overrides an otherwise-correct cost center setup.', type: 'troubleshooting' },
      { q: 'Client asks whether Profit Center planning data can be compared against actuals the same way cost center planning is.', a: 'Yes — profit center planning uses the same ACDOCA-based planning framework, supporting standard plan/actual variance reporting at the profit center level analogous to cost center reporting from CO Day 3.', type: 'conceptual' },
      { q: 'Auditor asks why the client activated document splitting on Profit Center when derivation was already populating the field correctly.', a: 'Derivation alone populates the field but doesn\'t guarantee the document balances to zero per profit center — splitting with zero-balance clearing is the additional mechanism required for genuinely usable profit-center-level balance sheets, which is why both are needed together.', type: 'conceptual' },
      { q: 'Client\'s sales-order-derived Profit Center doesn\'t match what the cost-center-based default would have produced for the same transaction.', a: 'This can be legitimate — if the sales order (or its material) has its own profit center derivation logic distinct from the fulfilling cost center\'s default, the sales-order-driven value can correctly differ, reflecting a deliberate profitability view by sales channel rather than an error.', type: 'conceptual' },
      { q: 'Client wants a consolidated regional profit center view without disrupting the divisional standard hierarchy already in place.', a: 'Build a Profit Center Group for the regional view — this coexists with the mandatory standard hierarchy (which likely reflects divisional structure) without requiring any change to that underlying structural tree.', type: 'scenario' },
      { q: 'Auditor asks how many cost centers can legitimately share the same Profit Center assignment.', a: 'Any number — it\'s common and expected for many cost centers within a division to all roll up to that division\'s single Profit Center; the 1:1 constraint (CO Day 3) applies to a cost center having exactly one profit center, not the reverse.', type: 'conceptual' },
      { q: 'A newly implemented sales channel shows all its transactions landing in the dummy profit center.', a: 'Check whether Profit Center derivation logic has been extended to cover the new sales channel\'s specific order types or materials — a newly introduced channel can fall outside existing derivation coverage the same way a new material type can, requiring an explicit rule addition.', type: 'troubleshooting' },
      { q: 'Client asks whether transfer pricing between profit centers requires a separate Company Code structure.', a: 'No — transfer pricing / multiple valuation operates within Profit Center Accounting\'s multiple valuation views, independent of Company Code structure; it values the same movement differently for internal margin purposes without needing separate legal entities.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that Profit Center Groups used in a management report don\'t inadvertently double-count any profit center.', a: 'Review the Profit Center Group structure for overlapping membership — since groups are a flexible reporting layer (potentially nested), a profit center accidentally included in two sibling groups being summed together would double-count that profit center\'s figures in the aggregated report.', type: 'conceptual' },
      { q: 'Client wants to know whether changing a Profit Center\'s parent node in the standard hierarchy affects historical reporting.', a: 'Since the hierarchy position is generally the current structural placement (distinct from the cost-center-level time-dependent assignment example in CO Day 3), a hierarchy change typically affects how the profit center rolls up going forward in hierarchy-based reports; confirm with the specific reporting tool whether it reflects the hierarchy as of report-run-time or the hierarchy as of posting-time for historical comparability.', type: 'conceptual' },
    ],
  },
  'co-day-7': {
    junior: [
      { q: 'What is the difference between Mark and Release for a standard cost estimate?', a: 'Mark writes the calculated cost as the future standard price without affecting current valuation. Release makes it the current standard price and revalues existing stock.', type: 'conceptual' },
      { q: 'What does the Costing Variant tie together?', a: 'Costing Type, Valuation Variant, Date Control, Quantity Structure Control, and Transfer Control — the full configuration recipe for building a cost estimate.', type: 'conceptual' },
      { q: 'What PP master data must exist before a meaningful cost estimate can run?', a: 'Bill of Materials, Work Center, Routing, and Activity Types.', type: 'conceptual' },
      { q: 'What is the difference between Price Control S and V?', a: 'S (Standard) fixes material value with variance captured separately. V (Moving Average) continuously updates value with each transaction. S/4 recommends S for actual costing scenarios.', type: 'conceptual' },
      { q: 'What does Cost Estimate Without Quantity Structure (Unit Costing) address?', a: 'Manual costing for materials lacking a full BOM/routing structure, useful for early-stage or ad hoc estimates.', type: 'conceptual' },
      { q: 'What does the Primary Cost Component Split add to the standard cost component structure?', a: 'The original primary cost element detail behind each cost component, useful for feeding account-based Margin Analysis for COGS breakdown.', type: 'conceptual' },
      { q: 'What does the Costing Sheet define?', a: 'The calculation base and overhead rate applied to that base, plus the credit — which cost center/cost element receives the overhead credit.', type: 'conceptual' },
      { q: 'What does Multi-Level Costing do?', a: 'Rolls up costs through a full BOM hierarchy, where component costs feed into the parent material\'s total cost estimate.', type: 'conceptual' },
      { q: 'What is Costing Lot Size?', a: 'The quantity assumed for a cost estimate calculation, which affects how fixed/setup costs get absorbed per unit — a different lot size can produce a materially different unit cost.', type: 'conceptual' },
      { q: 'What is Costing Status used for?', a: 'Tracking where a specific cost estimate sits in its create/mark/release lifecycle, so systems and users know whether it\'s still a draft calculation or an active standard.', type: 'conceptual' },
      { q: 'What is Date Control within a Costing Variant?', a: 'Defines which date (e.g. planned start of production) the system uses to determine which prices and master data versions are valid for the cost estimate calculation.', type: 'conceptual' },
      { q: 'What is Quantity Structure Control within a Costing Variant?', a: 'Rules for selecting which specific BOM and routing alternative to use for the cost estimate when multiple versions exist for a material.', type: 'conceptual' },
      { q: 'What is Transfer Control within a Costing Variant?', a: 'Rules determining whether an existing cost estimate from another plant or costing variant can be reused/transferred rather than recalculated from scratch.', type: 'conceptual' },
      { q: 'What does the Valuation Variant\'s "activity price strategy" specifically determine?', a: 'Which activity price (plan, actual, or a specific version) the cost estimate uses when calculating the labor/machine cost component from activity type consumption.', type: 'conceptual' },
      { q: 'How does subcontracting get valued within a cost estimate, per the Valuation Variant?', a: 'The Valuation Variant\'s strategy sequence determines whether subcontracting cost comes from a purchasing info record, a subcontracting-specific price source, or another configured fallback.', type: 'conceptual' },
      { q: 'What is the relationship between Cost Component Structure and the client\'s financial statement presentation?', a: 'Cost components (material, labor, overhead) can be mapped to align with how the client wants COGS broken down in reporting, connecting product costing detail to financial statement granularity.', type: 'conceptual' },
      { q: 'Can a material have both a Standard Cost Estimate and a Unit Cost Estimate simultaneously?', a: 'Yes — a Unit Cost Estimate (without quantity structure) can exist alongside or before a formal Standard Cost Estimate, often used for comparison or early estimation before full costing runs.', type: 'conceptual' },
      { q: 'What happens if two different BOM alternatives exist for the same material and no Quantity Structure Control rule is defined?', a: 'The system may select a default or the most recently valid alternative based on standard fallback logic, but this is exactly the ambiguity Quantity Structure Control is meant to resolve explicitly rather than leave to a default.', type: 'conceptual' },
      { q: 'What is the purpose of running a cost estimate at multiple points before final release?', a: 'To catch and correct issues (missing prices, incorrect BOM/routing) early through iterative recalculation, rather than only discovering problems at the final mark/release stage.', type: 'conceptual' },
      { q: 'Does Costing Lot Size affect variable costs the same way it affects fixed/setup costs?', a: 'No — variable costs scale roughly proportionally with quantity, so lot size has much less effect on their per-unit value; the lot size sensitivity is specifically pronounced for fixed/setup cost absorption.', type: 'conceptual' },
      { q: 'What is the relationship between Costing Variant and the Company Code/Plant combination?', a: 'A Costing Variant is typically configured to be used consistently for a given Company Code/Plant\'s standard costing runs, though multiple costing variants can exist for different costing purposes (standard, planned, simulation) even within the same plant.', type: 'conceptual' },
      { q: 'What does it mean for a cost estimate to be "marked" for a future period rather than the current one?', a: 'The calculated cost is stored as the price that will become standard at a specified future date/period, letting a company prepare and review the new standard price before it actually takes effect.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A cost estimate errors out with no clear message pointing to the root cause.', a: 'Check for a missing BOM/routing, no component price available, incorrect costing lot size, material status blocking costing, or date control misalignment — the standard multi-factor diagnostic chain.', type: 'troubleshooting' },
      { q: 'Client marks a new standard cost but stock valuation doesn\'t change.', a: 'This is expected — Mark only writes the future price; Release is the step that revalues stock, and it hasn\'t happened yet.', type: 'troubleshooting' },
      { q: 'Client asks why S/4 recommends Standard price over Moving Average for materials using Material Ledger actual costing.', a: 'Standard price provides a stable baseline for variance capture, which actual costing then reconciles against via periodic actual cost calculation — moving average would conflict with that reconciliation model.', type: 'conceptual' },
      { q: 'A multi-level BOM rollup shows an unexpectedly low cost for a finished good.', a: 'Check whether a component further down the BOM hierarchy is missing its own valid cost estimate — an uncosted component silently understates the entire rollup.', type: 'troubleshooting' },
      { q: 'Client wants to estimate a new product\'s cost before formal BOM/routing master data exists.', a: 'Use Cost Estimate Without Quantity Structure (Unit Costing), designed exactly for this pre-master-data scenario.', type: 'scenario' },
      { q: 'Auditor asks how the system ensures a material\'s standard price doesn\'t change silently mid-period.', a: 'The Create → Mark → Release lifecycle is a deliberate multi-step process with an audit trail at each stage — bypassing all three would be required for a silent, unreviewed price change.', type: 'conceptual' },
      { q: 'Client\'s cost estimate for a high-volume, low-cost item shows a wildly different unit cost than expected.', a: 'Check the Costing Lot Size used for the estimate — fixed/setup costs get absorbed very differently at a small versus large lot size, and a mismatched lot size relative to actual typical production runs is a common cause of unexpectedly skewed unit costs.', type: 'troubleshooting' },
      { q: 'Client has two valid BOM alternatives for the same finished good and cost estimates are inconsistently picking one or the other.', a: 'Configure Quantity Structure Control explicitly within the Costing Variant to define selection rules — leaving this to default/fallback logic is exactly the ambiguity that produces the inconsistent alternative selection the client is seeing.', type: 'troubleshooting' },
      { q: 'Client wants next year\'s standard cost estimate prepared and reviewed now, without disturbing this year\'s active standard price.', a: 'Mark the new cost estimate for the future period — Mark writes the calculated cost as the future standard without affecting current valuation, letting the client review it well ahead of the actual Release date that will make it the live standard.', type: 'scenario' },
      { q: 'Auditor asks how Date Control ensures a cost estimate reflects the correct time-relevant prices rather than whatever happens to be current at calculation time.', a: 'Date Control explicitly defines which reference date (e.g. planned production start) governs which price/master-data versions apply, so the estimate reflects the intended future period\'s conditions rather than accidentally using today\'s prices for a future-dated production run.', type: 'conceptual' },
      { q: 'Client wants their COGS breakdown in financial reporting to align precisely with the cost components used in product costing.', a: 'Design the Cost Component Structure with this financial reporting alignment in mind from the start — since cost components can be mapped to feed the desired COGS breakdown, this is a design decision to make early rather than retrofit after go-live.', type: 'scenario' },
      { q: 'A subcontracted component\'s cost estimate seems to be pulling from the wrong price source.', a: 'Review the Valuation Variant\'s pricing strategy sequence specifically for subcontracting — if the intended price source (e.g. a specific purchasing info record) isn\'t positioned correctly in the sequence, the system may fall through to an unintended alternative source.', type: 'troubleshooting' },
      { q: 'Client asks whether they need a Unit Cost Estimate if they already plan to build a full Standard Cost Estimate eventually.', a: 'A Unit Cost Estimate can still add value for early comparison/estimation before full BOM/routing master data is ready, or for ad hoc what-if costing — it\'s a complementary tool, not strictly redundant with a later formal Standard Cost Estimate.', type: 'scenario' },
      { q: 'Auditor asks for evidence that a released standard price genuinely went through the full create-mark-release lifecycle rather than being manually overridden.', a: 'Pull the costing status history for that material\'s price, showing the distinct create, mark, and release timestamps/users — a genuine lifecycle progression through all three stages is the evidence; a price that appears without this trail warrants further investigation.', type: 'conceptual' },
      { q: 'Client\'s cost estimate iterations keep failing at the same BOM level despite fixing the initially-reported error each time.', a: 'Check whether a deeper, previously-masked issue further down the BOM hierarchy is now surfacing after the first fix — iterative cost estimate recalculation often reveals a chain of nested issues (missing prices, invalid components) that appear sequentially rather than all at once.', type: 'troubleshooting' },
      { q: 'Client wants to compare potential production costs across three different plants before deciding where to manufacture a new product.', a: 'Run cost estimates using the Costing Variant configured for each respective plant, ensuring each estimate\'s valuation variant correctly reflects that plant\'s actual price sources and activity prices — a fair plant comparison depends on each estimate genuinely reflecting its own plant\'s cost structure, not a shared or default configuration.', type: 'scenario' },
      { q: 'Auditor asks how Transfer Control prevents unnecessary recalculation overhead across plants using the same material.', a: 'Transfer Control rules allow an existing valid cost estimate from one plant/costing variant to be reused rather than force a full recalculation, reducing processing overhead when the underlying cost structure is genuinely shared or comparable across plants.', type: 'conceptual' },
      { q: 'Client\'s multi-level cost rollup shows a correct component-level cost but an incorrect parent-level total.', a: 'Check the Cost Component Structure mapping and BOM quantity relationships at the parent level — an error in how component costs are supposed to roll up (e.g. wrong quantity per assembly) can produce a correct component cost but an incorrect aggregated parent total.', type: 'troubleshooting' },
      { q: 'Client asks whether Costing Status alone can prevent a not-yet-released cost estimate from accidentally being used in production reporting.', a: 'Costing Status tracks lifecycle stage but the actual enforcement of which price is "live" is governed by whether the estimate has been Released — Costing Status is informational/tracking, while Release is the actual control point that makes a price effective for production use.', type: 'conceptual' },
      { q: 'Auditor asks whether Date Control settings can differ between a cost estimate run for planning purposes versus one intended to become the actual standard price.', a: 'Yes — different Costing Variants (and their Date Control settings) are commonly used for planning/simulation purposes versus the formal standard-price-setting run, since the two serve different purposes and may legitimately need different reference dates.', type: 'conceptual' },
    ],
  },
  'co-day-8': {
    junior: [
      { q: 'What is the difference between WIP at Actual and WIP at Target?', a: 'WIP at Actual (by period) uses actual costs incurred so far; WIP at Target (by order) uses the target cost for the confirmed quantity.', type: 'conceptual' },
      { q: 'Does a DLV/TECO order calculate WIP or variance?', a: 'Variance — technical completion or delivery status triggers variance calculation instead of WIP.', type: 'conceptual' },
      { q: 'What do Target Cost Versions 0, 1, and 2 represent?', a: 'Different cost baselines (e.g. planned cost vs modified standard) used for comparing actual costs during variance calculation.', type: 'conceptual' },
      { q: 'What are examples of variance categories?', a: 'Input price, input quantity, resource-usage, output price, lot size, scrap, and remaining variance.', type: 'conceptual' },
      { q: 'What does REL status mean for a production order?', a: 'Released — the order is open for costing and execution.', type: 'conceptual' },
      { q: 'What is a Product Cost Collector used for?', a: 'Repetitive manufacturing scenarios, collecting costs across a continuous production process rather than discrete orders.', type: 'conceptual' },
      { q: 'What does a make-to-order sales order-based cost object typically settle to?', a: 'Margin Analysis directly, rather than updating a generic material price difference — standard behavior for this cost object type.', type: 'conceptual' },
      { q: 'What is the period-end sequence for cost object controlling?', a: 'Preliminary costing → simultaneous costing during execution → WIP or variance calculation (depending on status) → settlement.', type: 'conceptual' },
      { q: 'What is a Results Analysis Key?', a: 'A configuration object identifying which valuation method and rules apply for WIP/results analysis calculation on a specific cost object type.', type: 'conceptual' },
      { q: 'What is an RA Version?', a: 'A version of the Results Analysis configuration, similar in spirit to CO planning versions, allowing different valuation scenarios to be maintained without disturbing the primary one.', type: 'conceptual' },
      { q: 'What are Line IDs in the context of WIP calculation?', a: 'Categorization labels (e.g. costs of material, costs of labor) that WIP calculation uses to structure and present the calculated WIP value by cost type.', type: 'conceptual' },
      { q: 'What is a Variance Key?', a: 'Determines whether variance calculation is even active for a given material/order, and which variance categories and target cost versions apply.', type: 'conceptual' },
      { q: 'What is Target Cost Version 0 specifically?', a: 'The standard baseline comparing actual costs against the current standard cost estimate — the default and most commonly used version.', type: 'conceptual' },
      { q: 'What is Target Cost Version 1 typically used for?', a: 'Comparing actual costs against a modified standard, useful when a client wants variance measured against an adjusted baseline different from the pure current standard.', type: 'conceptual' },
      { q: 'What is Target Cost Version 2 typically used for?', a: 'Comparing actual costs against a preliminary cost estimate rather than the released standard, useful for orders costed before a formal standard was fully established.', type: 'conceptual' },
      { q: 'What is Scrap variance specifically capturing?', a: 'The cost impact of material or output lost during production beyond what was planned, distinct from input price or quantity variance categories.', type: 'conceptual' },
      { q: 'What is Output Price variance?', a: 'The difference caused by the finished output being valued at a different price than planned, distinct from input-side variances on materials/activities consumed.', type: 'conceptual' },
      { q: 'What is Lot Size variance?', a: 'Variance arising specifically because the actual production quantity differed from the lot size assumed in the standard cost estimate, affecting fixed cost absorption.', type: 'conceptual' },
      { q: 'What does "Resource-Usage variance" specifically measure?', a: 'Differences arising from using different resources (e.g. a different work center or routing) than what the standard cost estimate assumed, distinct from a pure quantity or price variance.', type: 'conceptual' },
      { q: 'What is the difference between a Production Order and a Process Order?', a: 'Both are discrete cost object types; Process Orders are specifically used in process manufacturing industries (chemicals, pharma) with process-specific master data (e.g. recipes) versus the routing-based discrete manufacturing production order.', type: 'conceptual' },
      { q: 'What is a Service Order in the cost object controlling context?', a: 'A cost object type collecting costs for service-based work (rather than physical production), following similar WIP/variance/settlement logic adapted for service delivery.', type: 'conceptual' },
      { q: 'What does "final costing" specifically refer to, distinct from preliminary and simultaneous costing?', a: 'The variance calculation step that occurs once the order is technically complete, comparing final actual costs against the target to produce the definitive cost variance for that order.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A production order shows WIP even though it has been marked Technically Complete (TECO).', a: 'This is a symptom to investigate — TECO status should trigger variance calculation instead of WIP; a lingering WIP value suggests the period-end sequence or status transition wasn\'t executed correctly.', type: 'troubleshooting' },
      { q: 'Client wants period-based reporting on in-progress orders rather than order-based reporting.', a: 'Use WIP at Actual (by period), since WIP at Target is order-based and doesn\'t fit a period-based reporting requirement.', type: 'scenario' },
      { q: 'Variance calculation shows a large "remaining" category the team can\'t explain via the other categories.', a: '"Remaining" is the catch-all for anything not explained by the other categories — a large remaining variance signals those other categories\' configuration or master data may be incomplete.', type: 'troubleshooting' },
      { q: 'Client asks whether event-based production cost posting changes the fundamental WIP/variance logic.', a: 'No — the underlying concepts remain the same; event-based posting changes the timing (real-time vs periodic batch) of when calculations and postings occur.', type: 'conceptual' },
      { q: 'A make-to-order cost object settles to Margin Analysis instead of a material.', a: 'This is correct, expected behavior for make-to-order scenarios — sales order-based cost objects typically settle directly to Margin Analysis rather than updating a material price difference.', type: 'conceptual' },
      { q: 'Auditor asks how the period-end sequence prevents an order from calculating both WIP and variance incorrectly in the same period.', a: 'Order status (REL vs DLV/TECO) is the structural gate — WIP applies to still-open orders, variance to technically complete/delivered ones, making the two mutually exclusive for a given order at a given time.', type: 'conceptual' },
      { q: 'Client wants variance measured against an internally adjusted baseline rather than the pure released standard cost.', a: 'Use Target Cost Version 1, configured against a modified standard — this supports the client\'s need for a customized comparison baseline without disturbing the standard Version 0 comparison other reports rely on.', type: 'scenario' },
      { q: 'An order costed before a formal standard was released shows unusual variance results under Version 0.', a: 'Consider whether Target Cost Version 2 (comparison against a preliminary cost estimate) is more appropriate for that specific order — comparing against a not-yet-finalized standard via Version 0 can produce misleading variance since the baseline itself was still provisional.', type: 'troubleshooting' },
      { q: 'Client\'s variance report shows significant Lot Size variance on several orders with normal production quantities.', a: 'Check whether the standard cost estimate\'s assumed Costing Lot Size (CO Day 7) genuinely matches typical actual production run sizes — a mismatch between assumed and actual typical lot sizes creates a structural, recurring Lot Size variance that isn\'t really about any individual order\'s abnormality.', type: 'troubleshooting' },
      { q: 'Client asks whether Scrap variance and Output Price variance can both appear on the same production order.', a: 'Yes — they measure entirely different things (material/output loss during production vs. output valuation difference) and can coexist independently on the same order, each pointing to a different root cause that needs its own investigation.', type: 'conceptual' },
      { q: 'Auditor asks how Resource-Usage variance differs from a simple input quantity variance.', a: 'Input quantity variance reflects using more or less of the planned resource; Resource-Usage variance reflects using a genuinely different resource (e.g. a substitute work center or alternate routing) than what the standard assumed — a substitution, not just a quantity deviation.', type: 'conceptual' },
      { q: 'Client\'s process manufacturing plant asks whether they should use Production Orders or Process Orders for their chemical production.', a: 'Process Orders are the standard fit for process manufacturing industries like chemicals, since they carry process-specific master data (recipes) rather than the routing-based structure Production Orders assume for discrete manufacturing.', type: 'scenario' },
      { q: 'A Service Order\'s WIP calculation behaves unexpectedly compared to a standard production order.', a: 'Confirm the Results Analysis Key and valuation method configured for that Service Order type — service-oriented cost objects can have adapted WIP/variance logic reflecting the nature of service delivery, and assuming identical behavior to a production order can lead to misinterpreting correct results as errors.', type: 'troubleshooting' },
      { q: 'Client wants two different WIP valuation scenarios maintained without disturbing their primary results analysis configuration.', a: 'Use RA Versions — similar to CO planning versions, this lets an alternative WIP valuation scenario be maintained and compared without touching the primary, production-relied-upon results analysis configuration.', type: 'scenario' },
      { q: 'Auditor asks for evidence supporting the WIP figure reported for a specific in-progress order.', a: 'Pull the WIP calculation detail by Line ID for that order, showing the categorized breakdown (material cost, labor cost, etc.) that sums to the reported WIP total — this line-level breakdown is the supporting evidence, not just the single aggregated figure.', type: 'conceptual' },
      { q: 'Client\'s variance report is missing entirely for a specific material, even though production orders clearly exist for it.', a: 'Check whether a Variance Key is actually assigned to that material — without an assigned Variance Key, variance calculation may not be active at all for orders of that material, producing no variance output regardless of actual cost activity.', type: 'troubleshooting' },
      { q: 'Client asks whether final costing (variance calculation) can be re-run if a correction is made after the order was already marked TECO.', a: 'Yes, if the order status permits reopening or a correction posting is made — variance calculation can be rerun to reflect the correction, though this should follow the client\'s formal correction/reopening process rather than an ad hoc adjustment outside standard procedure.', type: 'scenario' },
      { q: 'Auditor asks how the system distinguishes Output Price variance from a straightforward standard cost estimate error.', a: 'Output Price variance is a calculated comparison between actual output valuation and the standard at the time of the order — a systemic standard cost estimate error would show up as a consistent, repeated variance pattern across many orders using that estimate, while a one-off legitimate output pricing difference would appear isolated to specific orders.', type: 'conceptual' },
      { q: 'Client\'s process manufacturing orders show cost object controlling behaving inconsistently compared to their discrete manufacturing production orders.', a: 'Confirm whether the same period-end sequence, Results Analysis Key, and Variance Key configuration genuinely apply equivalently to Process Orders as to standard Production Orders — process manufacturing sometimes requires distinct configuration given recipe-based rather than routing-based master data, and assuming identical setup can cause unexplained inconsistency.', type: 'troubleshooting' },
      { q: 'Auditor asks how the client ensures Service Orders are correctly excluded from standard manufacturing variance analysis where inapplicable.', a: 'Confirm Service Orders carry their own appropriately configured order type, Results Analysis Key, and (if applicable) Variance Key distinct from manufacturing order types — this ensures service-specific cost object controlling logic applies rather than manufacturing-oriented variance categories that may not meaningfully apply to service delivery.', type: 'conceptual' },
    ],
  },
  'fi-11': {
    junior: [
      { q: 'What tax calculation technique does a condition-based tax procedure use?', a: 'Condition types and condition records — the same technique used in SD pricing, applied to tax determination instead.', type: 'conceptual' },
      { q: 'What happens to non-deductible tax amounts?', a: 'They are added to the cost of the material or expense rather than posted to a recoverable tax account, since they cannot be reclaimed.', type: 'conceptual' },
      { q: 'What is a Tax Jurisdiction Code?', a: 'A code representing the combination of state/county/city tax authorities in a jurisdiction-based tax procedure, common in the US.', type: 'conceptual' },
      { q: 'What is the Plants Abroad scenario?', a: 'A configuration handling VAT registration obligations in a foreign country arising from having plants there, without needing a separate legal entity.', type: 'conceptual' },
      { q: 'What is Deferred Tax?', a: 'Tax liability recognized at invoice time but only reported to the tax authority once a deferral-triggering event (like payment) occurs, requiring a transfer posting.', type: 'conceptual' },
      { q: 'What does Tax Account Determination configure?', a: 'Which G/L accounts tax amounts post to, per tax code and account key — conceptually parallel to VKOA and OBYC.', type: 'conceptual' },
      { q: 'Where do India-specific GST details live in this build?', a: 'In INT-6, which covers localization frameworks separately from this tab\'s general tax procedure and condition technique content.', type: 'conceptual' },
      { q: 'What is the difference between an input and output tax code?', a: 'Input tax codes apply to purchases (potentially deductible or non-deductible); output tax codes apply to sales.', type: 'conceptual' },
      { q: 'What is a Tax Type?', a: 'A classification within a tax code determining what kind of tax is being calculated (e.g. VAT, sales tax, use tax), driving which rate and G/L posting logic applies.', type: 'conceptual' },
      { q: 'What is the difference between VAT and Sales Tax at a conceptual level?', a: 'VAT is charged and reclaimed at each stage of a supply chain (multi-stage, deductible for businesses); Sales Tax typically applies only at the final point of sale to the end consumer.', type: 'conceptual' },
      { q: 'What does a Tax Rate Type represent within a condition-based tax procedure?', a: 'The specific percentage or calculation rule tied to a condition type, which can vary by country, product category, or customer classification.', type: 'conceptual' },
      { q: 'Can a single invoice carry multiple tax codes?', a: 'Yes — different line items on the same invoice can each carry their own applicable tax code if they have different tax treatments (e.g. mixed taxable and exempt items).', type: 'conceptual' },
      { q: 'What is a Tax Exemption Certificate used for?', a: 'Documenting a customer or transaction\'s legal exemption from tax, which the tax code configuration should reference to correctly suppress tax calculation for that specific case.', type: 'conceptual' },
      { q: 'What does "reverse charge" mean in a VAT context?', a: 'A mechanism shifting the responsibility for calculating and reporting VAT from the seller to the buyer, commonly used in specific cross-border or industry scenarios.', type: 'conceptual' },
      { q: 'What is the relationship between Tax Procedure and Country?', a: 'A Tax Procedure is assigned per country, and each Company Code operating in that country inherits the country\'s tax procedure for its transactions.', type: 'conceptual' },
      { q: 'What does the Advance Return for Tax on Sales/Purchases actually consolidate?', a: 'Tax code-level detail across the reporting period into the specific declaration format required by that country\'s tax authority for periodic filing.', type: 'conceptual' },
      { q: 'Why might a company need both a tax code for standard-rate goods and a separate one for reduced-rate or zero-rated goods?', a: 'Different goods/services can be legally subject to different tax rates in the same country, so distinct tax codes are needed to correctly calculate and report each rate category separately.', type: 'conceptual' },
      { q: 'What happens if a transaction is posted with the wrong tax code?', a: 'It results in an incorrect tax amount and potentially an incorrect statutory tax filing — correcting this typically requires reversing and reposting with the correct tax code rather than simply adjusting the amount.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A client\'s tax report shows a mismatch between the configured rate and posted amount.', a: 'Check whether a non-deductible portion is being added to material cost instead of a recoverable tax account, or whether a jurisdiction code is layering multiple tax authorities in a way that looks like a single rate mismatch.', type: 'troubleshooting' },
      { q: 'Client has plants generating sales in a country with no separate legal entity, facing a local VAT audit.', a: 'This is the Plants Abroad scenario — the Company Code must register and report VAT in that country due to the plant\'s presence, without requiring a new legal entity.', type: 'scenario' },
      { q: 'Auditor asks why a deferred tax liability sat unreported for two months.', a: 'This is expected for deferred tax — the liability is recognized at invoice time but only reported once the deferral event occurs, requiring a transfer posting at that point.', type: 'conceptual' },
      { q: 'Client wants to move to a condition-based tax procedure like TAXINN for a new country rollout.', a: 'Condition-based procedures are the standard, flexible S/4 approach, reusing the condition technique for more granular and maintainable tax determination than flat percentage tables.', type: 'scenario' },
      { q: 'Client\'s cross-border transaction with a business customer in another EU country needs reverse charge VAT treatment.', a: 'Configure the tax code for that transaction type to apply reverse charge logic, shifting VAT reporting responsibility to the buyer rather than calculating standard output VAT on the seller\'s side — this requires the tax code and condition configuration to correctly recognize the cross-border B2B scenario.', type: 'scenario' },
      { q: 'A tax audit flags that several transactions used an incorrect tax code for reduced-rate goods.', a: 'Reverse and repost the affected transactions with the correct tax code rather than adjusting the tax amount directly — since the tax code drives both the rate and the account determination, a direct amount adjustment wouldn\'t correct the underlying statutory reporting classification.', type: 'troubleshooting' },
      { q: 'Client asks whether a single tax procedure can handle a country with multiple tax rate tiers (standard, reduced, zero-rated).', a: 'Yes — one tax procedure can support multiple tax codes representing the different rate tiers, with condition records maintaining each specific rate; the procedure structure itself doesn\'t need to change per rate tier.', type: 'conceptual' },
      { q: 'A customer claims tax exemption but the invoice still calculated standard tax.', a: 'Verify a valid Tax Exemption Certificate is on file and correctly referenced in the transaction\'s tax determination — a missing or unlinked exemption certificate means the system has no basis to suppress the standard tax calculation.', type: 'troubleshooting' },
      { q: 'Client operating in multiple countries wants consistent tax code naming conventions across all of them.', a: 'While tax procedures and rates are inherently country-specific, establish a consistent naming/numbering convention for tax codes across countries for easier cross-country reporting and support, even though the underlying rates and rules will legitimately differ.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents an invoice from mixing taxable and tax-exempt line items incorrectly.', a: 'Each line item carries its own tax code assignment, so a mixed invoice correctly applies different tax treatment per line rather than forcing one uniform tax code across the whole document — this line-level granularity is what supports correctly mixed invoices.', type: 'conceptual' },
      { q: 'Client\'s tax report shows a large volume of transactions using a generic "standard rate" tax code when several should have used a reduced rate.', a: 'This points to a tax code selection/determination issue at transaction entry or automatic determination — review the default tax code logic (e.g. from material master or customer master defaults) to see why the reduced-rate cases aren\'t routing to the correct code.', type: 'troubleshooting' },
      { q: 'Client asks whether Tax Account Determination needs separate configuration per tax rate tier within the same tax type.', a: 'Yes if the tiers should post to genuinely different G/L accounts (uncommon but possible), but typically all rate tiers of the same tax type post to the same recoverable/payable tax accounts, with only the rate itself differing by tax code — confirm the client\'s specific reporting needs before assuming separate accounts are required.', type: 'conceptual' },
      { q: 'Auditor asks how reverse charge transactions are distinguished from standard VAT transactions in reporting.', a: 'Reverse charge transactions use a specifically configured tax code/condition type flagged for that treatment, which statutory tax reports (like the Advance Return) recognize and report separately from standard output/input VAT — this is a configuration-level distinction, not something requiring manual reclassification at reporting time.', type: 'conceptual' },
      { q: 'Client wants to know whether a Tax Exemption Certificate needs to be renewed periodically.', a: 'This depends on the specific jurisdiction\'s statutory requirements — some exemption certificates have expiration dates requiring renewal, and the client\'s tax compliance process should track certificate validity to avoid a lapsed certificate incorrectly continuing to suppress tax calculation.', type: 'scenario' },
    ],
  },
  'fi-12': {
    junior: [
      { q: 'What is a Statistical special G/L indicator used for?', a: 'Informational-only postings, like guarantees, that need tracking without being part of the regular open item ledger.', type: 'conceptual' },
      { q: 'What is a Noted Item?', a: 'A memo posting with no G/L impact until it converts into a real transaction, such as a down payment request before actual payment.', type: 'conceptual' },
      { q: 'Why does a cross-company code posting need a common reference number?', a: 'To tie together the separate documents created in each involved Company Code for audit trail and clearing purposes.', type: 'conceptual' },
      { q: 'What is the difference between Substitution and Validation?', a: 'Substitution automatically derives or replaces field values during entry; Validation checks a posting against rules and blocks it if the rule fails.', type: 'conceptual' },
      { q: 'What is BRF+ at an awareness level?', a: 'A more modern, flexible business rule engine that can supplement or replace classic GGB0/GGB1 substitution/validation for complex scenarios.', type: 'conceptual' },
      { q: 'Can a standard clearing transaction clear an item spanning two Company Codes?', a: 'No — cross-company clearing requires a dedicated transaction since standard clearing operates within one Company Code.', type: 'conceptual' },
      { q: 'What are Bills of Exchange represented as in FI?', a: 'Their own special G/L category, tracked separately from standard receivables/payables until settled or discounted.', type: 'conceptual' },
      { q: 'What do Ledger Group postings enable for special G/L transactions?', a: 'Restricting certain postings to specific ledger groups so they don\'t inadvertently affect every parallel accounting principle\'s ledger.', type: 'conceptual' },
      { q: 'What is the difference between a Free Offsetting Entry special G/L and a Statistical special G/L?', a: 'Free Offsetting Entry (like down payments) creates a real, clearable posting on an alternative reconciliation account; Statistical is purely informational with no true clearing requirement.', type: 'conceptual' },
      { q: 'What is a Guarantee, in the special G/L context?', a: 'A contingent obligation (e.g. a bank guarantee issued on the company\'s behalf) tracked statistically since it represents a potential, not yet realized, financial commitment.', type: 'conceptual' },
      { q: 'Can Substitution rules reference data from other line items in the same document?', a: 'Yes — substitution logic can reference other fields within the same document context, not just the current line item, enabling more sophisticated derivation logic.', type: 'conceptual' },
      { q: 'What is a common reason to use Validation rather than Substitution for a specific business requirement?', a: 'When the goal is to prevent an incorrect posting entirely (hard stop) rather than automatically correct/derive a value — Validation blocks, Substitution fixes silently.', type: 'conceptual' },
      { q: 'What does it mean that BRF+ can "supplement" classic substitution/validation rather than fully replace it?', a: 'Both mechanisms can coexist in the same system, with BRF+ typically handling newer, more complex rule scenarios while classic GGB0/GGB1 continues handling simpler, established rules.', type: 'conceptual' },
      { q: 'What is a Security Deposit, distinct from a Guarantee, in the special G/L context?', a: 'A Security Deposit represents funds actually held by the company (or given to another party) as collateral, whereas a Guarantee is a promise/commitment without funds having actually changed hands.', type: 'conceptual' },
      { q: 'Why might a cross-company code posting require special authorization beyond standard document posting authorization?', a: 'Because it affects the financial records of more than one legal entity simultaneously, requiring broader authorization scope than a posting confined to a single Company Code.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A shared services cost split must post simultaneously to three Company Codes.', a: 'Use a cross-company code posting — it automatically creates linked documents across the involved Company Codes, tied together by a shared cross-company document number.', type: 'scenario' },
      { q: 'A validation rule blocks legitimate postings under a newly changed business policy.', a: 'Review and update the specific validation rule in GGB0/GGB1 to reflect the new policy rather than removing validation controls entirely.', type: 'troubleshooting' },
      { q: 'Client wants a security deposit tracked without appearing as a real open receivable.', a: 'Use a Statistical special G/L indicator — it tracks the deposit informationally without treating it as a true open item.', type: 'scenario' },
      { q: 'Auditor asks why a cross-company posting produces two documents rather than one.', a: 'Each Company Code involved gets its own document since Company Code is the legal entity boundary — the two are linked via a shared cross-company document number, which is the expected structure.', type: 'conceptual' },
      { q: 'Client wants a bank guarantee issued on their behalf tracked without any real G/L clearing burden.', a: 'Use a Statistical special G/L posting — since a guarantee is a contingent, not-yet-realized obligation, statistical tracking (informational, no clearing requirement) is the appropriate treatment rather than a real, clearable posting.', type: 'scenario' },
      { q: 'A cross-company posting fails because the user lacks authorization for one of the involved Company Codes.', a: 'This is expected behavior — cross-company postings require authorization spanning every involved Company Code since the transaction affects multiple legal entities simultaneously; the user needs broader authorization scope, not a workaround around the check.', type: 'troubleshooting' },
      { q: 'Client wants a substitution rule that derives a cost center based on a combination of the document\'s customer and material, both on different line items.', a: 'This is supported since substitution logic can reference other fields within the same document context, not just the current line — configure the rule to pull the needed cross-line data for the derivation.', type: 'scenario' },
      { q: 'Auditor asks why the client uses both classic substitution/validation and BRF+ in the same system.', a: 'This is a valid coexistence pattern — BRF+ handles newer, more complex rule scenarios while classic GGB0/GGB1 continues managing simpler, already-established rules; a full migration isn\'t required for both to function correctly together.', type: 'conceptual' },
      { q: 'Client\'s security deposit held on behalf of a tenant needs to be distinguished from a guarantee they issued to a supplier.', a: 'Track the security deposit (funds actually held) separately from the guarantee (a commitment without funds transferred) — both may use special G/L logic, but they represent economically different obligations that shouldn\'t be commingled in reporting.', type: 'scenario' },
      { q: 'A validation rule intended to block incomplete postings is instead silently correcting them.', a: 'Review the configuration — this behavior suggests a substitution rule, not a validation rule, is actually active for that scenario; validation should hard-block, while substitution silently derives/corrects, and a mismatch between intended and actual configured type causes this confusion.', type: 'troubleshooting' },
      { q: 'Auditor asks for evidence that all guarantees issued on the company\'s behalf are properly tracked and disclosed.', a: 'Pull the statistical special G/L postings for the Guarantee indicator across all relevant Company Codes, cross-checked against legal/treasury\'s own guarantee issuance log — this comparison confirms completeness of the statistical tracking against the actual commitments made.', type: 'conceptual' },
    ],
  },
  'co-9': {
    junior: [
      { q: 'What is the S/4-recommended profitability analysis approach?', a: 'Account-based Margin Analysis — costing-based COPA remains available but is optional and de-emphasized.', type: 'conceptual' },
      { q: 'What replaces "value fields" in account-based Margin Analysis?', a: 'G/L accounts, tying profitability reporting directly to the same chart of accounts used elsewhere in the system.', type: 'conceptual' },
      { q: 'What must be activated before Margin Analysis postings can flow?', a: 'An Operating Concern assigned to and activated for the Controlling Area.', type: 'conceptual' },
      { q: 'What does the Cost Component Split transfer into Margin Analysis enable?', a: 'A full COGS breakdown by cost component (material, labor, overhead) directly within profitability reporting.', type: 'conceptual' },
      { q: 'What do Attributed Profitability Segments solve?', a: 'Costs/revenues that legitimately belong to a profitability segment but weren\'t posted with full characteristic detail — attribution assigns them after the fact.', type: 'conceptual' },
      { q: 'Where does Margin Analysis reporting read from?', a: 'Directly and live from ACDOCA, consistent with the Universal Journal design running through the whole module.', type: 'conceptual' },
      { q: 'What is an Operating Concern?', a: 'The top-level organizational structure for profitability reporting, containing the Characteristics that segment profitability.', type: 'conceptual' },
      { q: 'What role do SD condition types play in account-based Margin Analysis versus costing-based?', a: 'The SD condition-type-to-value-field mapping pattern is more central to costing-based COPA (legacy); account-based relies primarily on the G/L account structure instead.', type: 'conceptual' },
      { q: 'What is a Characteristic in the Margin Analysis context?', a: 'A profitability reporting dimension (customer, product, region, sales organization) used to segment revenue and cost data for detailed margin analysis.', type: 'conceptual' },
      { q: 'What is Characteristic Derivation?', a: 'Rules automatically populating characteristic values (like customer or product) on a posting from the source document, rather than requiring manual entry of each characteristic.', type: 'conceptual' },
      { q: 'What is a Profitability Segment?', a: 'The specific combination of characteristic values (e.g. Customer X + Product Y + Region Z) that a posting is attributed to for margin reporting purposes.', type: 'conceptual' },
      { q: 'Can Margin Analysis include planning data, similar to cost center or profit center planning?', a: 'Yes — profitability planning can be entered at the characteristic-combination level, supporting plan/actual margin variance reporting.', type: 'conceptual' },
      { q: 'What is Costing-Based COPA\'s "value field" conceptually, for contrast with account-based?', a: 'An abstract, COPA-specific bucket (not a real G/L account) used to accumulate amounts like "gross revenue" or "material cost" — a structure unique to the legacy costing-based approach.', type: 'conceptual' },
      { q: 'What is the relationship between Margin Analysis and Sales & Distribution billing documents?', a: 'Billing documents (from INT-3\'s O2C flow) are a primary source feeding revenue and cost of goods sold data into Margin Analysis via account posting and characteristic derivation.', type: 'conceptual' },
      { q: 'What does "real-time from ACDOCA" specifically mean for margin reporting responsiveness?', a: 'A margin report reflects postings the moment they hit ACDOCA, without any batch/ETL delay — a billing document posted minutes ago is immediately reflected in margin analysis.', type: 'conceptual' },
      { q: 'What is a Value Field Group in costing-based COPA, at a legacy-awareness level?', a: 'A logical grouping of related value fields (e.g. all discount-related value fields) for costing-based COPA reporting convenience, analogous in spirit to Cost Element Groups.', type: 'conceptual' },
      { q: 'Can characteristics in Margin Analysis include custom, client-specific dimensions beyond standard ones like customer/product?', a: 'Yes — Operating Concern configuration allows adding custom characteristics relevant to the client\'s specific profitability reporting needs, beyond the standard SAP-delivered set.', type: 'conceptual' },
      { q: 'What is the risk of adding too many characteristics to an Operating Concern?', a: 'Increased complexity in derivation configuration and reporting, plus performance considerations — similar to the FI Day 5 caution against over-configuring splitting characteristics, characteristics should be limited to genuinely needed reporting dimensions.', type: 'conceptual' },
      { q: 'What does Universal Allocation\'s Margin Analysis coverage (from CO Day 4) specifically add to this tab?', a: 'The ability to allocate indirect costs (e.g. shared marketing spend) directly into profitability segments using the same modern allocation framework used for cost centers and profit centers.', type: 'conceptual' },
      { q: 'What is the difference between Margin Analysis at the Company Code level versus the Controlling Area level?', a: 'Margin Analysis operates within an Operating Concern, which is assigned to a Controlling Area — so profitability reporting can span multiple Company Codes sharing that Controlling Area, similar to other cross-CC CO reporting.', type: 'conceptual' },
      { q: 'What happens to margin reporting if Characteristic Derivation fails to populate a key characteristic on a posting?', a: 'The posting either falls into an incomplete/default profitability segment or triggers a derivation error depending on configuration — either way, it represents a data quality gap needing investigation similar to a dummy profit center posting.', type: 'conceptual' },
      { q: 'Can the same G/L account feed both standard FI reporting and Margin Analysis simultaneously?', a: 'Yes — since account-based Margin Analysis uses actual G/L accounts, the same posting naturally feeds both standard financial reporting and profitability reporting without any separate parallel entry.', type: 'conceptual' },
      { q: 'What is the purpose of comparing planned margin against actual margin by profitability segment?', a: 'It surfaces which specific customer/product/region combinations are outperforming or underperforming plan, enabling targeted management action rather than only a company-wide margin trend.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client asks why account-based Margin Analysis reconciles automatically with FI while costing-based historically drifted.', a: 'Account-based uses actual G/L accounts, structurally the same data as FI; costing-based used separate value fields that could diverge over time without careful reconciliation.', type: 'conceptual' },
      { q: 'A cost genuinely belongs to a profitability segment but was posted without full characteristic detail.', a: 'Use Attributed Profitability Segments to assign the cost to the correct segment after the fact via attribution rules.', type: 'scenario' },
      { q: 'Client runs both costing-based and account-based COPA in parallel during a transition.', a: 'This adds reconciliation and reporting complexity and should be time-boxed toward a single approach rather than treated as a permanent state.', type: 'scenario' },
      { q: 'Auditor asks how account-based Margin Analysis structurally prevents legacy FI/CO-PA drift.', a: 'Because it records to actual G/L accounts rather than abstract value fields, it is structurally the same underlying data as FI — there is no separate ledger that could drift out of sync.', type: 'conceptual' },
      { q: 'Client\'s margin report shows a growing volume of postings falling into an incomplete or default profitability segment.', a: 'Investigate Characteristic Derivation configuration for gaps, similar to investigating a dummy profit center — a growing incomplete-segment bucket signals specific source documents or master data aren\'t deriving one or more required characteristics correctly.', type: 'troubleshooting' },
      { q: 'Client wants to add ten new custom characteristics to their Operating Concern to capture every conceivable reporting angle.', a: 'Push back and recommend limiting characteristics to genuinely needed reporting dimensions — excessive characteristics increase derivation configuration complexity and reporting performance overhead without proportional reporting value, echoing the same caution from FI Day 5\'s splitting characteristics guidance.', type: 'scenario' },
      { q: 'Auditor asks how quickly a billing document posted this morning would be reflected in a margin analysis report run this afternoon.', a: 'Immediately — since Margin Analysis reads real-time from ACDOCA with no batch/ETL delay, a billing document posted this morning is already reflected in any report run afterward, a direct benefit of the account-based, ACDOCA-native design.', type: 'conceptual' },
      { q: 'Client wants to allocate a large shared marketing campaign cost across the specific customer segments it\'s expected to benefit.', a: 'Use Universal Allocation\'s Margin Analysis coverage (CO Day 4) to allocate the shared cost into the relevant profitability segments using an appropriate tracing factor — this brings indirect costs into segment-level margin visibility rather than leaving them unallocated at a higher level.', type: 'scenario' },
      { q: 'Client operating across multiple Company Codes under one Controlling Area wants consolidated profitability reporting.', a: 'Confirm the Operating Concern is properly assigned to that shared Controlling Area — Margin Analysis then naturally spans all Company Codes under it, consistent with how other cross-CC CO reporting works.', type: 'scenario' },
      { q: 'Auditor asks whether costing-based COPA value fields could ever legitimately still appear in a client\'s current reporting.', a: 'Yes, if costing-based COPA remains active alongside account-based Margin Analysis during a transition or for a specific legacy reporting need — this dual-running should be a deliberate, time-boxed choice, not an indefinite default, per the earlier caution about reconciliation complexity.', type: 'conceptual' },
      { q: 'Client\'s planned versus actual margin comparison by profitability segment reveals one product consistently underperforming plan.', a: 'This is exactly the value of segment-level plan/actual comparison — it surfaces the specific underperforming product for targeted management action (pricing, cost, or volume investigation) rather than being masked within an aggregate company-wide margin figure.', type: 'conceptual' },
      { q: 'A newly launched sales channel\'s transactions aren\'t appearing correctly segmented in Margin Analysis.', a: 'Check whether Characteristic Derivation has been extended to cover the new channel\'s specific order types or characteristics — similar to a new material type falling outside dummy profit center derivation coverage, a new channel can require an explicit derivation rule addition.', type: 'troubleshooting' },
      { q: 'Client asks whether they need Value Field Groups if they\'ve fully adopted account-based Margin Analysis.', a: 'No — Value Field Groups are specific to costing-based COPA\'s value field structure; a system running purely account-based Margin Analysis has no value fields to group, since G/L accounts (and their existing Cost Element Groups) serve the equivalent organizing function.', type: 'conceptual' },
      { q: 'Auditor asks how the system prevents the same cost from being both allocated via Universal Allocation into Margin Analysis and separately double-posted through standard billing document flow.', a: 'These represent different economic events by design — billing-driven postings reflect direct sales transactions, while Universal Allocation distributes genuinely separate indirect/shared costs; as long as the allocation source pool and the billing-driven costs are distinct underlying amounts, there is no double-counting, though this should be verified for the specific cost pools involved.', type: 'conceptual' },
      { q: 'Client wants profitability planning entered at a very granular characteristic-combination level (e.g. every individual customer-product pair).', a: 'This is supported but consider the practical planning effort and maintenance burden — very granular planning combinations may not be sustainable for the planning team to maintain accurately each cycle, and a slightly higher-level planning granularity might better balance detail against practical usability.', type: 'scenario' },
      { q: 'Auditor asks for evidence that Margin Analysis figures reconcile to the Company Code\'s standard P&L for a given period.', a: 'Since account-based Margin Analysis draws from the same G/L accounts as standard FI reporting, a reconciliation is largely structural — pull both reports for the same period and confirm the relevant revenue/COGS totals match, which they should by construction absent a genuine characteristic derivation gap.', type: 'conceptual' },
      { q: 'Client asks whether adopting account-based Margin Analysis requires giving up any reporting capability costing-based COPA provided.', a: 'Most capabilities carry over, though a few very SD-condition-type-specific costing-based reporting patterns may need to be rebuilt using the G/L-account-based approach — a careful gap assessment against the client\'s specific existing costing-based reports is worth doing before fully retiring costing-based COPA.', type: 'scenario' },
      { q: 'A characteristic derivation rule was recently changed, and historical margin reports now show different segment totals than before the change.', a: 'Check whether the change affects only new postings going forward or was mistakenly applied retroactively — like most derivation configuration changes in this module, characteristic derivation changes should only affect new postings; historical reports recalculating differently suggests an unintended retroactive application worth investigating.', type: 'troubleshooting' },
      { q: 'Auditor asks how attributed profitability segments differ from a standard characteristic derivation failure.', a: 'A standard derivation failure means the characteristic simply wasn\'t populated at posting time and needs a source-level fix; attribution is a deliberate, rules-based mechanism to assign an already-posted amount to the correct segment after the fact when full detail genuinely wasn\'t available at posting time — attribution is a designed recovery mechanism, not a symptom of broken derivation.', type: 'conceptual' },
    ],
  },
  'co-10': {
    junior: [
      { q: 'Is Material Ledger optional in S/4HANA?', a: 'No — Material Ledger is always active; Actual Costing (built on top of it) is the optional feature.', type: 'conceptual' },
      { q: 'What does Price Determination 3 enable?', a: 'Full actual costing with periodic unit price calculation.', type: 'conceptual' },
      { q: 'What is the difference between single-level and multilevel price determination?', a: 'Single-level redistributes price differences only within the material\'s own level; multilevel redistributes down through the BOM to components.', type: 'conceptual' },
      { q: 'What is the Periodic Unit Price (PUP)?', a: 'The actual cost per unit calculated at period-end by the actual costing run, replacing the standard price for that period\'s actual cost view.', type: 'conceptual' },
      { q: 'What does the Alternative Valuation Run (AVR) provide?', a: 'An additional parallel valuation perspective, like group costing, without disturbing the primary legal valuation.', type: 'conceptual' },
      { q: 'What is the standard design pairing Price Control with Material Ledger actual costing?', a: 'Price Control S (Standard), which provides a stable baseline that actual costing then reconciles against periodically.', type: 'conceptual' },
      { q: 'What are the steps of the actual costing run?', a: 'Selection, sequence determination, single-level calculation, multilevel calculation, revaluation of consumption, WIP revaluation, and post closing.', type: 'conceptual' },
      { q: 'What does the Actual Cost Component Split preserve?', a: 'Material/labor/overhead detail within the actual cost, not just the standard/planned cost, feeding richer margin reporting.', type: 'conceptual' },
      { q: 'What is Sequence Determination within the actual costing run?', a: 'The step that determines the correct BOM-level processing order — components must be actual-costed before the parent materials that consume them, so sequence matters for correct redistribution.', type: 'conceptual' },
      { q: 'What does "Post Closing" mean as the final step of the actual costing run?', a: 'The step where the calculated actual costs (Periodic Unit Price and redistributions) are formally posted to the ledger, finalizing the period\'s actual costing results.', type: 'conceptual' },
      { q: 'What is Revaluation of Consumption?', a: 'A step in the actual costing run that adjusts previously-posted consumption transactions to reflect the newly-calculated actual price rather than the standard price used during the period.', type: 'conceptual' },
      { q: 'Can Material Ledger track valuation in more than two currencies simultaneously?', a: 'Yes — up to the same multiple currency types available per FI Day 1 configuration, Material Ledger can track material values across several currencies at once, not just local and one other.', type: 'conceptual' },
      { q: 'What is the relationship between Material Ledger and the Universal Journal (ACDOCA)?', a: 'Material Ledger data and postings integrate with ACDOCA, consistent with the broader Universal Journal design absorbing what were separate ECC-era tables (MLIT among them, per FI Day 5).', type: 'conceptual' },
      { q: 'What does "legal valuation" specifically represent among the parallel valuation views?', a: 'The valuation view required for statutory/legal reporting in that specific entity\'s jurisdiction, typically the primary or default valuation view for external compliance purposes.', type: 'conceptual' },
      { q: 'What does "group valuation" represent among the parallel valuation views?', a: 'A valuation view reflecting group-level cost/transfer pricing assumptions, useful for consolidated group reporting distinct from any single entity\'s local legal valuation.', type: 'conceptual' },
      { q: 'What is the practical trigger for running an Alternative Valuation Run (AVR)?', a: 'A specific reporting need for a supplementary valuation perspective (e.g. group costing for consolidation) that shouldn\'t alter the primary legal valuation\'s postings.', type: 'conceptual' },
      { q: 'Can Actual Costing be activated for some plants in a Company Code but not others?', a: 'Yes — Actual Costing activation is typically configured at a more granular level (valuation area/plant), so a phased rollout across plants is possible even though Material Ledger itself is mandatory everywhere.', type: 'conceptual' },
      { q: 'What happens to a material\'s Periodic Unit Price if the actual costing run for that period is never executed?', a: 'No new PUP is calculated, and reporting relying on actual cost for that period would be incomplete or would fall back to the standard price view instead, depending on how the report is built.', type: 'conceptual' },
      { q: 'What is the relevance of Material Type to Material Ledger behavior?', a: 'Certain material types (e.g. raw materials vs. finished goods) may have different typical actual costing complexity given their position in the BOM structure, though Material Ledger itself applies broadly regardless of type.', type: 'conceptual' },
      { q: 'Can a material with Price Control V (moving average) still participate in Material Ledger?', a: 'Yes — Material Ledger itself is mandatory regardless of price control setting, though the combination of V with full actual costing is less common than the recommended S-plus-actual-costing pairing.', type: 'conceptual' },
      { q: 'What is the purpose of tracking parallel valuation (legal, group, profit center) specifically at the material level rather than only at a higher reporting level?', a: 'It allows genuinely different costing perspectives (e.g. transfer-priced group view vs. arm\'s-length legal view) to exist consistently down to the individual material and transaction level, rather than being approximated only through higher-level adjustments.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A candidate states Material Ledger can be disabled in S/4 to reduce overhead.', a: 'This is incorrect and a red flag — Material Ledger is always active in S/4HANA; only Actual Costing built on top of it is optional.', type: 'conceptual' },
      { q: 'Client wants a supplementary group-level costing view without changing primary legal valuation.', a: 'Use the Alternative Valuation Run (AVR) — it provides a parallel valuation perspective without disturbing the primary legal valuation.', type: 'scenario' },
      { q: 'A finished good\'s actual cost redistribution seems shallow, with component price differences not flowing through.', a: 'Check whether the material is configured for single-level rather than multilevel price determination — multilevel is required to redistribute differences down through the BOM.', type: 'troubleshooting' },
      { q: 'Client\'s actual costing run completes but WIP values don\'t reflect updated actual costs.', a: 'Check whether WIP revaluation, a distinct step in the actual costing run sequence, was actually executed — it is separate from the consumption revaluation steps.', type: 'troubleshooting' },
      { q: 'Client\'s multilevel actual costing run seems to process finished goods before their component raw materials are fully actual-costed.', a: 'Check the Sequence Determination step\'s configuration — components must be actual-costed before parent materials consuming them; an incorrect sequence produces parent-level actual costs based on not-yet-finalized component costs, understating the accuracy of the redistribution.', type: 'troubleshooting' },
      { q: 'Client wants to roll out Actual Costing to one pilot plant before committing across the whole Company Code.', a: 'This is supported — Actual Costing activation is granular enough to phase by plant/valuation area, even though Material Ledger itself remains mandatory everywhere; a pilot plant approach lets the client validate the process before a full rollout.', type: 'scenario' },
      { q: 'A material\'s reported cost seems to only reflect the standard price, with no sign of actual cost adjustment for the period.', a: 'Check whether the actual costing run was actually executed for that period and that material\'s scope — if the run wasn\'t performed, or that plant/material was excluded from scope, no Periodic Unit Price would exist and reporting would fall back to standard price only.', type: 'troubleshooting' },
      { q: 'Client\'s group consolidation team wants a different cost basis than the local legal entity\'s statutory valuation for the same materials.', a: 'Use the group valuation view within Material Ledger\'s parallel valuation, or run an Alternative Valuation Run if a supplementary perspective is needed without disturbing the primary legal valuation — either approach lets the group view coexist with, rather than override, the local statutory figures.', type: 'scenario' },
      { q: 'Auditor asks how Material Ledger prevents the group valuation view from ever being mistaken for the statutory legal valuation in external reporting.', a: 'Each valuation view is explicitly tagged and reported from its own distinct configuration (legal vs. group vs. profit center); external statutory reporting should be explicitly configured to pull from the legal valuation view specifically, and a reporting tool pulling from the wrong view would be a report configuration issue, not a Material Ledger data integrity issue.', type: 'conceptual' },
      { q: 'Client asks whether Revaluation of Consumption changes historical financial statements already issued for a prior period.', a: 'No — revaluation of consumption applies within the current period\'s actual costing run, adjusting that period\'s consumption postings to actual cost; it does not retroactively alter already-closed and issued prior-period financial statements.', type: 'conceptual' },
      { q: 'A material shows different actual costs under legal valuation versus group valuation for the identical physical transaction.', a: 'This is expected and by design — the two valuation views can apply different transfer pricing or costing assumptions to the same physical movement, producing legitimately different actual cost figures for different reporting purposes, not a data inconsistency.', type: 'conceptual' },
      { q: 'Client\'s Post Closing step fails partway through for a subset of materials.', a: 'Investigate the specific failing materials for incomplete master data, blocked status, or a sequence determination issue upstream — Post Closing is the final step and typically fails due to an unresolved problem from an earlier stage (selection, sequence, revaluation) rather than a standalone Post Closing-specific defect.', type: 'troubleshooting' },
      { q: 'Client wants confidence that switching a material from Price Control V to S ahead of activating actual costing won\'t disrupt existing inventory valuation.', a: 'This is a meaningful master data change requiring careful transition planning — moving from a continuously-updating moving average to a fixed standard price changes how the material\'s book value behaves going forward, and existing inventory quantities need to be properly revalued to the new standard as part of the switch, not left at their prior moving-average-derived value.', type: 'scenario' },
      { q: 'Auditor asks for evidence that the Periodic Unit Price genuinely reflects actual purchase and production costs for the period, not just a recalculated standard.', a: 'Trace the actual costing run\'s inputs — price differences captured through the period (from OBYC\'s PRD key, per INT-2) and actual activity consumption — through to the calculated PUP, showing the redistribution logic connecting real transactional cost data to the final period-end unit price.', type: 'conceptual' },
      { q: 'Client\'s finished goods actual cost includes an unexpected cost component that doesn\'t match their expected material/labor/overhead breakdown.', a: 'Review the Actual Cost Component Split configuration — an unexpected component category suggests either a genuine cost source the client hadn\'t anticipated (worth investigating operationally) or a cost component structure mapping issue routing costs into an unintended component category.', type: 'troubleshooting' },
      { q: 'Client asks whether Material Ledger\'s multi-currency tracking creates a reconciliation burden similar to what ECC\'s separate currency conversion tables required.', a: 'No — this is precisely the improvement Material Ledger (paired with the broader ACDOCA design from FI Day 1) provides: multiple currencies are tracked natively on the same material valuation record, eliminating the kind of separate-table reconciliation burden that existed in less integrated legacy designs.', type: 'conceptual' },
      { q: 'Auditor asks how the client ensures actual costing runs happen consistently every period without being accidentally skipped.', a: 'Confirm the actual costing run is built into the client\'s formal period-end close checklist (via Advanced Financial Closing, FI Day 10) as a scheduled, tracked task with a responsible owner — this governance integration is what prevents an ad hoc, easily-forgotten manual run from being skipped in a busy close cycle.', type: 'conceptual' },
    ],
  },
  'int-1': {
    junior: [
      { q: 'How does ACDOCA remove the FI/CO divide?', a: 'A single posting document carries both FI and CO data on the same line, rather than two separate documents that must be kept in sync.', type: 'conceptual' },
      { q: 'What eliminates the need for FI-CO reconciliation?', a: 'Cost element as G/L account — there is no separate CO-only master data object that could diverge from FI.', type: 'conceptual' },
      { q: 'What did ECC need for FI-CO sync that S/4 does not?', a: 'The Reconciliation Ledger and COFI reconciliation postings, which existed specifically to catch drift between separate FI and CO documents.', type: 'conceptual' },
      { q: 'What kind of answer do interviewers expect for "how does S/4 keep FI and CO in sync?"', a: 'A structural answer — FI and CO share the same document, so there is nothing to keep in sync procedurally.', type: 'conceptual' },
      { q: 'Do cross-Company-Code CO postings still need alignment prerequisites?', a: 'Yes — the CO Day 1 requirement of shared operating chart of accounts and fiscal year variant still applies.', type: 'conceptual' },
      { q: 'Can P&L reconciliation issues still occur in S/4?', a: 'Yes, from incomplete derivation, inconsistent Functional Area assignment, or cross-CC configuration gaps — requiring investigation, not a scheduled reconciliation run.', type: 'conceptual' },
      { q: 'What does "true vs statistical CO objects as FI sees them" mean specifically?', a: 'From an FI reporting perspective, a true CO object\'s posting is the actual financial event; a statistical object carries only an informational copy layered onto a true posting elsewhere, and FI reporting must respect this distinction to avoid double-counting.', type: 'conceptual' },
      { q: 'What is the full account assignment derivation precedence for an FI line item, restated from CO Day 2?', a: 'Document entry (if manually entered) → OKB9 default assignment → substitution rules → cost element default, in that priority order.', type: 'conceptual' },
      { q: 'What does Functional Area derivation have to do with FI-CO integration specifically?', a: 'Functional Area derives alongside cost object assignment on the same posting, keeping the cost-of-sales P&L view (FI Day 2) in sync with CO postings without requiring a separate reconciliation step.', type: 'conceptual' },
      { q: 'What is COFI, mentioned as an ECC contrast?', a: 'The CO-FI reconciliation postings ECC generated to catch and correct drift between separately-maintained FI and CO documents — a mechanism no longer needed given S/4\'s single-document design.', type: 'conceptual' },
      { q: 'What reporting implication follows from FI and CO sharing one Universal Journal document?', a: 'Every report reading ACDOCA automatically sees consistent FI and CO data by construction, without needing a "reconciled as of" caveat that ECC-era reporting sometimes required.', type: 'conceptual' },
      { q: 'Why is "one document, one table" the headline phrase for this tab?', a: 'It captures the core structural shift — S/4 doesn\'t merely integrate FI and CO more tightly, it eliminates the separate-document architecture that made drift possible in the first place.', type: 'conceptual' },
      { q: 'Does a statistical CO object ever need its own separate FI-CO reconciliation?', a: 'No — since it only carries an informational copy of a posting whose true home is elsewhere, there\'s no independent financial event on the statistical side that could drift from FI in the first place.', type: 'conceptual' },
      { q: 'What is the significance of Cross-Company-Code CO postings requiring the CO Day 1 prerequisites?', a: 'It shows that even with structural FI-CO sync at the document level, cross-entity CO reporting still depends on the foundational org-structure prerequisites (shared operating COA, shared fiscal year variant) established earlier.', type: 'conceptual' },
      { q: 'What would a "procedural" (incorrect) answer to "how does S/4 keep FI and CO in sync" sound like?', a: 'Describing a scheduled reconciliation job, a nightly batch check, or a manual review process — any answer describing an ongoing activity rather than the structural document design is the expected wrong answer this tab tests against.', type: 'conceptual' },
      { q: 'Can a P&L account intentionally have no cost object at all in a well-configured S/4 system?', a: 'No — every Primary Costs/Revenue or Secondary Costs account type posting must resolve to a valid CO object through the derivation chain; a well-configured system structurally requires this, reinforcing why FI and CO data stay consistent by construction.', type: 'conceptual' },
      { q: 'What is the relevance of this tab\'s content to interview preparation specifically?', a: 'It\'s explicitly the tab covering the single most commonly asked "prove you understand S/4 architecture" question — the structural FI-CO sync explanation — making it disproportionately high-value relative to its Q-count weight.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Auditor asks how S/4 structurally prevents the FI-CO drift ECC\'s reconciliation ledger existed to catch.', a: 'FI and CO share the same Universal Journal document; cost elements are G/L accounts, so there is no separate CO-only data that could diverge — a structural elimination, not a faster procedural fix.', type: 'conceptual' },
      { q: 'A client\'s P&L shows a reconciliation gap between a cost-object-filtered report and an unfiltered one.', a: 'Investigate incomplete cost object derivation or inconsistent Functional Area population — configuration gaps to find, not a sign FI-CO sync has failed.', type: 'troubleshooting' },
      { q: 'Client asks whether Central Finance changes FI-CO integration within one S/4 system.', a: 'No — within one system, FI-CO integration remains the single-document Universal Journal design; Central Finance replicates/centralizes data across multiple source systems, a different layer entirely.', type: 'conceptual' },
      { q: 'A cross-CC CO allocation produces an unexpected FI entry in the receiving Company Code.', a: 'Verify the CO Day 1 prerequisites — shared operating chart of accounts and fiscal year variant — are genuinely met; a mismatch is the most common cause.', type: 'troubleshooting' },
      { q: 'Client asks whether their custom-built CO allocation report needs to separately query FI data to produce a combined FI-CO view.', a: 'No — since both FI and CO data live on the same ACDOCA line, a single query against ACDOCA can produce a genuinely combined view without any separate join or reconciliation step, simplifying custom reporting significantly compared to an ECC-style dual-table design.', type: 'scenario' },
      { q: 'A candidate answering "how does S/4 keep FI and CO in sync" describes a nightly batch reconciliation process.', a: 'This is the wrong (procedural) answer this tab specifically tests against — correct the candidate toward the structural explanation: FI and CO are the same Universal Journal document, so there is no separate synchronization process running at all.', type: 'conceptual' },
      { q: 'Client\'s Functional Area-based cost-of-sales P&L view shows gaps for certain CO postings.', a: 'Check whether Functional Area derivation is configured consistently alongside cost object derivation for those specific posting types — a gap here means the cost-of-sales view is incomplete even though the standard nature-of-expense P&L and CO reporting are both otherwise correct.', type: 'troubleshooting' },
      { q: 'Auditor asks whether COFI-equivalent reconciliation postings ever need to be manually created in S/4 for any edge case.', a: 'No — since the single-document architecture structurally prevents FI-CO drift, there is no scenario in a correctly configured S/4 system requiring a manual COFI-style reconciliation posting; any perceived need for one signals a configuration gap elsewhere (like incomplete derivation) rather than a genuine architectural requirement.', type: 'conceptual' },
      { q: 'Client\'s cross-Company-Code allocation report shows correct totals for three Company Codes but a discrepancy in a fourth, newly-added one.', a: 'Verify the newly-added Company Code genuinely meets the CO Day 1 prerequisites (same operating chart of accounts, same fiscal year variant) as the other three — a late-onboarded Company Code is the most likely place for this kind of prerequisite mismatch to first surface.', type: 'troubleshooting' },
      { q: 'Client asks whether adopting Central Finance for group reporting purposes changes any of the FI-CO sync guarantees within their core S/4 system.', a: 'No — Central Finance operates as a separate replication/central-processing layer across systems; the core S/4 system\'s own FI-CO integration remains the same single-document Universal Journal design regardless of whether Central Finance is also deployed alongside it.', type: 'conceptual' },
      { q: 'A statistical CO object\'s report shows a value that doesn\'t match the true CO object\'s corresponding posting.', a: 'Investigate this as a genuine data issue, since a statistical object\'s value should always mirror an informational copy of its paired true posting — any mismatch suggests either a derivation error or an incomplete statistical posting, not an acceptable natural variation.', type: 'troubleshooting' },
      { q: 'Auditor asks for the single best piece of evidence demonstrating S/4\'s structural FI-CO integration to a skeptical stakeholder.', a: 'Show a single ACDOCA line item containing both the FI account assignment and the CO cost object assignment on the identical document/line — this concretely demonstrates there is one record, not two records being kept in sync.', type: 'conceptual' },
      { q: 'Client\'s newly configured substitution rule for cost object derivation seems to conflict with the standard OKB9 default in unpredictable ways.', a: 'Review where in the full derivation precedence chain (document entry → OKB9 → substitution → cost element default) the new rule is positioned — an unexpected conflict usually means the substitution is intercepting earlier or later in the sequence than intended relative to OKB9.', type: 'troubleshooting' },
      { q: 'Client asks whether this tab\'s content overlaps meaningfully with CO Day 1 and CO Day 2, or is purely repetitive.', a: 'There is meaningful overlap by design — this tab revisits CO Day 1\'s org prerequisites and CO Day 2\'s derivation chain specifically through the lens of FI-CO integration and reporting implications, reinforcing the concepts from the FI reporting/reconciliation angle rather than merely repeating them.', type: 'conceptual' },
      { q: 'Auditor asks how the system would surface a genuine FI-CO reconciliation problem, if one somehow occurred despite the structural design.', a: 'Since there\'s no separate FI-CO reconciliation process to run, a genuine issue would surface as an internal data inconsistency within ACDOCA itself (e.g. a technically malformed line item) — this would be an unusual, low-level data integrity issue investigated via Basis/technical support, not a business-process-level FI-CO sync failure as understood in ECC.', type: 'conceptual' },
    ],
  },
  'int-2': {
    junior: [
      { q: 'What is the near-universal FICO interview question about Goods Receipt?', a: '"What is the accounting entry at goods receipt?" — inventory debit, GR/IR clearing credit.', type: 'conceptual' },
      { q: 'What is the accounting difference between Price Control S and V at goods receipt?', a: 'Under S, a PO-vs-standard-price difference posts to a price difference account; under V, the difference directly updates the moving average inventory value.', type: 'conceptual' },
      { q: 'What does the GBB transaction key control?', a: 'The offsetting entry for goods movements, with modifiers like VBR (consumption), VAX/VAY (goods issue/sales), ZOB/ZOF (GR with/without PO reference), and BSA (initial entry).', type: 'conceptual' },
      { q: 'Must the MM period be open for goods movements even when the FI period is open?', a: 'Yes — MMPV (MM period close) is an independent control from the FI period close.', type: 'conceptual' },
      { q: 'What does the WRX transaction key represent?', a: 'GR/IR clearing.', type: 'conceptual' },
      { q: 'What is the three-way match?', a: 'Comparing PO, Goods Receipt, and Invoice Receipt quantities/prices against tolerance keys before allowing automatic invoice release.', type: 'conceptual' },
      { q: 'What are examples of movement types and what they represent?', a: '101 (GR into stock), 201 (goods issue to cost center), 261 (goods issue for order), 601 (goods issue for delivery/SD) — each triggers specific OBYC-driven accounting.', type: 'conceptual' },
      { q: 'What does split valuation address?', a: 'Valuing the same material differently based on origin or quality grade, when a single valuation figure wouldn\'t accurately represent all stock of that material.', type: 'conceptual' },
      { q: 'What is Valuation Class?', a: 'A material master field driving OBYC account determination — it groups materials with similar accounting treatment together so they post to the same G/L accounts.', type: 'conceptual' },
      { q: 'What is Valuation Grouping Code?', a: 'Groups plants together so they can share the same OBYC account determination configuration, reducing the need for plant-specific account determination setup.', type: 'conceptual' },
      { q: 'What is Material Type and how does it relate to accounting?', a: 'A classification (raw material, finished good, trading good, etc.) controlling number ranges, valuation behavior, and which views (accounting, costing) are relevant for that material category.', type: 'conceptual' },
      { q: 'What is a Purchasing Organization?', a: 'The MM org unit responsible for procurement activities and contract negotiation, distinct from the Purchasing Group (the buyer/team) and Plant (where goods are received/used).', type: 'conceptual' },
      { q: 'What is a Purchasing Group?', a: 'Represents the specific buyer or buying team responsible for a purchase, a more granular assignment within a Purchasing Organization.', type: 'conceptual' },
      { q: 'What is a Valuation Area, typically set at what level?', a: 'The organizational level (usually Plant) at which material valuation and account determination are actually applied — most designs set Valuation Area at Plant level.', type: 'conceptual' },
      { q: 'What does the KDM transaction key handle?', a: 'Exchange rate differences arising during the P2P process, such as when the invoice is settled in a different exchange rate environment than the original PO/GR.', type: 'conceptual' },
      { q: 'What does the UMB transaction key handle?', a: 'Revaluation postings, capturing gains/losses when a material\'s value is formally revalued (e.g. through a price change or valuation run).', type: 'conceptual' },
      { q: 'What does the FR1 transaction key represent?', a: 'Freight charges incurred as part of the procurement transaction, posted to a specific freight expense/clearing account distinct from the base material cost.', type: 'conceptual' },
      { q: 'What is a Landed Cost / Delivery Cost?', a: 'Additional costs beyond the base material price (freight, customs, insurance) that get added to the material\'s valuation as part of the total cost of acquiring it.', type: 'conceptual' },
      { q: 'What is Consignment stock, at an accounting level?', a: 'Stock physically held by the buyer but still owned by the vendor until consumed — no liability/inventory value is recognized on the buyer\'s books until actual consumption occurs.', type: 'conceptual' },
      { q: 'What is Stock Transfer, and does it always involve a full P2P accounting entry chain?', a: 'Moving stock between plants or storage locations; if within the same valuation area it may be a simple quantity movement, while a cross-valuation-area transfer typically involves a full accounting entry similar to a sale/purchase.', type: 'conceptual' },
      { q: 'What does movement type 309 specifically represent?', a: 'A material-to-material transfer posting, converting one material into another (e.g. reclassifying stock) rather than moving the same material between locations.', type: 'conceptual' },
      { q: 'What do movement types 543 and 561 represent?', a: '543 is component consumption for subcontracting; 561 is an initial stock receipt (e.g. for data migration or a new material entering the system for the first time).', type: 'conceptual' },
      { q: 'What is the purpose of a Tolerance Key in the three-way match?', a: 'Defining the acceptable percentage or absolute variance threshold between PO, GR, and IR quantities/prices before the system automatically blocks the invoice for manual review.', type: 'conceptual' },
      { q: 'What happens to an invoice blocked by the three-way match?', a: 'It remains in a blocked status, excluded from automatic payment selection, until a user with appropriate authorization manually reviews and releases it.', type: 'conceptual' },
      { q: 'What is the relationship between MMPV and the periodic depreciation/actual costing runs from other tabs?', a: 'MMPV\'s closed-period control affects when goods movements (which feed into cost/valuation data) can post, indirectly influencing the timing of downstream processes like Material Ledger\'s actual costing run that depend on that period\'s movement data being finalized.', type: 'conceptual' },
      { q: 'What is a common cause of the GR/IR clearing account showing a non-zero balance at any given moment during normal operations?', a: 'Timing differences are completely normal — goods can be received before the invoice arrives (or vice versa), so a non-zero GR/IR balance mid-period reflects legitimate timing gaps, not necessarily an error requiring immediate investigation.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A vendor invoice is blocked and the client asks why.', a: 'Check the three-way match against PO/GR quantities and prices — a variance exceeding configured tolerance keys triggers an automatic invoice block.', type: 'troubleshooting' },
      { q: 'A GR/IR clearing account shows a persistent, unexplained balance.', a: 'Run GR/IR analysis to identify specific GR-without-IR or IR-without-GR mismatches, then investigate unposted invoices, quantity discrepancies, or cancelled POs with lingering GR postings.', type: 'troubleshooting' },
      { q: 'A goods movement fails to post despite the FI period being confirmed open.', a: 'Check MMPV (MM period close) — an independent control from the FI period that blocks goods movements regardless of FI period status.', type: 'troubleshooting' },
      { q: 'Auditor asks how Material Ledger actual costing (CO-10) connects to standard P2P accounting entries.', a: 'Price differences captured through OBYC\'s PRD key during the period feed into the Material Ledger\'s actual costing run at period-end, which calculates the Periodic Unit Price reconciling planned costs against actuals.', type: 'conceptual' },
      { q: 'Client asks how subcontracting accounting differs from a standard goods receipt.', a: 'Subcontracting uses specific movement types (like 543 for component consumption at the subcontractor) with their own OBYC-driven postings, reflecting components consumed at an external location.', type: 'conceptual' },
      { q: 'Client wants freight and customs costs included in a material\'s inventory valuation rather than expensed separately.', a: 'Configure landed cost / delivery cost handling so these additional costs post to the material\'s valuation via the appropriate OBYC keys (like FR1 for freight) rather than a standalone expense account — this correctly reflects the total cost of acquiring the material in inventory value.', type: 'scenario' },
      { q: 'Client\'s consignment stock shows no liability on their books despite physically holding the vendor\'s inventory.', a: 'This is expected — consignment stock remains vendor-owned until consumption, so no liability or inventory value should be recognized until the buyer actually consumes it; recognizing a liability earlier would misstate the buyer\'s books.', type: 'conceptual' },
      { q: 'A stock transfer between two plants in different valuation areas produces an unexpected accounting entry, while a transfer within one valuation area does not.', a: 'This is expected and by design — cross-valuation-area transfers are treated similarly to a sale/purchase with full accounting entries, while same-valuation-area transfers are typically simpler quantity movements without the same accounting impact.', type: 'conceptual' },
      { q: 'Client asks why two plants with nearly identical account determination needs still require separate Valuation Class configuration per material.', a: 'Valuation Grouping Code is what lets similar plants share OBYC configuration efficiently — if both plants are assigned the same Valuation Grouping Code, they don\'t need separate account determination setup even with different plant codes, reducing the configuration burden the client is concerned about.', type: 'conceptual' },
      { q: 'Auditor asks how the system prevents an invoice with a large, suspicious price variance from a PO from posting automatically.', a: 'Tolerance Keys within the three-way match configuration define the threshold beyond which an invoice is automatically blocked rather than posted — a large variance exceeding the configured tolerance is exactly the control catching this scenario before automatic posting.', type: 'conceptual' },
      { q: 'Client\'s GR/IR clearing account carries a moderate balance every single month-end, and finance is concerned this indicates an ongoing problem.', a: 'A recurring moderate balance reflecting normal timing differences (goods received before invoices arrive, or vice versa) is expected and not inherently problematic — the concern should focus on whether GR/IR regrouping (FI Day 10) correctly reclassifies it for balance sheet presentation and whether the balance is growing abnormally over time, not on its mere existence.', type: 'conceptual' },
      { q: 'A vendor invoice for a subcontracted assembly shows different accounting treatment than the client expected from a standard purchase.', a: 'This is expected — subcontracting uses its own movement types (like 543) with distinct OBYC-driven postings reflecting that components were consumed at an external location before the assembled good was received back, a fundamentally different accounting story than a straightforward material purchase.', type: 'conceptual' },
      { q: 'Client wants to reclassify a batch of raw material stock into a different material code without a physical movement.', a: 'Use movement type 309 for the material-to-material transfer — this correctly handles the accounting reclassification without implying goods physically moved locations, distinct from movement types representing physical relocation.', type: 'scenario' },
      { q: 'Auditor asks how exchange rate differences between PO placement and invoice settlement are captured in the accounting entries.', a: 'The KDM transaction key captures exchange rate differences arising during the P2P process — if the invoice settles at a different rate than the original PO/GR reflected, KDM ensures this difference is properly posted rather than silently absorbed elsewhere.', type: 'conceptual' },
      { q: 'Client asks whether MM period close (MMPV) needs to be managed separately by a different team than FI period close.', a: 'Not necessarily a different team, but it does require separate awareness and coordination — since MMPV is an independent control, the close calendar must explicitly account for both MM and FI period statuses rather than assuming one governs the other.', type: 'scenario' },
      { q: 'A newly onboarded plant\'s goods receipts are posting to unexpected G/L accounts compared to other established plants.', a: 'Check the new plant\'s Valuation Grouping Code and Valuation Class-to-account mappings — a new plant not correctly assigned to the same grouping as established plants will use different (or default/incomplete) account determination, producing the unexpected posting behavior.', type: 'troubleshooting' },
      { q: 'Client\'s revaluation of a material\'s standard price shows an unexpected gain/loss posting they can\'t immediately trace.', a: 'Trace this to the UMB transaction key — revaluation-driven gains/losses post specifically through UMB, so reviewing UMB postings for that material/period is the direct path to understanding the revaluation\'s accounting impact.', type: 'troubleshooting' },
      { q: 'Auditor asks how landed costs are allocated across multiple materials received on a single, consolidated freight shipment.', a: 'Landed cost allocation typically distributes the total freight/delivery cost proportionally across the materials on that shipment (often by value or weight), ensuring each material\'s valuation reflects its fair share of the shared delivery cost rather than one material absorbing the full shipment cost.', type: 'conceptual' },
      { q: 'Client\'s split-valuated material shows two different values for what they consider the "same" inventory.', a: 'This is expected — split valuation deliberately values the same material differently based on origin or quality grade when a single valuation figure wouldn\'t accurately represent all the stock; the two values reflect genuinely different valuation types (e.g. domestically-sourced vs. imported) rather than a data error.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that a three-way match block was appropriately released rather than bypassed.', a: 'Pull the invoice\'s release history showing the specific user, timestamp, and any noted justification for releasing the block — this documents that the block went through a deliberate manual review rather than being silently overridden or auto-released without oversight.', type: 'conceptual' },
      { q: 'Client asks whether movement type 561 (initial stock receipt) creates the same GR/IR entries as a standard movement type 101 goods receipt.', a: 'No — 561 is specifically for initial stock entry (e.g. data migration or first-time system entry) and typically doesn\'t generate the standard GR/IR clearing entries a normal purchase-order-driven 101 receipt would, since there\'s no corresponding PO/vendor invoice process to reconcile against.', type: 'conceptual' },
      { q: 'Client wants confirmation that their consignment stock arrangement won\'t distort their inventory turnover metrics.', a: 'Since consignment stock isn\'t recognized as buyer-owned inventory until consumed, it correctly stays out of the buyer\'s reported inventory value and turnover calculations until consumption — this is the intended, correct accounting treatment supporting accurate turnover metrics, not a distortion risk.', type: 'conceptual' },
    ],
  },
  'int-3': {
    junior: [
      { q: 'At which two points does the O2C flow begin creating accounting entries?', a: 'Post Goods Issue (PGI) and Billing — earlier steps like inquiry, quotation, and order carry no accounting impact.', type: 'conceptual' },
      { q: 'What is the PGI accounting entry?', a: 'COGS debit, inventory credit — a genuine financial posting, not just a logistics status update.', type: 'conceptual' },
      { q: 'On which master records must Account Assignment Group be maintained?', a: 'Both the customer master AND the material master — a dual requirement that\'s a classic troubleshooting trap.', type: 'conceptual' },
      { q: 'What is the difference between KOFI and KOFK?', a: 'KOFI is standard revenue account determination; KOFK is the CO-PA-specific variant used for costing-based COPA account determination.', type: 'conceptual' },
      { q: 'What can block a billing document from creating its accounting document?', a: 'A billing block, or gaps in VKOA or account assignment group configuration.', type: 'conceptual' },
      { q: 'Is sales order creation a valid FSCM credit check trigger point?', a: 'Yes — alongside delivery and goods issue, sales order creation is one of the configurable trigger points.', type: 'conceptual' },
      { q: 'What is a Sales Organization?', a: 'The top-level SD org unit responsible for selling and distributing products/services, often tied to a specific market or legal entity for sales purposes.', type: 'conceptual' },
      { q: 'What is a Distribution Channel?', a: 'The route to market through which goods reach the customer (e.g. wholesale, retail, online), allowing the same material to be sold differently by channel.', type: 'conceptual' },
      { q: 'What is a Division in the SD org structure?', a: 'A grouping of products or services (e.g. by product line) allowing separate sales/reporting views within the same Sales Organization.', type: 'conceptual' },
      { q: 'What is a Sales Area?', a: 'The combination of Sales Organization, Distribution Channel, and Division that together define the specific sales context a transaction operates within.', type: 'conceptual' },
      { q: 'What is a Shipping Point?', a: 'The physical location from which goods are shipped, relevant both logistically and for certain account/tax determination purposes tied to origin.', type: 'conceptual' },
      { q: 'What account key does ERL represent?', a: 'Revenue — the standard account key routing recognized revenue amounts to the appropriate G/L account via VKOA.', type: 'conceptual' },
      { q: 'What account key does ERS represent?', a: 'Sales deductions/rebates — routing amounts that reduce recognized revenue (like customer rebates) to their own distinct G/L account.', type: 'conceptual' },
      { q: 'What account key does ERF represent?', a: 'Freight revenue — routing any freight charged to the customer as part of the sale to its own specific revenue account.', type: 'conceptual' },
      { q: 'What account key does MWS represent?', a: 'Output tax — routing the tax portion of a billing document to the appropriate tax payable account.', type: 'conceptual' },
      { q: 'What is a Rebate/Condition Contract, at an awareness level?', a: 'An agreement with a customer for retroactive discounts based on purchase volume/value over a period, settled periodically rather than applied at each individual transaction.', type: 'conceptual' },
      { q: 'What is Intercompany Billing?', a: 'A billing process where a supplying entity bills a selling entity for goods that ultimately reach an external customer, creating a distinct internal revenue/cost event alongside the external sale.', type: 'conceptual' },
      { q: 'What is the difference between a Billing Block and a Delivery Block?', a: 'A Billing Block prevents a billing document from being created/released; a Delivery Block prevents the goods delivery step from proceeding — they act at different points in the O2C flow.', type: 'conceptual' },
      { q: 'Does the SD Pricing Procedure determine the FI revenue account directly?', a: 'No — the Pricing Procedure determines the price/condition amounts; VKOA (a separate account determination step) determines which G/L account those condition amounts post to via account keys.', type: 'conceptual' },
      { q: 'What is the relevance of Condition Records to FI-relevant pricing?', a: 'Condition Records store the actual maintained prices/rates for each condition type, which the Pricing Procedure then applies to calculate the amounts that flow into the FI-relevant account keys.', type: 'conceptual' },
      { q: 'What does "FSCM credit checks tying into the SD process" mean practically?', a: 'Credit exposure calculations (FI Day 8) evaluate against real-time SD document data (open orders, deliveries) at each configured trigger point, making SD the operational front line where credit blocks are actually enforced.', type: 'conceptual' },
      { q: 'What is the relationship between Revenue Recognition (RAR) and standard billing-triggers-revenue logic?', a: 'Standard logic recognizes revenue directly at billing; RAR is needed when performance obligations, bundling, or multi-period contracts mean revenue recognition timing must diverge from the simple billing-document trigger, per IFRS 15 requirements.', type: 'conceptual' },
    ],
    senior: [
      { q: '"Billing document not released to accounting" — walk the diagnostic chain.', a: 'Check VKOA missing entries, blank account assignment group on customer or material, closed posting period, missing profit center/segment, or a missing splitting rule.', type: 'troubleshooting' },
      { q: 'Why does PGI create a CO-relevant posting before billing occurs?', a: 'COGS hits a Primary Costs account type at PGI, flowing into CO reporting and Margin Analysis even before revenue is recognized at billing.', type: 'conceptual' },
      { q: 'Client wants revenue recognition for a bundled, multi-period contract per IFRS 15.', a: 'This requires RAR (Revenue Accounting and Reporting) — standard billing-at-invoice logic is insufficient for performance-obligation-based recognition across periods.', type: 'scenario' },
      { q: 'A revenue posting lands on the wrong G/L account despite correct-looking VKOA.', a: 'Check the Account Assignment Group on both customer AND material master — a gap on either side is more often the root cause than the VKOA table itself.', type: 'troubleshooting' },
      { q: 'Client wants freight charged to a customer to post to a separate revenue line from product sales revenue.', a: 'Ensure the freight condition type routes through the ERF account key rather than ERL — this is exactly the mechanism that keeps freight revenue distinct from product revenue in the P&L, provided VKOA is correctly configured for ERF.', type: 'scenario' },
      { q: 'A customer\'s rebate accrual doesn\'t appear to reduce recognized revenue as expected.', a: 'Check whether the rebate condition is routing through the ERS (sales deductions) account key rather than being miscategorized as ERL — a rebate incorrectly treated as straight revenue would fail to show the expected revenue reduction.', type: 'troubleshooting' },
      { q: 'Client\'s intercompany billing scenario produces two separate revenue postings for what looks like one physical sale.', a: 'This is expected — external billing (selling entity to customer) and intercompany billing (supplying entity to selling entity) are two distinct, independent revenue/cost events, each creating its own accounting document, not a duplication of one event.', type: 'conceptual' },
      { q: 'Auditor asks how the Sales Area concept (Sales Org + Distribution Channel + Division) affects revenue account determination.', a: 'VKOA can key on Sales Organization as one of its determination factors, so different sales areas can route to different revenue accounts if the client\'s reporting needs revenue segmented by sales organization — the Sales Area structure feeds directly into this account determination granularity.', type: 'conceptual' },
      { q: 'Client\'s billing document creation is blocked and they can\'t determine whether it\'s a Billing Block or a Delivery Block.', a: 'Check the specific block field on the relevant document — Billing Block sits on the billing-relevant document and stops billing document creation, while Delivery Block sits earlier and stops the delivery step; the two block different stages and should not be confused when troubleshooting.', type: 'troubleshooting' },
      { q: 'Client asks whether changing their Pricing Procedure will automatically change which G/L accounts revenue posts to.', a: 'No — Pricing Procedure determines the price/condition amounts, while VKOA (a separate, independent configuration) determines the G/L account routing via account keys; a pricing procedure change alone doesn\'t alter account determination unless VKOA is also updated.', type: 'conceptual' },
      { q: 'Auditor asks how the system prevents a sales order from proceeding for a customer with insufficient credit exposure headroom.', a: 'FSCM credit checks fire at sales order creation (one of the configured trigger points) evaluating real-time exposure against the customer\'s Credit Segment limit — if exposure would exceed the limit, the order is blocked or flagged pending release, tying SD process execution directly to FI Day 8\'s credit management design.', type: 'conceptual' },
      { q: 'Client\'s rebate/condition contract settlement produces an unexpected accounting entry the finance team doesn\'t recognize.', a: 'Review the specific settlement process for that rebate contract — periodic rebate settlements can generate distinct accrual reversal and payment postings that look unfamiliar if the finance team hasn\'t previously worked with condition contract settlement mechanics.', type: 'troubleshooting' },
      { q: 'A client operating multiple Divisions within one Sales Organization wants separate profitability visibility by Division.', a: 'Ensure Division is included as a relevant characteristic in Margin Analysis (CO-9) derivation, and confirm VKOA/account determination differentiates by Division where the client\'s reporting requires it — Division-level segmentation depends on both configurations being aligned.', type: 'scenario' },
      { q: 'Auditor asks how output tax (MWS) on a billing document connects to the broader tax reporting framework from FI-11.', a: 'MWS routes the calculated output tax amount to the correct tax payable G/L account, which then feeds into the same tax code-level detail that FI-11\'s Advance Return for Tax on Sales/Purchases consolidates for statutory filing — the SD billing transaction is simply one of the sources populating that broader tax reporting framework.', type: 'conceptual' },
      { q: 'Client\'s multi-period service contract revenue is being recognized entirely at the initial billing date, which finance believes overstates early-period revenue.', a: 'This is exactly the scenario requiring RAR rather than standard billing-triggers-revenue logic — a multi-period contract with distinct performance obligations needs revenue spread according to those obligations under IFRS 15, not recognized entirely upfront at billing.', type: 'scenario' },
      { q: 'A billing document\'s revenue posts correctly, but the associated CO/Margin Analysis detail is missing expected characteristic data.', a: 'Check Characteristic Derivation (CO-9) for that specific sales area/material combination — a billing-side accounting success doesn\'t guarantee complete Margin Analysis characteristic population, since the two rely on related but distinct derivation logic.', type: 'troubleshooting' },
      { q: 'Client asks whether Shipping Point affects revenue account determination the way Sales Organization does.', a: 'Not typically for standard revenue account determination via VKOA, which usually keys on Sales Organization, Account Assignment Group, and condition/account key — Shipping Point is more logistically relevant, though it can matter for certain tax jurisdiction determination scenarios tied to origin.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that intercompany billing correctly captures both the external customer sale and the internal entity-to-entity transaction.', a: 'Pull both the external billing document (selling entity to customer) and the intercompany billing document (supplying entity to selling entity) for the same underlying physical goods movement, confirming both accounting documents were independently generated and posted as expected.', type: 'conceptual' },
      { q: 'Client wants to understand why two seemingly identical sales transactions produced different revenue account postings.', a: 'Compare the Account Assignment Group on the customer and material master for each transaction — since VKOA keys on this dual master data field, even subtly different account assignment groups between the two transactions\' customers or materials would correctly produce different account determination outcomes.', type: 'troubleshooting' },
      { q: 'Auditor asks how PGI\'s COGS posting and the later billing document\'s revenue posting are reconciled for a single sales transaction.', a: 'Both postings reference the same underlying sales order/delivery chain and typically share common characteristics (material, customer, sales area) that allow Margin Analysis to correctly match the COGS (from PGI) against the revenue (from billing) for that specific transaction, producing an accurate margin calculation despite the two events occurring at different points in time.', type: 'conceptual' },
    ],
  },
  'int-4': {
    junior: [
      { q: 'What links a Work Center to Controlling for costing purposes?', a: 'A Cost Center assignment plus default Activity Types with formula-based capacity/time calculations.', type: 'conceptual' },
      { q: 'What are the three cost-bearing events in a production order lifecycle?', a: 'Goods Issue, Activity Confirmation, and Goods Receipt.', type: 'conceptual' },
      { q: 'What happens when time is confirmed against a production order operation?', a: 'Activity allocation charges the activity type\'s cost to the order and credits the source cost center simultaneously.', type: 'conceptual' },
      { q: 'Where does make-to-order production order variance typically settle?', a: 'Directly to Margin Analysis rather than updating a generic material price difference.', type: 'conceptual' },
      { q: 'What serves the cost-collection role of a production order in repetitive manufacturing?', a: 'A Product Cost Collector.', type: 'conceptual' },
      { q: 'What PP-level input feeds directly into activity price calculation?', a: 'Work center capacity and formulas — time per unit, setup time.', type: 'conceptual' },
      { q: 'What is a Production Version?', a: 'A specific combination of BOM and routing alternatives for producing a material, allowing multiple valid production methods for the same finished good.', type: 'conceptual' },
      { q: 'What does "cost estimation meeting PP master data" mean specifically?', a: 'Standard cost estimates (CO Day 7) rely on the same BOM/routing/work center/activity type master data that production order execution (this tab) also consumes — one shared master data foundation feeding two different CO consumption points.', type: 'conceptual' },
      { q: 'What is a Co-Product?', a: 'One of two or more primary outputs deliberately produced together from a single production process, each requiring its own cost allocation via a splitting rule.', type: 'conceptual' },
      { q: 'What is a By-Product?', a: 'A secondary, typically lower-value output incidentally produced alongside a main product, usually handled via a credit to the main product\'s cost rather than a full cost-splitting rule.', type: 'conceptual' },
      { q: 'What is Rework in production, from a cost perspective?', a: 'Additional production activity required to correct a defective output, typically generating its own order or operation with its own cost postings distinct from the original production run.', type: 'conceptual' },
      { q: 'What determines the equivalence number used in co-product cost splitting?', a: 'A configured ratio (often based on market value or another agreed metric) determining what proportion of the total production cost each co-product output should absorb.', type: 'conceptual' },
      { q: 'Can a Work Center be assigned to more than one Cost Center over its life?', a: 'The assignment can change over time (e.g. reorganization), similar to other time-dependent master data patterns, though at any given moment a Work Center carries one active Cost Center assignment.', type: 'conceptual' },
      { q: 'What is the relationship between a Production Order\'s Order Type and its cost collection behavior?', a: 'Order Type governs foundational settings (number range, settlement profile, category) that determine how the order\'s costs are ultimately collected and settled, similar to the internal order order type concept from CO Day 5.', type: 'conceptual' },
      { q: 'What does "capacity" specifically mean for a Work Center in the activity price context?', a: 'The available time/output the work center can provide in a period, which combined with formulas (time per unit) determines planned activity consumption feeding into activity price calculation.', type: 'conceptual' },
      { q: 'Can a single production order use activity types from multiple different work centers/cost centers?', a: 'Yes — a multi-operation routing can involve several work centers, each contributing its own activity type consumption and corresponding cost center credit to the same production order.', type: 'conceptual' },
      { q: 'What is the difference between a planned activity confirmation and an actual activity confirmation?', a: 'Planned reflects the routing\'s expected time per unit before execution; actual reflects the genuinely confirmed time entered by the operator during real production, which is what actually drives activity allocation.', type: 'conceptual' },
      { q: 'What happens to a production order\'s cost if an operation is skipped entirely during execution?', a: 'No activity confirmation (and therefore no activity allocation cost) posts for that skipped operation, which will show as a variance against the planned cost estimate that assumed the operation would occur.', type: 'conceptual' },
      { q: 'What is the relevance of the Standard Cost Estimate (CO Day 7) to a production order\'s variance calculation (CO Day 8)?', a: 'The standard cost estimate typically serves as (or feeds) the Target Cost Version 0 baseline that actual production order costs are compared against during variance calculation.', type: 'conceptual' },
    ],
    senior: [
      { q: 'A cost center appears chronically over/under-absorbed each month.', a: 'Trace to activity price (plan price) vs actual cost — differences during the period are expected until period-end revaluation, not necessarily an error.', type: 'troubleshooting' },
      { q: 'Why does a missing Routing break the standard cost estimate but not the production order?', a: 'Cost estimation needs Routing for planned activity consumption; the production order can still be created and executed operationally, though its actual costs will be incompletely planned.', type: 'conceptual' },
      { q: 'A confirmation is reversed after the original activity allocation posted.', a: 'The reversal generates an offsetting activity allocation entry, crediting back the production order and re-debiting the cost center.', type: 'troubleshooting' },
      { q: 'A work center\'s capacity formula understates setup time.', a: 'This distorts activity price calculation since capacity/formula data feeds directly into it — an understated setup time skews the activity price charged to every production order using that work center.', type: 'troubleshooting' },
      { q: 'Client has two valid production methods for the same finished good depending on available equipment.', a: 'Configure two Production Versions, each with its own BOM/routing combination — this lets the production planner select the appropriate version per order without needing entirely separate material codes for what is functionally the same finished good.', type: 'scenario' },
      { q: 'A by-product\'s value seems to be inflating the main product\'s reported cost rather than reducing it.', a: 'Verify the by-product credit is configured correctly to reduce (not add to) the main product\'s cost — by-product handling should net out the by-product\'s value against total production cost, and a misconfiguration here would incorrectly leave the main product bearing the full undiminished cost.', type: 'troubleshooting' },
      { q: 'Client wants two co-products from one production run to split cost based on relative market value rather than volume.', a: 'Configure the equivalence numbers in the co-product cost-splitting rule based on market value ratios rather than a volume-based metric — this correctly allocates more cost to the higher-value co-product, reflecting the client\'s intended splitting logic.', type: 'scenario' },
      { q: 'A production order shows an unexpectedly large variance traced to a completely skipped operation.', a: 'This is expected — a skipped operation generates no activity confirmation and therefore no corresponding cost, which shows as a variance (typically resource-usage or the "remaining" category) against a standard cost estimate that assumed the operation would occur; investigate whether skipping was intentional (a process change) or an execution error.', type: 'troubleshooting' },
      { q: 'Client\'s multi-operation production order shows cost contributions from three different cost centers, and finance wants to confirm this is expected.', a: 'This is expected and correct — a multi-operation routing spanning several work centers naturally generates activity allocation cost from each work center\'s associated cost center, so seeing multiple cost center contributions on one production order reflects the genuine multi-step production process, not an error.', type: 'conceptual' },
      { q: 'Auditor asks how the system ensures rework costs are tracked separately from the original production run\'s cost.', a: 'Rework typically generates its own dedicated order or operation with its own cost postings, keeping the additional correction cost visible and traceable separately from the original production cost rather than blending the two into one undifferentiated total.', type: 'conceptual' },
      { q: 'Client\'s Work Center reorganization moved several work centers to new cost centers mid-year, and reporting now shows split cost center attribution.', a: 'This is expected given the time-dependent nature of work center-to-cost-center assignment — postings before the reorganization correctly carry the old cost center, and postings after correctly carry the new one, producing accurate historical attribution rather than retroactively rewriting the prior assignment.', type: 'conceptual' },
      { q: 'Auditor asks how a production order\'s planned versus actual activity confirmation discrepancy gets captured in variance analysis.', a: 'The difference between planned time (from the routing) and actual confirmed time flows into the resource-usage and/or input-quantity variance categories (CO Day 8) during variance calculation, giving a specific, categorized view of execution efficiency versus the original cost estimate\'s assumptions.', type: 'conceptual' },
      { q: 'Client wants confidence that switching a material to a different Production Version won\'t silently change its standard cost.', a: 'It can genuinely change the standard cost if the new version\'s BOM/routing differs materially from the prior one — recommend re-running the cost estimate under the new Production Version and comparing before switching in production, rather than assuming cost neutrality across versions.', type: 'scenario' },
      { q: 'A newly built co-product cost-splitting configuration produces a negative cost for one of the co-products.', a: 'Review the equivalence number configuration and underlying total production cost — a negative resulting cost for a co-product typically indicates a configuration error in the splitting ratios or an unusually low assumed value for that co-product relative to the total cost being split, and should be corrected before the estimate is used for pricing or reporting decisions.', type: 'troubleshooting' },
      { q: 'Auditor asks for evidence that a production order\'s activity allocation cost exactly matches the cost center\'s credit for the same transaction.', a: 'Pull the paired activity allocation posting showing the production order debit and cost center credit for the identical activity type, quantity, and price — since activity allocation is structurally balanced by design (activity price × quantity confirmed generates equal and opposite entries), this pairing is the direct evidence of exact matching.', type: 'conceptual' },
      { q: 'Client asks whether Production Version selection can be automated based on available capacity at order creation time.', a: 'This depends on PP-side configuration for automatic Production Version determination logic, which can factor in capacity availability among other criteria — from the CO integration perspective, whichever version is ultimately selected simply determines which BOM/routing (and therefore which cost structure) the order inherits.', type: 'conceptual' },
      { q: 'Auditor asks how the system distinguishes cost variance caused by rework from cost variance caused by the original production run\'s inefficiency.', a: 'Since rework typically generates its own separate order/operation with distinct cost postings, variance calculation run against the original order isolates the original run\'s performance, while rework\'s own variance (if calculated separately) isolates the correction cost — the separation of orders/operations is what enables this distinction rather than one blended variance figure.', type: 'conceptual' },
    ],
  },
  'int-5': {
    junior: [
      { q: 'What are the three core PS structural elements?', a: 'Project Definition, WBS elements, and Networks.', type: 'conceptual' },
      { q: 'Is a WBS element a true or statistical CO object?', a: 'Can be a true CO object, receiving real cost directly from purchasing and sales account assignment.', type: 'conceptual' },
      { q: 'What is an Appropriation Request?', a: 'A formal capital expenditure proposal requiring approval before an Investment Measure can proceed.', type: 'conceptual' },
      { q: 'What is the typical Investment Measure lifecycle?', a: 'Investment Measure (order/WBS) → Asset under Construction → Fixed Asset.', type: 'conceptual' },
      { q: 'What is a Symbolic Account in HCM payroll posting?', a: 'A representation of a wage type category that maps to an actual G/L account during the payroll posting run.', type: 'conceptual' },
      { q: 'What does the payroll posting run distribute besides G/L postings?', a: 'Personnel costs to cost centers.', type: 'conceptual' },
      { q: 'What is a Network in Project Systems?', a: 'A structure of scheduled activities within a project, representing the resource-driven execution plan (timing, dependencies, resource assignment) beneath the WBS cost-collection level.', type: 'conceptual' },
      { q: 'What does "WBS receiving cost from purchasing account assignment" mean specifically?', a: 'A purchase order or requisition line item can be directly account-assigned to a WBS element, so procurement spend flows straight to the project\'s cost collection point rather than through a cost center first.', type: 'conceptual' },
      { q: 'What does "WBS receiving cost from sales account assignment" mean specifically?', a: 'A sales order line item can be account-assigned to a WBS element, allowing project-related revenue or cost to flow directly to the project\'s cost object for combined project profitability tracking.', type: 'conceptual' },
      { q: 'What is an Investment Program, distinct from a single Investment Measure?', a: 'A higher-level capital planning structure that can group multiple Investment Measures (individual capital projects) together for consolidated capital budgeting and approval oversight.', type: 'conceptual' },
      { q: 'Can an Appropriation Request be rejected, and what happens to the underlying Investment Measure if so?', a: 'Yes — if rejected, the associated Investment Measure typically cannot proceed with capital spending, since the Appropriation Request is the required approval gate before that spending is authorized.', type: 'conceptual' },
      { q: 'What is the relationship between Results Analysis (project-level) and the Results Analysis Key from CO Day 8?', a: 'Project-level Results Analysis for revenue recognition purposes uses the same underlying results analysis mechanism (Key, Version, valuation method) introduced for WIP/variance calculation on standard cost objects, just applied at the project level.', type: 'conceptual' },
      { q: 'What is a Wage Type in HCM payroll?', a: 'The specific category of pay or deduction (e.g. base salary, overtime, health insurance deduction) that payroll calculates, each of which needs its own mapping to a symbolic account for G/L posting.', type: 'conceptual' },
      { q: 'What happens if a new Wage Type is introduced without a corresponding symbolic account mapping?', a: 'The payroll posting run would fail or misroute that wage type\'s amount, since the symbolic account → G/L account mapping is the mechanism that translates every wage type into a correct FI posting.', type: 'conceptual' },
      { q: 'Can Travel Management postings be account-assigned to a WBS element the same way purchasing/sales can?', a: 'Yes, in principle — travel expenses can be account-assigned to relevant cost objects including WBS elements, following a similar integration pattern to how purchasing/sales account assignment works for projects.', type: 'conceptual' },
      { q: 'What is the difference between capital budgeting at the Investment Program level versus at an individual WBS/order level?', a: 'Investment Program-level budgeting provides top-down oversight across multiple capital initiatives; individual WBS/order-level budgeting (mirroring CO Day 5\'s availability control) governs spending against that specific project\'s own allocated budget.', type: 'conceptual' },
      { q: 'What does it mean that Investment Management is described as adding "a broader governance layer" over standard Internal Order budgeting?', a: 'It layers formal capital planning and approval processes (Investment Program, Appropriation Requests) on top of the same underlying budgeting/availability control mechanics, adding organizational governance without replacing the technical CO Day 5 foundation.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client is deciding between an Internal Order and a WBS/Project for a capital initiative.', a: 'WBS/Project structures suit multi-year, multi-deliverable work better; Internal Orders fit simpler, shorter-lived needs — the choice should follow project complexity, not default habit.', type: 'scenario' },
      { q: 'How does availability control differ between IM/PS and standard Internal Orders?', a: 'IM/PS availability control operates within the broader governance of Investment Programs and Appropriation Requests, adding a capital-approval gate Internal Orders don\'t inherently require.', type: 'conceptual' },
      { q: 'Auditor asks the single core question for mapping HCM payroll into FI/CO correctly.', a: 'How each wage type maps to a G/L account via its symbolic account — this is the core payroll integration question.', type: 'conceptual' },
      { q: 'A project\'s cost needs to split between a Fixed Asset and a Cost Center receiver.', a: 'Configure Distribution Rules within the Settlement Rule specifying the split, mirroring the CO Day 5 multi-receiver settlement mechanics.', type: 'scenario' },
      { q: 'Client wants a large capital initiative broken into multiple smaller Investment Measures but tracked together for overall capital governance.', a: 'Use an Investment Program to group the multiple Investment Measures — this provides consolidated capital budgeting and approval oversight while still allowing each individual measure to be managed and settled independently.', type: 'scenario' },
      { q: 'A project\'s purchase order account-assigned to a WBS element posts cost to an unexpected place.', a: 'Verify the account assignment on the PO line item genuinely points to the intended WBS element and that the WBS itself is correctly configured as a true CO object able to receive real cost — a misdirected account assignment or a WBS still configured as statistical would explain unexpected cost routing.', type: 'troubleshooting' },
      { q: 'Client\'s project revenue recognition inconsistency (from earlier discussion) is traced specifically to a mismatched RA Version between two similar projects.', a: 'Align the RA Version and valuation method configuration across comparable projects unless there\'s a deliberate reason for divergence — since project-level Results Analysis reuses the same RA Key/Version mechanism as CO Day 8, inconsistent configuration across similar projects produces inconsistent recognized revenue for comparable circumstances.', type: 'troubleshooting' },
      { q: 'An Appropriation Request for a capital project is rejected after the Investment Measure had already begun accumulating some preliminary costs.', a: 'Determine the disposition of the already-accumulated preliminary costs — depending on company policy, these may need to be written off, reallocated to a different cost object, or the rejection itself may need to be revisited if the preliminary spend was genuinely necessary and pre-approved separately.', type: 'scenario' },
      { q: 'Auditor asks how the system prevents payroll from posting a new wage type to the wrong G/L account after a compensation plan change.', a: 'Confirm the symbolic account mapping was updated for the new/changed wage type before the first payroll run using it — if a new wage type lacks a proper mapping, the posting run itself should fail or flag the gap rather than silently posting to an incorrect or default account.', type: 'conceptual' },
      { q: 'Client wants to know whether their WBS-based project structure could have been simpler as an Internal Order instead.', a: 'Revisit the original WBS vs Internal Order decision criteria — if the project turned out to be single-year, single-deliverable, and didn\'t need multiple purchasing/sales account assignment points, an Internal Order likely would have sufficed; this is worth an honest retrospective for future project structuring decisions, though converting an existing WBS project mid-life is a significant undertaking.', type: 'scenario' },
      { q: 'Auditor asks for evidence that Investment Program-level capital budgets are being respected by the individual Investment Measures within it.', a: 'Pull the Investment Program\'s aggregate budget alongside the sum of individual Investment Measure budgets/actuals within it, confirming the individual measures collectively stay within (or properly escalate exceptions to) the program-level capital allocation.', type: 'conceptual' },
      { q: 'Client\'s travel expense postings aren\'t appearing on the project cost report they expected them to feed into.', a: 'Check whether the travel expense entries were actually account-assigned to the relevant WBS element at entry time — travel postings follow a similar account-assignment pattern to purchasing/sales, but if the traveler didn\'t specify the WBS assignment, the cost would default elsewhere rather than automatically landing on the project.', type: 'troubleshooting' },
      { q: 'Client asks whether HCM payroll integration requires the same derivation-chain thinking (document entry → default → substitution) used elsewhere in CO.', a: 'Payroll posting is somewhat more direct — the symbolic account → G/L account mapping is the primary mechanism, though cost center distribution of personnel costs does draw on standard CO cost object assignment logic similar in spirit to the broader derivation concepts used throughout the module.', type: 'conceptual' },
      { q: 'Auditor asks how the client ensures WBS elements account-assigned from both purchasing and sales don\'t create a reconciliation gap between project cost and project revenue.', a: 'Since both purchasing and sales account assignments post to the same WBS element (a true CO object), project-level reporting can directly compare accumulated cost against accumulated revenue on that single object — this structural design is what prevents the kind of reconciliation gap that might arise if cost and revenue were tracked on entirely separate, unlinked objects.', type: 'conceptual' },
      { q: 'Client wants their capital project settlement to feed both asset capitalization and a separate cost center for departmental oversight, matching an earlier discussed scenario, but now with Investment Program governance layered on top.', a: 'The settlement mechanics remain the same (Settlement Rule with Distribution Rules splitting between AuC/Fixed Asset and Cost Center receivers) — Investment Program governance adds an approval/oversight layer before and during the project\'s life but doesn\'t change the underlying CO Day 5 settlement configuration needed to achieve the multi-receiver split.', type: 'conceptual' },
    ],
  },
  'int-6': {
    junior: [
      { q: 'Is Central Finance a data migration path?', a: 'No — it is a reporting/central-processing deployment option that replicates data from source systems, not itself a migration path.', type: 'conceptual' },
      { q: 'What tool replicates data near-real-time into Central Finance?', a: 'SAP Landscape Transformation (SLT).', type: 'conceptual' },
      { q: 'What does S/4HANA for Group Reporting replace?', a: 'BCS and BPC as the consolidation direction.', type: 'conceptual' },
      { q: 'What identifies the counter-entity for intercompany elimination?', a: 'Trading Partner.', type: 'conceptual' },
      { q: 'What is the standard S/4 migration tool, and what does it replace?', a: 'Migration Cockpit (LTMC/LTMOM), replacing the now-deprecated LSMW for S/4 migration.', type: 'conceptual' },
      { q: 'What are the three S/4 conversion strategy options?', a: 'Greenfield, Brownfield, and Bluefield/Selective Data Transition.', type: 'conceptual' },
      { q: 'What is MDG (Master Data Governance) used for specifically in a Central Finance context?', a: 'Harmonizing master data mappings (e.g. reconciling different customer/vendor/G/L account codes) across the multiple heterogeneous source systems replicating into Central Finance.', type: 'conceptual' },
      { q: 'What is AIF (Application Interface Framework) used for?', a: 'Managing and surfacing replication errors within Central Finance data flows, giving a structured way to identify and resolve failed or problematic replicated documents.', type: 'conceptual' },
      { q: 'What is the difference between Document Replication and Re-Posting in Central Finance?', a: 'Replication preserves the source document\'s original detail as closely as possible; Re-Posting applies target-system logic (e.g. different account determination), potentially altering how the transaction is represented in the central system.', type: 'conceptual' },
      { q: 'What is a Consolidation Unit in Group Reporting?', a: 'The entity (typically a Company Code or a defined reporting unit) whose financial data is collected and consolidated as part of the group-level reporting structure.', type: 'conceptual' },
      { q: 'What is the Consolidation Chart of Accounts?', a: 'A common account structure used across all consolidation units in Group Reporting, into which each unit\'s local operating chart of accounts data is mapped for consistent group-level presentation.', type: 'conceptual' },
      { q: 'What does "matching & reconciliation" specifically refer to in Group Reporting?', a: 'The process of comparing intercompany transaction amounts recorded by both sides (buyer and seller entities) to identify and resolve discrepancies before elimination can occur cleanly.', type: 'conceptual' },
      { q: 'What is a Migration Object in the Migration Cockpit context?', a: 'A predefined category of data (e.g. G/L balances, customer master, open items) with its own specific migration template and validation rules within the Migration Cockpit tool.', type: 'conceptual' },
      { q: 'What is a Fit-to-Standard workshop in SAP Activate?', a: 'A structured session (in the Explore phase) where the client\'s business requirements are compared against S/4HANA\'s standard functionality, identifying genuine gaps requiring configuration or custom development versus requirements the standard system already satisfies.', type: 'conceptual' },
      { q: 'What is the difference between Greenfield and Brownfield conversion approaches?', a: 'Greenfield builds a clean new S/4 system from scratch with fresh configuration; Brownfield technically converts an existing ECC system in place, retaining existing configuration and historical data.', type: 'conceptual' },
      { q: 'What is Bluefield/Selective Data Transition?', a: 'A hybrid approach selectively migrating specific data/configuration from an existing system into a new S/4 environment, rather than a full clean rebuild (greenfield) or a full in-place conversion (brownfield).', type: 'conceptual' },
      { q: 'What is HSN/SAC classification in the context of India GST?', a: 'Harmonized System of Nomenclature / Services Accounting Code — standardized classification codes required on invoices to categorize goods/services for GST reporting purposes.', type: 'conceptual' },
      { q: 'What is a Business Place in the India localization context?', a: 'A sub-unit within a Company Code representing a specific registered location for GST purposes, since GST registration and reporting in India often needs to happen at a more granular level than the Company Code itself.', type: 'conceptual' },
    ],
    senior: [
      { q: 'Client proposes Central Finance as their primary migration strategy to avoid a data migration project.', a: 'Push back — Central Finance is a reporting/central-processing deployment, not a migration path; it replicates data for unified reporting but doesn\'t migrate/replace source systems\' processing.', type: 'scenario' },
      { q: 'Client is planning a brownfield conversion and asks about FICO-specific prerequisites.', a: 'Business Partner conversion, New Asset Accounting activation, Material Ledger activation, and CVI setup are the key FICO-specific brownfield prerequisites.', type: 'conceptual' },
      { q: 'Post-cutover balance validation reveals a discrepancy between legacy and migrated balances.', a: 'Systematically trace the migration sequence — master data, open items, G/L balances, asset takeover, cost object balances — to find which object introduced the discrepancy.', type: 'troubleshooting' },
      { q: 'Client operating in India asks what localization-specific configuration is required beyond standard tax setup.', a: 'GST-specific tax procedure configuration, Business Place setup, HSN/SAC classification, TDS, and e-invoicing compliance as part of the India country-version framework.', type: 'conceptual' },
      { q: 'Client\'s Central Finance replication is failing for a subset of documents from one source system.', a: 'Use AIF to investigate the specific replication errors for that source system\'s document flow — AIF is built exactly to surface and help resolve this kind of failed/problematic replication, rather than requiring manual database-level investigation.', type: 'troubleshooting' },
      { q: 'Client wants Central Finance to preserve exact source-system account determination logic rather than reapplying S/4 target-system rules.', a: 'Configure Document Replication (preserving source detail) rather than Re-Posting (applying target-system logic) — this choice directly determines whether the central system mirrors the source\'s original determination or recalculates it under S/4 rules.', type: 'scenario' },
      { q: 'Client\'s intercompany elimination in Group Reporting shows unresolved discrepancies between two consolidation units.', a: 'Run matching & reconciliation specifically for the intercompany transactions between those two units — discrepancies here (before elimination) typically stem from timing differences or genuinely mismatched recorded amounts on each side, which must be resolved before elimination can proceed cleanly.', type: 'troubleshooting' },
      { q: 'Client asks whether their existing BPC-based consolidation reports can be directly ported to Group Reporting.', a: 'Not directly — Group Reporting has its own data model and reporting structure (Consolidation Units, Consolidation Chart of Accounts) distinct from BPC, so existing BPC reports need to be rebuilt or adapted for Group Reporting rather than assumed to migrate as-is.', type: 'conceptual' },
      { q: 'A brownfield conversion project discovers the existing ECC system never activated Material Ledger.', a: 'Material Ledger activation is one of the required FICO brownfield prerequisites — this gap must be addressed as part of the conversion project, since Material Ledger is mandatory in S/4 regardless of whether the source ECC system had it active.', type: 'troubleshooting' },
      { q: 'Client is deciding between Greenfield and Bluefield for a conversion project with significant historical data value but outdated configuration.', a: 'Bluefield/Selective Data Transition may be the better fit — it allows selectively bringing forward valuable historical data while leaving behind outdated configuration that a full Greenfield rebuild would discard anyway, striking a middle ground between the two extremes.', type: 'scenario' },
      { q: 'Client asks how HSN/SAC classification interacts with the general tax procedure concepts from FI-11.', a: 'HSN/SAC codes provide the specific goods/services classification required on Indian GST invoices, working alongside (not replacing) the general condition-based tax procedure mechanics from FI-11 — the tax procedure calculates the amount, while HSN/SAC ensures correct statutory classification for reporting.', type: 'conceptual' },
      { q: 'Client operating multiple Business Places within one Company Code in India shows inconsistent GST reporting across them.', a: 'Verify each Business Place\'s GST registration details and tax procedure assignment are correctly and independently configured — since Business Place represents a distinct registered location for GST purposes, each needs complete and correct setup rather than assuming Company Code-level configuration automatically covers every Business Place within it.', type: 'troubleshooting' },
      { q: 'Auditor asks how MDG supports data quality specifically for a Central Finance deployment spanning five source ERP systems.', a: 'MDG harmonizes master data mappings (customer, vendor, G/L account codes) across the five heterogeneous systems, ensuring the same real-world entity is consistently represented in the central system regardless of which source system it originated from — without this, the same customer might appear as five different, unreconciled records centrally.', type: 'conceptual' },
      { q: 'Client\'s Fit-to-Standard workshop for a Central Finance project spent most of its time on local transactional process details rather than replication/mapping validation.', a: 'This suggests the workshop focus should be recalibrated — for a Central Finance deployment specifically, the higher-value focus is validating SLT/MDG replication rules and central reporting requirements, since Central Finance is fundamentally a data-consolidation and reporting deployment rather than a typical local transactional S/4 implementation.', type: 'conceptual' },
      { q: 'Client asks whether e-invoicing compliance for India affects their broader Central Finance or Group Reporting architecture.', a: 'E-invoicing is primarily a country-specific localization compliance requirement at the transactional level (invoice generation/reporting to the tax authority) and generally operates independently of the broader Central Finance replication or Group Reporting consolidation architecture, though the underlying transactional data it governs does eventually flow into both.', type: 'conceptual' },
      { q: 'Auditor asks for evidence that a Bluefield/Selective Data Transition conversion correctly balanced legacy data value against configuration modernization.', a: 'Review the project\'s data selection criteria documenting which historical data was deliberately carried forward versus which configuration was deliberately rebuilt fresh, along with validation that the selectively transitioned data reconciles correctly against the legacy source — this documented rationale and reconciliation is the evidence of a deliberate, well-managed hybrid approach rather than an ad hoc mix.', type: 'conceptual' },
    ],
  },
};

